  select 'Según el artículo 83 de la Constitución, las leyes de bases no podrán en ningún caso:', 'El art. 83 CE prohíbe que las leyes de bases autoricen la modificación de la propia ley de bases o faculten para dictar normas retroactivas; los demás contenidos los permiten o exigen los apartados 3, 4 y 6 del art. 82.', 'age_adm_31_fuentes', (select id from public.topics where slug = 'age-adm-31-fuentes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 83 CE', 'Las leyes de bases no podrán en ningún caso: a) Autorizar la modificación de la propia ley de bases. b) Facultar para dictar normas con carácter retroactivo.', null, '23cfcc29527574fbfb76ab58c186b47eb9b6f5110e4692d247012d1a8c57b9d2', false
