  select 'Un centro directivo tramita un proyecto de real decreto que afecta a los derechos de los ciudadanos y quiere acortar el trámite de audiencia e información públicas por razones debidamente motivadas. Según el artículo 26 de la Ley 50/1997, ¿hasta qué plazo mínimo puede reducirlo?', 'El art. 26.6 de la Ley 50/1997 fija un plazo mínimo de 15 días hábiles, reducible hasta un mínimo de siete días hábiles cuando razones debidamente motivadas lo justifiquen o se aplique la tramitación urgente; debe dejarse constancia en la Memoria del Análisis de Impacto Normativo.', 'age_adm_31_fuentes', (select id from public.topics where slug = 'age-adm-31-fuentes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336'), 'Art. 26.6 LG', 'El plazo mínimo de esta audiencia e información públicas será de 15 días hábiles, y podrá ser reducido hasta un mínimo de siete días hábiles cuando razones debidamente motivadas así lo justifiquen', null, '4165f7b2cf31289ad67d56d60f80d82e49a56c70d28e73b63c95bb45cfeb734b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4165f7b2cf31289ad67d56d60f80d82e49a56c70d28e73b63c95bb45cfeb734b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Diez días hábiles.', false), ('B', 'Cinco días naturales.', false), ('C', 'Siete días hábiles.', true), ('D', 'Quince días naturales.', false)) as v(label, body, ok)
)
