with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 25 de la Ley 50/1997, el Ministro de la Presidencia elevará el Plan Anual Normativo al Consejo de Ministros para su aprobación:', 'El art. 25.4 de la Ley 50/1997 atribuye la coordinación del Plan al Ministerio de la Presidencia y fija como límite para su elevación el 30 de abril; el Plan recoge las iniciativas que se elevarán en el año siguiente.', 'age_adm_31_fuentes', (select id from public.topics where slug = 'age-adm-31-fuentes'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336'), 'Art. 25.4 LG', 'El Ministro de la Presidencia elevará el Plan al Consejo de Ministros para su aprobación antes del 30 de abril.', null, '03125d5708775884470c30b6b27ca73c44f6d91c976cb8918b7ab669ebeaebc8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '03125d5708775884470c30b6b27ca73c44f6d91c976cb8918b7ab669ebeaebc8')
  returning id
), o as (
