with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 23 de la Ley 50/1997, las disposiciones de entrada en vigor de los reglamentos aprobados por el Gobierno que impongan nuevas obligaciones a quienes desempeñen una actividad económica o profesional preverán el comienzo de su vigencia:', 'El art. 23 de la Ley 50/1997 fija esas dos fechas, salvo para los reales decretos-leyes o cuando la transposición de directivas u otras razones justificadas lo aconsejen, lo que debe acreditarse en la Memoria.', 'age_adm_31_fuentes', (select id from public.topics where slug = 'age-adm-31-fuentes'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336'), 'Art. 23 LG', 'las disposiciones de entrada en vigor de las leyes o reglamentos, cuya aprobación o propuesta corresponda al Gobierno o a sus miembros, y que impongan nuevas obligaciones a las personas físicas o jurídicas que desempeñen una actividad económica o profesional como consecuencia del ejercicio de ésta, preverán el comienzo de su vigencia el 2 de enero o el 1 de julio siguientes a su aprobación.', null, '662cd86a36f43d1855c6636e92b4cd415bab3d16e077f1e0b802cd939eb43144', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '662cd86a36f43d1855c6636e92b4cd415bab3d16e077f1e0b802cd939eb43144')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A los veinte días de su completa publicación en el «Boletín Oficial del Estado».', false), ('B', 'El 2 de enero o el 1 de julio siguientes a su aprobación.', true), ('C', 'El 1 de enero del año siguiente a su aprobación.', false), ('D', 'Al día siguiente de su publicación en el «Boletín Oficial del Estado».', false)) as v(label, body, ok)
)
