insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-31-fuentes', 'III.1 Las fuentes del derecho administrativo. La ley, el decreto-ley, el decreto legislativo y el reglamento') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-31-fuentes' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa, los Juzgados y Tribunales de este orden conocerán de las pretensiones que se deduzcan en relación con los Decretos legislativos:', 'El art. 1.1 LJCA atribuye a la jurisdicción contencioso-administrativa el control de las disposiciones generales de rango inferior a la ley y de los Decretos legislativos cuando excedan los límites de la delegación (lo que el art. 82.6 CE llama «competencia propia de los Tribunales»).', 'age_adm_31_fuentes', (select id from public.topics where slug = 'age-adm-31-fuentes'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 1.1 LJCA', 'con las disposiciones generales de rango inferior a la Ley y con los Decretos legislativos cuando excedan los límites de la delegación.', null, '2e30a710a893f66c67b4ed03be1d8019bd350c7879c0f33fcc121aa5e7e03d84', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2e30a710a893f66c67b4ed03be1d8019bd350c7879c0f33fcc121aa5e7e03d84')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuando excedan los límites de la delegación.', true), ('B', 'En todo caso, al tratarse de disposiciones del Gobierno.', false), ('C', 'Solo cuando hayan sido convalidados por el Congreso de los Diputados.', false), ('D', 'En ningún caso, pues su control corresponde exclusivamente al Tribunal Constitucional.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una asociación no impugnó en plazo un real decreto que considera ilegal. Ahora un órgano administrativo le aplica ese real decreto en un acto concreto. Según el artículo 26 de la Ley 29/1998, ¿puede recurrir el acto alegando la ilegalidad del real decreto?', 'El art. 26 LJCA admite el recurso indirecto contra reglamentos: se puede impugnar el acto de aplicación fundándose en que la disposición no es conforme a Derecho, aunque esta no se recurriera directamente o se desestimara el recurso directo. Además, contra las disposiciones generales no cabe recurso en vía administrativa (art. 112.3 LPAC).', 'age_adm_31_fuentes', (select id from public.topics where slug = 'age-adm-31-fuentes'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 26.2 LJCA', 'también es admisible la de los actos que se produzcan en aplicación de las mismas, fundada en que tales disposiciones no son conformes a Derecho. […] 2. La falta de impugnación directa de una disposición general o la desestimación del recurso que frente a ella se hubiera interpuesto no impiden la impugnación de los actos de aplicación con fundamento en lo dispuesto en el apartado anterior.', null, '26f8976487c0ab755dc022c4095e1f92dce6fd311df4bc70c4e1e58e50b90713', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '26f8976487c0ab755dc022c4095e1f92dce6fd311df4bc70c4e1e58e50b90713')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No, porque la disposición general ha devenido firme y consentida.', false), ('B', 'Solo si antes interpone recurso de reposición contra el real decreto.', false), ('C', 'Solo mediante recurso de inconstitucionalidad ante el Tribunal Constitucional.', false), ('D', 'Sí, porque la falta de impugnación directa de la disposición general no impide impugnar sus actos de aplicación por no ser aquella conforme a Derecho.', true)) as v(label, body, ok)
)
