insert into public.topics (slug, title) values ('age-adm-31-fuentes', 'III.1 Las fuentes del derecho administrativo. La ley, el decreto-ley, el decreto legislativo y el reglamento') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-31-fuentes' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 128 de la Ley 39/2015, sin perjuicio de su función de desarrollo o colaboración con respecto a la ley, los reglamentos y disposiciones administrativas no podrán:', 'El art. 128.2 LPAC impide a los reglamentos tipificar delitos, faltas o infracciones administrativas, establecer penas o sanciones, tributos, exacciones parafiscales u otras prestaciones patrimoniales de carácter público; el art. 128.1 reconoce potestad reglamentaria a los órganos de gobierno locales.', 'age_adm_31_fuentes', (select id from public.topics where slug = 'age-adm-31-fuentes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 128.2 LPAC', 'Sin perjuicio de su función de desarrollo o colaboración con respecto a la ley, no podrán tipificar delitos, faltas o infracciones administrativas, establecer penas o sanciones, así como tributos, exacciones parafiscales u otras cargas o prestaciones personales o patrimoniales de carácter público.', null, '23c1566317bc677875e530e8fd1653e55f1f4231a7836aab1103e34d928f7ddd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '23c1566317bc677875e530e8fd1653e55f1f4231a7836aab1103e34d928f7ddd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Regular la organización interna de los órganos administrativos.', false), ('B', 'Tipificar infracciones administrativas ni establecer sanciones.', true), ('C', 'Desarrollar los procedimientos previstos en una ley.', false), ('D', 'Ser aprobados por los órganos de gobierno locales.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 129 de la Ley 39/2015, ¿cuál de los siguientes NO figura entre los principios de buena regulación a los que deben ajustarse las Administraciones Públicas en el ejercicio de la iniciativa legislativa y la potestad reglamentaria?', 'El art. 129.1 LPAC enumera necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia; la jerarquía es un principio de organización administrativa (art. 103.1 CE), no de buena regulación.', 'age_adm_31_fuentes', (select id from public.topics where slug = 'age-adm-31-fuentes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 129.1 LPAC', 'En el ejercicio de la iniciativa legislativa y la potestad reglamentaria, las Administraciones Públicas actuarán de acuerdo con los principios de necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia, y eficiencia.', null, 'b0ab3083dac3f36427a3bf25e9b6979f421ef02840538edf5299578566d0b91d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b0ab3083dac3f36427a3bf25e9b6979f421ef02840538edf5299578566d0b91d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Proporcionalidad.', false), ('B', 'Seguridad jurídica.', false), ('C', 'Jerarquía.', true), ('D', 'Eficiencia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 131 de la Ley 39/2015, para que las normas con rango de ley, los reglamentos y las disposiciones administrativas entren en vigor y produzcan efectos jurídicos:', 'El art. 131 LPAC exige la publicación en el diario oficial correspondiente; otros medios de publicidad son solo complementarios y facultativos.', 'age_adm_31_fuentes', (select id from public.topics where slug = 'age-adm-31-fuentes'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 131 LPAC', 'Las normas con rango de ley, los reglamentos y disposiciones administrativas habrán de publicarse en el diario oficial correspondiente para que entren en vigor y produzcan efectos jurídicos.', null, 'f71c6db735d6e667d6aea8a92ed5035795c4c1d6afb8a7c2f4ca3dc3809870bd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f71c6db735d6e667d6aea8a92ed5035795c4c1d6afb8a7c2f4ca3dc3809870bd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Basta con su aprobación por el órgano competente.', false), ('B', 'Deben notificarse individualmente a los interesados.', false), ('C', 'Basta con su publicación en el Portal de la Transparencia.', false), ('D', 'Habrán de publicarse en el diario oficial correspondiente.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un Ministro aprueba una Orden ministerial que regula con carácter general los requisitos de unas autorizaciones. Meses después, el mismo Ministro dicta una resolución particular que concede una autorización a una empresa sin exigirle uno de esos requisitos. Según la Ley 39/2015, esa resolución es:', 'El art. 37 LPAC (inderogabilidad singular de los reglamentos) impide que las resoluciones particulares vulneren una disposición general aunque procedan de un órgano de igual o superior jerarquía, y declara nulas las que vulneren una disposición reglamentaria.', 'age_adm_31_fuentes', (select id from public.topics where slug = 'age-adm-31-fuentes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 37 LPAC', 'Las resoluciones administrativas de carácter particular no podrán vulnerar lo establecido en una disposición de carácter general, aunque aquéllas procedan de un órgano de igual o superior jerarquía al que dictó la disposición general. […] 2. Son nulas las resoluciones administrativas que vulneren lo establecido en una disposición reglamentaria', null, '6facac4c1235d98ab2c9e8b8e4784790480e28df13274140fbdcb51e3e64a661', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6facac4c1235d98ab2c9e8b8e4784790480e28df13274140fbdcb51e3e64a661')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Válida, porque procede del mismo órgano que aprobó la disposición general.', false), ('B', 'Válida, siempre que esté debidamente motivada.', false), ('C', 'Nula, porque las resoluciones particulares no pueden vulnerar una disposición general aunque procedan del mismo órgano.', true), ('D', 'Anulable solo si algún interesado la recurre en el plazo de un mes.', false)) as v(label, body, ok)
)
