select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
-- Lote age-adm-32-acto-administrativo-lpac-v1 (20 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-32-acto-administrativo', 'III.2 El acto administrativo: concepto, clases, elementos, eficacia, validez, motivación y notificación') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-32-acto-administrativo' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 35 de la Ley 39/2015, ¿cuál de los siguientes actos debe ser motivado, con sucinta referencia de hechos y fundamentos de derecho?', 'El art. 35.1.c) LPAC exige motivar los actos que se separen del criterio seguido en actuaciones precedentes o del dictamen de órganos consultivos. La ley exige motivar el rechazo de pruebas (letra f), no su admisión.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 35.1.c) LPAC', 'c) Los actos que se separen del criterio seguido en actuaciones precedentes o del dictamen de órganos consultivos.', null, '1fb9a4ae1bde2cf56fe17c086a12d01039ffcb0a045286a263b89545aee9eb01', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1fb9a4ae1bde2cf56fe17c086a12d01039ffcb0a045286a263b89545aee9eb01')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El que acuerde la apertura de un período de prueba solicitado por el interesado.', false), ('B', 'El que estime íntegramente una solicitud reglada.', false), ('C', 'El que se separe del criterio seguido en actuaciones precedentes.', true), ('D', 'El acuse de recibo de una solicitud presentada en el registro.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 35 de la Ley 39/2015, el acto del instructor que rechaza las pruebas propuestas por un interesado:', 'El art. 35.1.f) LPAC incluye entre los actos que deben motivarse los que rechacen pruebas propuestas por los interesados, sin distinguir el tipo de procedimiento.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 35.1.f) LPAC', 'Serán motivados, con sucinta referencia de hechos y fundamentos de derecho: […] f) Los actos que rechacen pruebas propuestas por los interesados.', null, '8c7182aa7fa7b57f44c4fe31983deb367f0348847aee4dbd1b299a6645e4e951', false
