  select 'Según el artículo 36 de la Ley 39/2015, los actos administrativos se producirán:', 'El art. 36.1 LPAC establece como regla la forma escrita a través de medios electrónicos, salvo que la naturaleza del acto exija otra forma más adecuada.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 36.1 LPAC', 'Los actos administrativos se producirán por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada de expresión y constancia.', null, 'f1fe5d3cce1912d04f9eabeb317ae3f2fda3c43e79b10bb53f7d998b0aad8282', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f1fe5d3cce1912d04f9eabeb317ae3f2fda3c43e79b10bb53f7d998b0aad8282')
