with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 39.3 de la Ley 39/2015, podrá otorgarse excepcionalmente eficacia retroactiva a los actos administrativos:', 'El art. 39.3 LPAC admite la retroactividad en esos dos supuestos, siempre que los supuestos de hecho existieran ya en la fecha a la que se retrotraiga la eficacia y no se lesionen derechos o intereses legítimos de otras personas.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 39.3 LPAC', 'Excepcionalmente, podrá otorgarse eficacia retroactiva a los actos cuando se dicten en sustitución de actos anulados, así como cuando produzcan efectos favorables al interesado, siempre que los supuestos de hecho necesarios existieran ya en la fecha a que se retrotraiga la eficacia del acto y ésta no lesione derechos o intereses legítimos de otras personas.', null, 'ee30f18a8cc7ea166537c71addf7e50521642cb1cb56a942c346acb77382fcc0', false
