with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un empleado público intenta entregar una notificación en papel en el domicilio de un interesado a las 11:00 y no hay nadie que se haga cargo de ella. Según el artículo 42 de la Ley 39/2015, el segundo intento:', 'El art. 42.2 LPAC exige repetir el intento una sola vez, en hora distinta y dentro de los tres días siguientes; si el primero fue antes de las quince horas, el segundo será después, con un margen mínimo de tres horas. Si también fracasa, se acude al anuncio del art. 44.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 42.2 LPAC', 'intento que se repetirá por una sola vez y en una hora distinta dentro de los tres días siguientes. En caso de que el primer intento de notificación se haya realizado antes de las quince horas, el segundo intento deberá realizarse después de las quince horas y viceversa, dejando en todo caso al menos un margen de diferencia de tres horas entre ambos intentos de notificación.', null, '142be9d0e408824b5b2bea9558cb9fd0e463b88ae1bd696bf0c366e0877ec616', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '142be9d0e408824b5b2bea9558cb9fd0e463b88ae1bd696bf0c366e0877ec616')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se realizará al día siguiente a la misma hora que el primero.', false), ('B', 'No es necesario: se publicará directamente un anuncio en el «Boletín Oficial del Estado».', false), ('C', 'Se realizará dentro de los tres días siguientes, después de las quince horas y con al menos tres horas de diferencia respecto del primero.', true), ('D', 'Se realizará dentro de los diez días siguientes, en cualquier franja horaria.', false)) as v(label, body, ok)
)
