with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 44 de la Ley 39/2015, cuando los interesados en un procedimiento sean desconocidos o se ignore el lugar de la notificación, esta se hará por medio de un anuncio publicado en:', 'El art. 44 LPAC exige siempre el anuncio en el BOE; el boletín autonómico o provincial, el tablón de edictos del Ayuntamiento o el del Consulado son publicaciones previas y facultativas.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 44 LPAC', 'Cuando los interesados en un procedimiento sean desconocidos, se ignore el lugar de la notificación o bien, intentada ésta, no se hubiese podido practicar, la notificación se hará por medio de un anuncio publicado en el «Boletín Oficial del Estado».', null, '4f0a3987dfee32948fce15a51445055338b93e41407777975e8fa359aadd13ed', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4f0a3987dfee32948fce15a51445055338b93e41407777975e8fa359aadd13ed')
