with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un proceso selectivo, la convocatoria indica que las listas de aprobados se publicarán en la sede electrónica del Ministerio. Una unidad publica una de esas listas solo en el tablón físico de anuncios del edificio. Según el artículo 45 de la Ley 39/2015, esa publicación:', 'El art. 45.1.b) LPAC dispone que en los procedimientos selectivos o de concurrencia competitiva la convocatoria indicará el medio de las sucesivas publicaciones, careciendo de validez las que se lleven a cabo en lugares distintos.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 45.1.b) LPAC', 'b) Cuando se trate de actos integrantes de un procedimiento selectivo o de concurrencia competitiva de cualquier tipo. En este caso, la convocatoria del procedimiento deberá indicar el medio donde se efectuarán las sucesivas publicaciones, careciendo de validez las que se lleven a cabo en lugares distintos.', null, '81c82833d6ecdcd99ac16e58a0a95e823d4fb62838c9efee1f7c15e4d5864bab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '81c82833d6ecdcd99ac16e58a0a95e823d4fb62838c9efee1f7c15e4d5864bab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
