with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 46 de la Ley 39/2015, si el órgano competente aprecia que la publicación de un acto lesiona derechos o intereses legítimos:', 'El art. 46 LPAC prevé la publicación de una somera indicación del contenido y del lugar y plazo para comparecer, con constancia del conocimiento del contenido íntegro.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 46 LPAC', 'Si el órgano competente apreciase que la notificación por medio de anuncios o la publicación de un acto lesiona derechos o intereses legítimos, se limitará a publicar en el Diario oficial que corresponda una somera indicación del contenido del acto y del lugar donde los interesados podrán comparecer, en el plazo que se establezca, para conocimiento del contenido íntegro del mencionado acto y constancia de tal conocimiento.', null, '8c44d357b117e236b10f0a7bae13c11b9ed0836c5df7b1c292b98acf17b276be', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8c44d357b117e236b10f0a7bae13c11b9ed0836c5df7b1c292b98acf17b276be')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se abstendrá de publicarlo y lo notificará únicamente por correo certificado.', false), ('B', 'Publicará el acto íntegro, pero anonimizando el nombre del órgano que lo dictó.', false), ('C', 'Se limitará a publicar en el diario oficial una somera indicación del contenido del acto y del lugar donde los interesados podrán comparecer para conocer su contenido íntegro.', true), ('D', 'Deberá solicitar autorización judicial antes de publicarlo.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 47 de la Ley 39/2015, es nulo de pleno derecho el acto administrativo:', 'El art. 47.1.b) LPAC sanciona con nulidad la incompetencia manifiesta por razón de materia o territorio; la desviación de poder y las demás infracciones del ordenamiento son causa de anulabilidad (art. 48.1), y la actuación fuera de plazo solo anula si lo impone la naturaleza del término (art. 48.3).', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 47.1 LPAC', 'b) Los dictados por órgano manifiestamente incompetente por razón de la materia o del territorio.', null, 'b1b51e1755318820cb65ffb19b07028f0d003b0fa05e8af932e8429f026225a4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b1b51e1755318820cb65ffb19b07028f0d003b0fa05e8af932e8429f026225a4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dictado por órgano manifiestamente incompetente por razón de la materia o del territorio.', true), ('B', 'Dictado por órgano incompetente por razón de la jerarquía.', false), ('C', 'Que incurre en desviación de poder.', false), ('D', 'Dictado fuera del plazo establecido, en todo caso.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 48 de la Ley 39/2015, el defecto de forma de un acto administrativo:', 'El art. 48.2 LPAC limita la anulabilidad por defecto de forma a los casos en que el acto carezca de los requisitos formales indispensables para su fin o cause indefensión. La regla general (art. 48.1) es la anulabilidad por cualquier infracción del ordenamiento, incluida la desviación de poder.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 48.2 LPAC', 'No obstante, el defecto de forma sólo determinará la anulabilidad cuando el acto carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados.', null, 'feb4fca429e624f64d78ee4030b176466c333796f545caeddf359c5d2da37675', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'feb4fca429e624f64d78ee4030b176466c333796f545caeddf359c5d2da37675')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Determina siempre la nulidad de pleno derecho del acto.', false), ('B', 'Determina siempre la anulabilidad del acto, sea cual sea su entidad.', false), ('C', 'Nunca afecta a la validez del acto, que solo puede corregirse de oficio.', false), ('D', 'Solo determinará la anulabilidad cuando el acto carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un órgano dicta un acto pocos días después de vencer el plazo previsto para ello en la norma, sin que dicho plazo tenga carácter esencial. Según el artículo 48 de la Ley 39/2015, el acto:', 'El art. 48.3 LPAC dispone que la actuación administrativa fuera de plazo solo implica la anulabilidad cuando así lo imponga la naturaleza del término o plazo.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 48.3 LPAC', 'La realización de actuaciones administrativas fuera del tiempo establecido para ellas sólo implicará la anulabilidad del acto cuando así lo imponga la naturaleza del término o plazo.', null, '48b39b63edc96888076d9e96f282a33b3b05adc4d91fd593e9bedc4730c5f548', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '48b39b63edc96888076d9e96f282a33b3b05adc4d91fd593e9bedc4730c5f548')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es nulo de pleno derecho por haberse dictado fuera de plazo.', false), ('B', 'Solo será anulable si así lo impone la naturaleza del término o plazo.', true), ('C', 'Es siempre anulable por haberse dictado fuera de plazo.', false), ('D', 'Es inexistente y no produce ningún efecto.', false)) as v(label, body, ok)
)
