with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 39/2015, los actos nulos o anulables que, sin embargo, contengan los elementos constitutivos de otro distinto producirán los efectos de este. ¿Cómo se denomina esta figura?', 'El art. 50 LPAC regula la conversión; la convalidación (art. 52) subsana vicios de actos anulables y la conservación (art. 51) mantiene los actos y trámites cuyo contenido no habría variado sin la infracción.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 50 LPAC', 'Los actos nulos o anulables que, sin embargo, contengan los elementos constitutivos de otro distinto producirán los efectos de éste.', null, 'dd66dae449b47c5c7f9560fce8fe494933404b225113f39791c88c31d31ca21f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'dd66dae449b47c5c7f9560fce8fe494933404b225113f39791c88c31d31ca21f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Convalidación.', false), ('B', 'Conservación de actos y trámites.', false), ('C', 'Conversión de actos viciados.', true), ('D', 'Revocación.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un Subdirector General dicta un acto anulable por incompetencia no determinante de nulidad, ya que la competencia correspondía a su Director General, que es su superior jerárquico. Según el artículo 52 de la Ley 39/2015:', 'El art. 52 LPAC permite convalidar los actos anulables; si el vicio es de incompetencia no determinante de nulidad, convalida el órgano competente cuando sea superior jerárquico del que dictó el acto, y la convalidación produce efecto desde su fecha salvo lo previsto en el art. 39.3.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 52.3 LPAC', 'El acto de convalidación producirá efecto desde su fecha, salvo lo dispuesto en el artículo 39.3 para la retroactividad de los actos administrativos. 3. Si el vicio consistiera en incompetencia no determinante de nulidad, la convalidación podrá realizarse por el órgano competente cuando sea superior jerárquico del que dictó el acto viciado.', null, '77979376e307278c7a7aebf37459f2116e86c71409ceb5d8c368635c9a4a2c98', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '77979376e307278c7a7aebf37459f2116e86c71409ceb5d8c368635c9a4a2c98')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Director General puede convalidar el acto, que producirá efecto desde la fecha de la convalidación, salvo los casos de retroactividad del artículo 39.3.', true), ('B', 'El acto no puede convalidarse y debe revisarse de oficio por nulidad.', false), ('C', 'Solo el Ministro puede convalidar el acto, con efectos desde la fecha en que se dictó.', false), ('D', 'El propio Subdirector General puede convalidarlo dictando un nuevo acto idéntico.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
