with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 98 de la Ley 39/2015, los actos de las Administraciones Públicas sujetos al Derecho Administrativo son inmediatamente ejecutivos, salvo, entre otros supuestos, cuando:', 'El art. 98.1 LPAC exceptúa la ejecutividad inmediata cuando se suspenda la ejecución, en resoluciones sancionadoras aún recurribles en vía administrativa, cuando una disposición establezca lo contrario o cuando se necesite aprobación o autorización superior.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 98.1 LPAC', 'b) Se trate de una resolución de un procedimiento de naturaleza sancionadora contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición.', null, 'ed1e372a7caccef73fdeaf2ca4fbe7cc85b3c3f5eaaff3609f712ffe9b09dfef', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ed1e372a7caccef73fdeaf2ca4fbe7cc85b3c3f5eaaff3609f712ffe9b09dfef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El interesado haya anunciado su intención de interponer recurso contencioso-administrativo.', false), ('B', 'Se trate de una resolución de un procedimiento sancionador contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición.', true), ('C', 'Se trate de un acto de gravamen dictado en un procedimiento iniciado a solicitud del interesado.', false), ('D', 'El acto no haya sido publicado en el diario oficial, aunque se haya notificado.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 112 de la Ley 39/2015, contra los actos de trámite podrán interponerse recursos de alzada y potestativo de reposición:', 'El art. 112.1 LPAC distingue los actos de trámite cualificados, que son recurribles, de los restantes, cuya oposición se alega para su consideración en la resolución que ponga fin al procedimiento.', 'age_adm_32_acto_administrativo', (select id from public.topics where slug = 'age-adm-32-acto-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 112.1 LPAC', 'Contra las resoluciones y los actos de trámite, si estos últimos deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, producen indefensión o perjuicio irreparable a derechos e intereses legítimos, podrán interponerse por los interesados los recursos de alzada y potestativo de reposición', null, 'd4710ac1046f6adfe866b14ec54c91ae22eaae0fcb7f16cae30d9994416f23ef', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd4710ac1046f6adfe866b14ec54c91ae22eaae0fcb7f16cae30d9994416f23ef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En todo caso, al ser actos administrativos sujetos a Derecho Administrativo.', false), ('B', 'En ningún caso: su oposición solo puede alegarse en el recurso contra la resolución final.', false), ('C', 'Solo cuando hayan sido dictados por un órgano colegiado.', false), ('D', 'Si deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento o producen indefensión o perjuicio irreparable a derechos e intereses legítimos.', true)) as v(label, body, ok)
)
