with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 15 de la Ley 9/2017, de Contratos del Sector Público, en el contrato de concesión de servicios el derecho de explotación de los servicios implicará:', 'El art. 15 LCSP define la concesión de servicios como la encomienda onerosa de la gestión de un servicio de titularidad o competencia del poder adjudicador, retribuida con el derecho a explotarlo (o ese derecho más un precio), lo que implica transferir al concesionario el riesgo operacional.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 15 LCSP', 'cuya contrapartida venga constituida bien por el derecho a explotar los servicios objeto del contrato o bien por dicho derecho acompañado del de percibir un precio. 2. El derecho de explotación de los servicios implicará la transferencia al concesionario del riesgo operacional', null, '12f3c71a8a7fd722aa9b72a4eb6761e6cbc37cdf1eaaf29e36ed8cd224838001', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '12f3c71a8a7fd722aa9b72a4eb6761e6cbc37cdf1eaaf29e36ed8cd224838001')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La transferencia al concesionario del riesgo operacional.', true), ('B', 'Que el poder adjudicador asuma íntegramente el riesgo de demanda.', false), ('C', 'La transmisión al concesionario de la titularidad del servicio.', false), ('D', 'Que la contrapartida consista únicamente en un precio fijo abonado por la Administración.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 25 de la Ley 9/2017, ¿cuál de los siguientes contratos celebrados por una Administración Pública tiene carácter privado?', 'El art. 25.1.a) LCSP atribuye carácter administrativo a los contratos de obras, concesión de obras, concesión de servicios, suministro y servicios celebrados por una Administración Pública, pero exceptúa, entre otros, los de suscripción a revistas, publicaciones periódicas y bases de datos, que son privados.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 25.1.a) LCSP', 'No obstante, tendrán carácter privado los siguientes contratos: […] 2.º Aquellos cuyo objeto sea la suscripción a revistas, publicaciones periódicas y bases de datos.', null, '5f52d58742c5c48666ec8ded1956dad46e3be8cd7e5d4cfcb67e1209babfcb3c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5f52d58742c5c48666ec8ded1956dad46e3be8cd7e5d4cfcb67e1209babfcb3c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El contrato de suministro de material de oficina.', false), ('B', 'El contrato de concesión de obras.', false), ('C', 'El contrato de servicios de limpieza de un edificio administrativo.', false), ('D', 'El que tenga por objeto la suscripción a revistas, publicaciones periódicas y bases de datos.', true)) as v(label, body, ok)
)
