  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 29 de la Ley 9/2017, con carácter general, los contratos de suministros y de servicios de prestación sucesiva tendrán un plazo máximo de duración de:', 'El art. 29.4 LCSP fija un máximo de cinco años, prórrogas incluidas, salvo la excepción ligada al período de recuperación de inversiones que debe justificarse en el expediente.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 29.4 LCSP', 'Los contratos de suministros y de servicios de prestación sucesiva tendrán un plazo máximo de duración de cinco años, incluyendo las posibles prórrogas', null, '27e93991bec95b8e5236b3e24036a535eaca3895c32d89a59430cc46fc4217a1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '27e93991bec95b8e5236b3e24036a535eaca3895c32d89a59430cc46fc4217a1')
