select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un contrato de servicios de mantenimiento prevé una prórroga. El órgano de contratación comunica al contratista su decisión de prorrogarlo tres meses antes de que finalice el plazo de duración, y el pliego no establece otro plazo de preaviso. Según el artículo 29 de la Ley 9/2017:', 'El art. 29.2 LCSP dispone que la prórroga la acuerda el órgano de contratación y es obligatoria para el empresario si el preaviso se produce al menos con dos meses de antelación (salvo plazo mayor del pliego); nunca cabe la prórroga tácita.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 29.2 LCSP', 'La prórroga se acordará por el órgano de contratación y será obligatoria para el empresario, siempre que su preaviso se produzca al menos con dos meses de antelación a la finalización del plazo de duración del contrato, salvo que en el pliego que rija el contrato se establezca uno mayor. […] En ningún caso podrá producirse la prórroga por el consentimiento tácito de las partes.', null, '955f26ed9e5c5c2acd8802121a71f211cf5fd8171744ee1cc4bb9b78eb9864eb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '955f26ed9e5c5c2acd8802121a71f211cf5fd8171744ee1cc4bb9b78eb9864eb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La prórroga solo es válida si el contratista la acepta expresamente.', false), ('B', 'La prórroga es obligatoria para el contratista, porque el preaviso se ha producido con al menos dos meses de antelación.', true), ('C', 'La prórroga no es posible, porque requiere un preaviso mínimo de seis meses.', false), ('D', 'La prórroga se entiende producida igualmente aunque no se comunique, por consentimiento tácito.', false)) as v(label, body, ok)
)
