  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 39 de la Ley 9/2017, además de las causas del artículo 47 de la Ley 39/2015, es causa de nulidad de pleno derecho de los contratos celebrados por poderes adjudicadores:', 'El art. 39.2.b) LCSP considera nulos los contratos con carencia o insuficiencia de crédito (salvo emergencia). El incumplimiento de los requisitos de modificación de los arts. 204 y 205 es causa de anulabilidad (art. 40.a).', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 39.2.b) LCSP', 'b) La carencia o insuficiencia de crédito, de conformidad con lo establecido en la Ley 47/2003, de 26 de noviembre, General Presupuestaria, o en las normas presupuestarias de las restantes Administraciones Públicas sujetas a esta Ley, salvo los supuestos de emergencia.', null, '20a0ed6cae3d892e0c2c74c989e2c8e54e5852540b4dbead78f3a4e82c80bee9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '20a0ed6cae3d892e0c2c74c989e2c8e54e5852540b4dbead78f3a4e82c80bee9')
  returning id
