with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 103 de la Ley 9/2017, salvo en los contratos de suministro de energía, la revisión periódica y predeterminada de precios tendrá lugar, cuando proceda, si el contrato se hubiese ejecutado al menos en:', 'El art. 103.5 LCSP excluye de la revisión el primer 20 % ejecutado y lo ejecutado en el primer año desde la formalización; la condición del porcentaje no se exige en las concesiones de servicios.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 103.5 LCSP', 'cuando el contrato se hubiese ejecutado, al menos, en el 20 por ciento de su importe y hubiese transcurrido un año desde su formalización. En consecuencia, el primer 20 por ciento ejecutado y el importe ejecutado en el primer año transcurrido desde la formalización quedarán excluidos de la revisión.', null, '4ff4beb181d5093887b9ef28fdc67f79fa61eae40e3b6ca6ee25acece4523bd7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4ff4beb181d5093887b9ef28fdc67f79fa61eae40e3b6ca6ee25acece4523bd7')
  returning id
), o as (
