  select 'Una unidad administrativa necesita contratar un servicio de traducción con un valor estimado de 14.000 euros. Según el artículo 118 de la Ley 9/2017, este contrato:', 'El art. 118.1 LCSP considera contratos menores los de valor estimado inferior a 40.000 euros en obras y a 15.000 euros en suministros o servicios.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 118.1 LCSP', 'Se consideran contratos menores los contratos de valor estimado inferior a 40.000 euros, cuando se trate de contratos de obras, o a 15.000 euros, cuando se trate de contratos de suministro o de servicios', null, 'f7c812e2888c3e1a27093423ee3e4d2ac79a477e605d3a538a2fd18a33819b63', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f7c812e2888c3e1a27093423ee3e4d2ac79a477e605d3a538a2fd18a33819b63')
