with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 131 de la Ley 9/2017, la adjudicación de los contratos de las Administraciones Públicas se realizará ordinariamente utilizando una pluralidad de criterios basados en la mejor relación calidad-precio y utilizando:', 'El art. 131.2 LCSP establece como ordinarios el abierto y el restringido; el negociado sin publicidad, el diálogo competitivo, la licitación con negociación y la asociación para la innovación solo caben en los supuestos tasados, y la adjudicación directa es propia de los contratos menores (art. 131.3).', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 131.2 LCSP', 'La adjudicación se realizará, ordinariamente utilizando una pluralidad de criterios de adjudicación basados en el principio de mejor relación calidad-precio, y utilizando el procedimiento abierto o el procedimiento restringido', null, '4b68ed659f77ebaac67dd7ca6d3161ce66f007133c15c421a5c297d40a4b6edc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4b68ed659f77ebaac67dd7ca6d3161ce66f007133c15c421a5c297d40a4b6edc')
  returning id
