with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 159 de la Ley 9/2017, para poder utilizar el procedimiento abierto simplificado, en los criterios de adjudicación previstos en el pliego no debe haber ninguno evaluable mediante juicio de valor o, de haberlos, su ponderación no debe superar, con carácter general:', 'El art. 159.1.b) LCSP fija el límite general del 25 %, que se eleva al 45 % cuando el contrato tenga por objeto prestaciones de carácter intelectual, como los servicios de ingeniería y arquitectura.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 159.1.b) LCSP', 'b) Que entre los criterios de adjudicación previstos en el pliego no haya ninguno evaluable mediante juicio de valor o, de haberlos, su ponderación no supere el veinticinco por ciento del total, salvo en el caso de que el contrato tenga por objeto prestaciones de carácter intelectual, como los servicios de ingeniería y arquitectura, en que su ponderación no podrá superar el cuarenta y cinco por ciento del total.', null, 'a96075958c77a297cf8c241cd108cd22b05abf6eead9e1db66410c372ac101f6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a96075958c77a297cf8c241cd108cd22b05abf6eead9e1db66410c372ac101f6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El cuarenta y cinco por ciento del total.', false), ('B', 'El cincuenta por ciento del total.', false), ('C', 'El diez por ciento del total.', false), ('D', 'El veinticinco por ciento del total.', true)) as v(label, body, ok)
)
