  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 150 de la Ley 9/2017, una vez aceptada la propuesta de la mesa por el órgano de contratación, se requerirá al licitador que haya presentado la mejor oferta para que presente la documentación justificativa dentro del plazo de:', 'El art. 150.2 LCSP concede diez días hábiles desde el día siguiente al requerimiento para acreditar, entre otros extremos, la disposición de medios y la constitución de la garantía definitiva.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 150.2 LCSP', 'requerirán al licitador que haya presentado la mejor oferta, de conformidad con lo dispuesto en el artículo 145 para que, dentro del plazo de diez días hábiles, a contar desde el siguiente a aquel en que hubiera recibido el requerimiento', null, '68a784ae00b33b5c7a68e02a2710f7b12e2e35aa26d26c6dca3b6dbf78172b22', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '68a784ae00b33b5c7a68e02a2710f7b12e2e35aa26d26c6dca3b6dbf78172b22')
  returning id
