  select 'Conforme al artículo 153 de la Ley 9/2017, si el contrato es susceptible de recurso especial en materia de contratación, la formalización no podrá efectuarse antes de que transcurran:', 'El art. 153.3 LCSP impone un plazo de espera de quince días hábiles (ampliable por las CCAA hasta un mes); después, el adjudicatario debe formalizar en un plazo no superior a cinco días desde el requerimiento.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 153.3 LCSP', 'Si el contrato es susceptible de recurso especial en materia de contratación conforme al artículo 44, la formalización no podrá efectuarse antes de que transcurran quince días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos.', null, '131aaa567668118b2fa49de032ac6b26b808ab5f4aa8b67ecaa5ca4beb386910', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '131aaa567668118b2fa49de032ac6b26b808ab5f4aa8b67ecaa5ca4beb386910')
