  select 'Según el artículo 153 de la Ley 9/2017, cuando por causas imputables al adjudicatario no se hubiese formalizado el contrato dentro del plazo indicado, se le exigirá en concepto de penalidad:', 'El art. 153.4 LCSP fija una penalidad del 3 % del presupuesto base de licitación, IVA excluido, que se hace efectiva en primer lugar contra la garantía definitiva; el contrato se adjudica al siguiente licitador por orden de clasificación.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 153.4 LCSP', 'Cuando por causas imputables al adjudicatario no se hubiese formalizado el contrato dentro del plazo indicado se le exigirá el importe del 3 por ciento del presupuesto base de licitación, IVA excluido, en concepto de penalidad', null, '9ea605300c63fda421db7fc313ec7ae6a080b9cf1bdd0d998c736ac9465a2cf7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9ea605300c63fda421db7fc313ec7ae6a080b9cf1bdd0d998c736ac9465a2cf7')
