with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 190 de la Ley 9/2017, ¿cuál de las siguientes es una prerrogativa del órgano de contratación en los contratos administrativos?', 'El art. 190 LCSP enumera las prerrogativas de interpretar, resolver dudas, modificar por razones de interés público, declarar la responsabilidad del contratista, suspender la ejecución, acordar la resolución y determinar sus efectos; las facultades de inspección no implican un derecho general a inspeccionar las instalaciones del contratista.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 190 LCSP', 'el órgano de contratación ostenta la prerrogativa de interpretar los contratos administrativos, resolver las dudas que ofrezca su cumplimiento, modificarlos por razones de interés público, declarar la responsabilidad imputable al contratista a raíz de la ejecución del contrato, suspender la ejecución del mismo, acordar su resolución y determinar los efectos de esta.', null, '52ecda4e5a750608f5e6d2ed28d791e113c96bba3b165fc2cfda5c5403c20349', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '52ecda4e5a750608f5e6d2ed28d791e113c96bba3b165fc2cfda5c5403c20349')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Modificarlos por razones de interés público.', true), ('B', 'Ceder el contrato a un tercero sin consentimiento del contratista.', false), ('C', 'Prorrogarlos por consentimiento tácito.', false), ('D', 'Inspeccionar con carácter general cualquier instalación del contratista, en todo caso.', false)) as v(label, body, ok)
)
