with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 193 de la Ley 9/2017, cuando el contratista, por causas imputables al mismo, incurra en demora respecto al plazo total, la Administración podrá optar por la resolución del contrato o por la imposición de penalidades diarias que, salvo que el pliego establezca otras de forma justificada, serán de:', 'El art. 193.3 LCSP fija penalidades diarias de 0,60 euros por cada 1.000 euros del precio, IVA excluido; el pliego puede prever otras distintas si se justifica en el expediente. La constitución en mora no precisa intimación previa (art. 193.2).', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 193.3 LCSP', 'la Administración podrá optar, atendidas las circunstancias del caso, por la resolución del contrato o por la imposición de las penalidades diarias en la proporción de 0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido.', null, 'cdf99ec2db50a1051f851466c1486ab18c3fec76ead31e9960bf6cd80578e988', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cdf99ec2db50a1051f851466c1486ab18c3fec76ead31e9960bf6cd80578e988')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '0,60 euros por cada 100 euros del precio del contrato, IVA incluido.', false), ('B', '0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido.', true), ('C', '1 euro por cada 1.000 euros del precio del contrato, IVA excluido.', false), ('D', 'El 1 por ciento del precio del contrato por cada día de retraso.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un contrato de suministro, las penalidades por demora impuestas al contratista alcanzan el 5 por 100 del precio del contrato, IVA excluido. Según el artículo 193 de la Ley 9/2017, el órgano de contratación:', 'El art. 193.4 LCSP faculta al órgano de contratación, cada vez que las penalidades alcancen un múltiplo del 5 % del precio, para resolver o continuar con nuevas penalidades.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 193.4 LCSP', 'Cada vez que las penalidades por demora alcancen un múltiplo del 5 por 100 del precio del contrato, IVA excluido, el órgano de contratación estará facultado para proceder a la resolución del mismo o acordar la continuidad de su ejecución con imposición de nuevas penalidades.', null, '09269f0874f0c12788d590fdd581066d171b03813c993f9b28206363236a9c54', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '09269f0874f0c12788d590fdd581066d171b03813c993f9b28206363236a9c54')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Debe resolver obligatoriamente el contrato.', false), ('B', 'No puede imponer más penalidades y debe esperar a la finalización del plazo.', false), ('C', 'Está facultado para resolver el contrato o acordar la continuidad de su ejecución con imposición de nuevas penalidades.', true), ('D', 'Debe solicitar autorización al Consejo de Ministros para continuar la ejecución.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 203 de la Ley 9/2017, los contratos administrativos solo podrán modificarse durante su vigencia:', 'El art. 203.2 LCSP limita la modificación a los casos previstos en el pliego (art. 204) o, excepcionalmente, a los no previstos que cumplan el art. 205; en otro caso procede resolver el contrato y celebrar otro.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 203.2 LCSP', 'a) Cuando así se haya previsto en el pliego de cláusulas administrativas particulares, en los términos y condiciones establecidos en el artículo 204; b) Excepcionalmente, cuando sea necesario realizar una modificación que no esté prevista en el pliego de cláusulas administrativas particulares, siempre y cuando se cumplan las condiciones que establece el artículo 205.', null, '7c77eb067b1b0b94421129abe7d09bbec8e15c712d13eeab63d044756da1c9ae', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7c77eb067b1b0b94421129abe7d09bbec8e15c712d13eeab63d044756da1c9ae')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuando lo acuerden libremente las partes por mutuo acuerdo, sin más requisitos.', false), ('B', 'Únicamente cuando lo autorice el Consejo de Estado.', false), ('C', 'Cuando así se haya previsto en el pliego de cláusulas administrativas particulares o, excepcionalmente, cuando se cumplan las condiciones de las modificaciones no previstas del artículo 205.', true), ('D', 'Solo en los contratos de obras y siempre que no se supere el 10 por ciento del precio.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 205 de la Ley 9/2017, una modificación no prevista en el pliego para añadir servicios adicionales solo es posible, entre otros requisitos, si la alteración de la cuantía no excede, aislada o conjuntamente con otras modificaciones acordadas conforme a ese artículo, del:', 'El art. 205.2.a).2.º LCSP fija el tope del 50 % del precio inicial, IVA excluido, para las prestaciones adicionales (el mismo límite rige para las circunstancias imprevisibles de la letra b).', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 205.2.a) LCSP', '2.º Que la modificación del contrato implique una alteración en su cuantía que no exceda, aislada o conjuntamente con otras modificaciones acordadas conforme a este artículo, del 50 por ciento de su precio inicial, IVA excluido.', null, 'ad76ee69c05d963a82bfa5c0a49c1e7491875fead090fba20bd9231545270451', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ad76ee69c05d963a82bfa5c0a49c1e7491875fead090fba20bd9231545270451')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
