)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 210 de la Ley 9/2017, la constatación del cumplimiento del contrato exigirá por parte de la Administración un acto formal y positivo de recepción o conformidad:', 'El art. 210.2 LCSP exige el acto formal de recepción o conformidad en el mes siguiente a la entrega o realización, salvo otro plazo del pliego; a partir de esa fecha corre el plazo de garantía (art. 210.3).', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 210.2 LCSP', 'En todo caso, su constatación exigirá por parte de la Administración un acto formal y positivo de recepción o conformidad dentro del mes siguiente a la entrega o realización del objeto del contrato, o en el plazo que se determine en el pliego de cláusulas administrativas particulares por razón de sus características.', null, '13cfd860d2307228fd495b83d0f8fafe71b1fb08c4b198d82f499c1c032419c5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '13cfd860d2307228fd495b83d0f8fafe71b1fb08c4b198d82f499c1c032419c5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dentro de los diez días siguientes a la entrega, sin excepción.', false), ('B', 'Dentro de los tres meses siguientes a la finalización del plazo de garantía.', false), ('C', 'En el momento de la formalización del contrato.', false), ('D', 'Dentro del mes siguiente a la entrega o realización del objeto del contrato, o en el plazo que determine el pliego por razón de sus características.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Administración resuelve un contrato de servicios por incumplimiento culpable del contratista de su obligación principal. Según el artículo 213 de la Ley 9/2017, ¿qué efecto tiene la resolución?', 'El art. 213.3 LCSP prevé la incautación de la garantía y la indemnización de los daños que excedan de ella; la indemnización del 3 % corresponde a la resolución por la causa del art. 211.g) y el régimen de lo estipulado, al mutuo acuerdo.', 'age_adm_34_contratos', (select id from public.topics where slug = 'age-adm-34-contratos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 213.3 LCSP', 'Cuando el contrato se resuelva por incumplimiento culpable del contratista le será incautada la garantía y deberá, además, indemnizar a la Administración los daños y perjuicios ocasionados en lo que excedan del importe de la garantía incautada.', null, '2d574be04ff1dc7b1e7be3303286a2bbcd4d4c4f8fdf1b06d06e900ad8005692', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2d574be04ff1dc7b1e7be3303286a2bbcd4d4c4f8fdf1b06d06e900ad8005692')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se incautará la garantía y el contratista deberá indemnizar los daños y perjuicios en lo que excedan de su importe.', true), ('B', 'El contratista tendrá derecho a una indemnización del 3 por ciento de la prestación dejada de realizar.', false), ('C', 'Los derechos de las partes se acomodarán a lo que estas hayan estipulado válidamente.', false), ('D', 'Se devolverá la garantía al contratista, sin más consecuencias.', false)) as v(label, body, ok)
)
