with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 84 de la Ley 7/1985, reguladora de las Bases del Régimen Local, ¿cuál de los siguientes es un medio a través del cual las Entidades locales pueden intervenir la actividad de los ciudadanos?', 'El art. 84.1 LBRL enumera ordenanzas y bandos, licencia y otros controles preventivos, comunicación previa o declaración responsable, control posterior al inicio de la actividad y órdenes individuales; las demás opciones son técnicas de fomento o formas de gestión de servicios.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392'), 'Art. 84.1 LBRL', 'd) Sometimiento a control posterior al inicio de la actividad, a efectos de verificar el cumplimiento de la normativa reguladora de la misma.', null, '7e20f77038d92621a46909fa8d90a94beff2cc0056abe58409ffb157b0974399', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7e20f77038d92621a46909fa8d90a94beff2cc0056abe58409ffb157b0974399')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El sometimiento a control posterior al inicio de la actividad.', true), ('B', 'La concesión de subvenciones en régimen de concurrencia competitiva.', false), ('C', 'La gestión indirecta mediante concesión de servicios.', false), ('D', 'La creación de una sociedad mercantil local.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 85 de la Ley 7/1985, ¿cuál de las siguientes es una forma de gestión directa de los servicios públicos de competencia local?', 'El art. 85.2.A) LBRL prevé como gestión directa la gestión por la propia Entidad Local, el organismo autónomo local, la entidad pública empresarial local y la sociedad mercantil local de capital íntegramente público; la concesión es gestión indirecta.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392'), 'Art. 85.2 LBRL', 'A) Gestión directa: a) Gestión por la propia Entidad Local. b) Organismo autónomo local. c) Entidad pública empresarial local. d) Sociedad mercantil local, cuyo capital social sea de titularidad pública.', null, '6a3501f59416c19f497ce81122e41b127c5b4ccf9ba373158839802fb265ae04', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6a3501f59416c19f497ce81122e41b127c5b4ccf9ba373158839802fb265ae04')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El organismo autónomo local.', true), ('B', 'La concesión de servicios.', false), ('C', 'La sociedad mercantil de capital mayoritariamente privado.', false), ('D', 'La fundación privada sin participación de la entidad local.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
