  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 86 de la Ley 7/1985, ¿cuál de las siguientes actividades o servicios esenciales está reservada en favor de las Entidades Locales?', 'El art. 86.2 LBRL reserva a las Entidades Locales el abastecimiento domiciliario y depuración de aguas, la recogida, tratamiento y aprovechamiento de residuos y el transporte público de viajeros; el Estado y las CCAA pueden establecer por ley idéntica reserva para otras actividades.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392'), 'Art. 86.2 LBRL', 'Se declara la reserva en favor de las Entidades Locales de las siguientes actividades o servicios esenciales: abastecimiento domiciliario y depuración de aguas; recogida, tratamiento y aprovechamiento de residuos, y transporte público de viajeros', null, 'bed14e9d100b9ea8c76108a4784b89b2950607774a1612820480c4443d02d773', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bed14e9d100b9ea8c76108a4784b89b2950607774a1612820480c4443d02d773')
  returning id
), o as (
