with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 284 de la Ley 9/2017, de Contratos del Sector Público, ¿qué servicios no podrán prestarse en ningún caso mediante concesión de servicios?', 'El art. 284.1 LCSP permite la gestión indirecta mediante concesión de los servicios susceptibles de explotación económica por particulares, pero nunca de los que impliquen ejercicio de autoridad.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 284.1 LCSP', 'En ningún caso podrán prestarse mediante concesión de servicios los que impliquen ejercicio de la autoridad inherente a los poderes públicos.', null, '6e8ee1ad3ff9b2bcd4b77db6c28a7732333d98c82678e6c175a7eb20907a5c8d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6e8ee1ad3ff9b2bcd4b77db6c28a7732333d98c82678e6c175a7eb20907a5c8d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los que sean susceptibles de explotación económica por particulares.', false), ('B', 'Los de titularidad local.', false), ('C', 'Los que exijan la ejecución de obras.', false), ('D', 'Los que impliquen ejercicio de la autoridad inherente a los poderes públicos.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 284 de la Ley 9/2017, antes de proceder a la contratación de una concesión de servicios, en los casos en que se trate de servicios públicos:', 'El art. 284.2 LCSP exige establecer previamente el régimen jurídico del servicio público, que declare su asunción por la Administración, determine el alcance de las prestaciones y regule sus aspectos jurídicos, económicos y administrativos.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 284.2 LCSP', 'Antes de proceder a la contratación de una concesión de servicios, en los casos en que se trate de servicios públicos, deberá haberse establecido su régimen jurídico, que declare expresamente que la actividad de que se trata queda asumida por la Administración respectiva como propia de la misma', null, 'b993df0b63ff410724a9ba0f335e1c889cf381a5f5f27180bb72354bd31d21a1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b993df0b63ff410724a9ba0f335e1c889cf381a5f5f27180bb72354bd31d21a1')
  returning id
), o as (
