with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 de la Ley 38/2003, General de Subvenciones, uno de los requisitos para que una disposición dineraria tenga la consideración de subvención es que:', 'El art. 2.1 LGS exige entrega sin contraprestación directa, afectación al cumplimiento de un objetivo, proyecto, actividad o comportamiento, y finalidad de fomento de una actividad de utilidad pública o interés social o de promoción de una finalidad pública; el beneficiario puede ser público o privado.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 2.1 LGS', 'a) Que la entrega se realice sin contraprestación directa de los beneficiarios.', null, 'fb6f1d79928ab0775b5f8c3ac0c061e6099848e7b2e3cd5ea0b9a1ebfbaf5d96', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fb6f1d79928ab0775b5f8c3ac0c061e6099848e7b2e3cd5ea0b9a1ebfbaf5d96')
