insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 8 de la Ley 38/2003, los órganos que propongan el establecimiento de subvenciones deberán, con carácter previo, concretar los objetivos y efectos que se pretenden, el plazo, los costes previsibles y sus fuentes de financiación en:', 'El art. 8.1 LGS exige el plan estratégico de subvenciones, supeditado al cumplimiento de los objetivos de estabilidad presupuestaria; las bases reguladoras deben hacer referencia a dicho plan.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 8.1 LGS', 'deberán concretar en un plan estratégico de subvenciones los objetivos y efectos que se pretenden con su aplicación, el plazo necesario para su consecución, los costes previsibles y sus fuentes de financiación, supeditándose en todo caso al cumplimiento de los objetivos de estabilidad presupuestaria.', null, '37221a56cc5dc033d169fb8ec6594d290dabee2c11cfdc543b4230c106206e19', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '37221a56cc5dc033d169fb8ec6594d290dabee2c11cfdc543b4230c106206e19')
  returning id
