)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una fundación figura con su dotación y como beneficiaria en los estados de gasto de los Presupuestos Generales del Estado. Según el artículo 22 de la Ley 38/2003, esa subvención:', 'El art. 22 LGS establece la concurrencia competitiva como procedimiento ordinario, pero permite la concesión directa de las subvenciones nominativas (dotación y beneficiario determinados en los estados de gasto), de las impuestas por norma de rango legal y, excepcionalmente, de las justificadas por razones de interés público, social, económico o humanitario.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 22 LGS', 'El procedimiento ordinario de concesión de subvenciones se tramitará en régimen de concurrencia competitiva. […] 2. Podrán concederse de forma directa las siguientes subvenciones: a) Las previstas nominativamente en los Presupuestos Generales del Estado, de las Comunidades Autónomas o de las Entidades Locales, en los términos recogidos en los convenios y en la normativa reguladora de estas subvenciones. A efectos de lo establecido en el párrafo anterior, se entiende por subvención prevista nominativamente en los Presupuestos Generales del Estado aquella en que al menos su dotación presupuestaria y beneficiario aparezcan determinados en los estados de gasto del Presupuesto.', null, '4a74569e96fc83f9af24f9cf0cebe9c302df3606615b92e8cd7758e59df737e2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4a74569e96fc83f9af24f9cf0cebe9c302df3606615b92e8cd7758e59df737e2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Debe tramitarse obligatoriamente en régimen de concurrencia competitiva.', false), ('B', 'Solo puede concederse si una ley distinta de la de Presupuestos impone su otorgamiento.', false), ('C', 'Debe concederse mediante prorrateo entre todas las fundaciones solicitantes.', false), ('D', 'Podrá concederse de forma directa, al estar prevista nominativamente en los Presupuestos.', true)) as v(label, body, ok)
)
