with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una ciudadana presenta ante la Administración competente la declaración responsable exigida para iniciar una actividad. Según el artículo 69 de la Ley 39/2015, ¿desde cuándo puede iniciarla?', 'El art. 69.3 LPAC permite el reconocimiento o ejercicio del derecho o el inicio de la actividad desde el día de presentación de la declaración responsable o comunicación, sin perjuicio del control posterior.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 69.3 LPAC', 'Las declaraciones responsables y las comunicaciones permitirán, el reconocimiento o ejercicio de un derecho o bien el inicio de una actividad, desde el día de su presentación, sin perjuicio de las facultades de comprobación, control e inspección que tengan atribuidas las Administraciones Públicas.', null, '58faf147dec7393d2620047ab65f523fefabab79f347dfc09daf6b334da4f522', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '58faf147dec7393d2620047ab65f523fefabab79f347dfc09daf6b334da4f522')
  returning id
