with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 69 de la Ley 39/2015, para iniciar una misma actividad u obtener el reconocimiento de un mismo derecho o facultad para su ejercicio:', 'El art. 69.6 LPAC prohíbe exigir acumulativamente declaración responsable y comunicación para una misma actividad o derecho.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 69.6 LPAC', 'Únicamente será exigible, bien una declaración responsable, bien una comunicación para iniciar una misma actividad u obtener el reconocimiento de un mismo derecho o facultad para su ejercicio, sin que sea posible la exigencia de ambas acumulativamente.', null, '5126daa3d7f8bf490875d846deed00abb6133accbec1dde839e80c6ecfa56cfd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5126daa3d7f8bf490875d846deed00abb6133accbec1dde839e80c6ecfa56cfd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
