with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 69.4 de la Ley 39/2015, la inexactitud, falsedad u omisión de carácter esencial de cualquier dato incorporado a una declaración responsable determinará:', 'El art. 69.4 LPAC impide continuar la actividad desde que se tenga constancia de esos hechos, sin perjuicio de las responsabilidades penales, civiles o administrativas; la resolución podrá además obligar a restituir la situación jurídica previa.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 69.4 LPAC', 'La inexactitud, falsedad u omisión, de carácter esencial, de cualquier dato o información que se incorpore a una declaración responsable o a una comunicación, o la no presentación ante la Administración competente de la declaración responsable, la documentación que sea en su caso requerida para acreditar el cumplimiento de lo declarado, o la comunicación, determinará la imposibilidad de continuar con el ejercicio del derecho o actividad afectada desde el momento en que se tenga constancia de tales hechos', null, '8e2596801a38bf45462e5847bc7265eb8bc170c224b57c2bbb224749cadca2d8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8e2596801a38bf45462e5847bc7265eb8bc170c224b57c2bbb224749cadca2d8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La nulidad de pleno derecho de todas las actuaciones desde la presentación, sin más efectos.', false), ('B', 'La imposibilidad de continuar con el ejercicio del derecho o actividad afectada desde el momento en que se tenga constancia de tales hechos.', true), ('C', 'La obligación de presentar una nueva declaración en el plazo de diez días, sin interrumpir la actividad.', false), ('D', 'Únicamente la imposición de una multa coercitiva.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
