with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Se ordena al propietario de un solar retirar unos escombros y este no lo hace en el plazo concedido. La Administración, previo apercibimiento, decide retirarlos por medio de una empresa y a costa del propietario. Según la Ley 39/2015, ¿qué medio de ejecución forzosa está utilizando?', 'El art. 102 LPAC prevé la ejecución subsidiaria para actos no personalísimos que puede realizar un sujeto distinto del obligado: la Administración los realiza por sí o a través de las personas que determine, a costa del obligado.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 102 LPAC', 'Habrá lugar a la ejecución subsidiaria cuando se trate de actos que por no ser personalísimos puedan ser realizados por sujeto distinto del obligado. 2. En este caso, las Administraciones Públicas realizarán el acto, por sí o a través de las personas que determinen, a costa del obligado.', null, 'a465794c5786d0530b7c8d722d6879f16bd34be8a3a5d4b31bbbc00adb6d06d7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a465794c5786d0530b7c8d722d6879f16bd34be8a3a5d4b31bbbc00adb6d06d7')
  returning id
