with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 112.2 de la Ley 39/2015, las leyes podrán sustituir el recurso de alzada, en supuestos o ámbitos sectoriales determinados, por procedimientos de impugnación, reclamación, conciliación, mediación y arbitraje:', 'El art. 112.2 LPAC permite esa sustitución cuando la especificidad de la materia lo justifique, ante órganos colegiados o comisiones no sometidos a instrucciones jerárquicas y respetando los principios, garantías y plazos de la Ley.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 112.2 LPAC', 'Las leyes podrán sustituir el recurso de alzada, en supuestos o ámbitos sectoriales determinados, y cuando la especificidad de la materia así lo justifique, por otros procedimientos de impugnación, reclamación, conciliación, mediación y arbitraje, ante órganos colegiados o Comisiones específicas no sometidas a instrucciones jerárquicas', null, '08ac99aeee4580f5dd772c483e967e3630503f30b4b0cb594eeeaea440b1c879', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '08ac99aeee4580f5dd772c483e967e3630503f30b4b0cb594eeeaea440b1c879')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ante el superior jerárquico del órgano que dictó el acto.', false), ('B', 'Ante órganos colegiados o Comisiones específicas no sometidas a instrucciones jerárquicas.', true), ('C', 'Ante los Juzgados de lo Contencioso-administrativo.', false), ('D', 'Ante árbitros designados libremente por el órgano que dictó el acto.', false)) as v(label, body, ok)
)
