with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 86 de la Ley 39/2015, sobre la terminación convencional del procedimiento, los acuerdos que versen sobre materias de la competencia directa del Consejo de Ministros:', 'El art. 86.3 LPAC exige la aprobación expresa del Consejo de Ministros (u órgano equivalente de las CCAA) para los acuerdos sobre materias de su competencia directa.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 86.3 LPAC', 'Requerirán en todo caso la aprobación expresa del Consejo de Ministros u órgano equivalente de las Comunidades Autónomas, los acuerdos que versen sobre materias de la competencia directa de dicho órgano.', null, '200d929aad63917f261a6d4ba84603ee2370175f2119afd9e823e9ad537cb67f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '200d929aad63917f261a6d4ba84603ee2370175f2119afd9e823e9ad537cb67f')
  returning id
), o as (
