with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 4 de la Ley 40/2015, las Administraciones Públicas que establezcan medidas que limiten el ejercicio de derechos o exijan requisitos para el desarrollo de una actividad deberán:', 'El art. 4.1 LRJSP exige aplicar la proporcionalidad, elegir la medida menos restrictiva, motivar su necesidad, justificar su adecuación sin diferencias de trato discriminatorias y evaluar periódicamente sus efectos.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 4.1 LRJSP', 'deberán aplicar el principio de proporcionalidad y elegir la medida menos restrictiva, motivar su necesidad para la protección del interés público así como justificar su adecuación para lograr los fines que se persiguen, sin que en ningún caso se produzcan diferencias de trato discriminatorias.', null, '490f5d96d23d28c85f15f0103f19948c969877210b467cff75f119004a18840e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '490f5d96d23d28c85f15f0103f19948c969877210b467cff75f119004a18840e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Elegir la medida más eficaz, aunque sea la más restrictiva.', false), ('B', 'Someter la medida a autorización judicial previa.', false), ('C', 'Aplicar el principio de proporcionalidad y elegir la medida menos restrictiva.', true), ('D', 'Aprobar la medida necesariamente mediante norma con rango de ley.', false)) as v(label, body, ok)
)
