with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 25 de la Ley 40/2015, la potestad sancionadora de las Administraciones Públicas se ejercerá cuando haya sido expresamente reconocida por:', 'El art. 25.1 LRJSP consagra el principio de legalidad: la potestad sancionadora debe estar reconocida por norma con rango de ley; su ejercicio corresponde a los órganos a los que se atribuya por disposición legal o reglamentaria (art. 25.2).', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 25.1 LRJSP', 'La potestad sancionadora de las Administraciones Públicas se ejercerá cuando haya sido expresamente reconocida por una norma con rango de Ley', null, 'a9805b8779a7eddbf750a4a5feba2f5830a369d6bd6025b77a12788d282f7d77', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a9805b8779a7eddbf750a4a5feba2f5830a369d6bd6025b77a12788d282f7d77')
  returning id
