with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 30 de la Ley 40/2015, si la ley que establece las infracciones no fija plazos de prescripción, las infracciones leves prescribirán:', 'El art. 30.1 LRJSP fija, en defecto de previsión legal, tres años para las muy graves, dos para las graves y seis meses para las leves; las sanciones por faltas leves prescriben al año.', 'age_adm_35_actividad_administrativa', (select id from public.topics where slug = 'age-adm-35-actividad-administrativa'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 30.1 LRJSP', 'Si éstas no fijan plazos de prescripción, las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses', null, '8d4b1cebe52a6b209bf846a3d40517a03cfeba0811c077d94e5dfb1a7bf6a3b7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8d4b1cebe52a6b209bf846a3d40517a03cfeba0811c077d94e5dfb1a7bf6a3b7')
  returning id
), o as (
