with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 106.2 de la Constitución Española, los particulares tendrán derecho a ser indemnizados por toda lesión que sufran en cualquiera de sus bienes y derechos, siempre que la lesión sea consecuencia del funcionamiento de los servicios públicos, salvo en los casos de:', 'El art. 106.2 CE solo excluye la indemnización en los casos de fuerza mayor; la Ley 40/2015 precisa que se indemniza tanto el funcionamiento normal como el anormal (art. 32.1).', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 106.2 CE', 'Los particulares, en los términos establecidos por la ley, tendrán derecho a ser indemnizados por toda lesión que sufran en cualquiera de sus bienes y derechos, salvo en los casos de fuerza mayor, siempre que la lesión sea consecuencia del funcionamiento de los servicios públicos.', null, 'd5b7576fea7e87648476cf4b8e07a1894e7cd3c866fff46fe31c08f01d6109dd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd5b7576fea7e87648476cf4b8e07a1894e7cd3c866fff46fe31c08f01d6109dd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Caso fortuito.', false), ('B', 'Funcionamiento normal de los servicios públicos.', false), ('C', 'Daños inferiores a la cuantía que fije la ley.', false), ('D', 'Fuerza mayor.', true)) as v(label, body, ok)
)
