insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-36-responsabilidad', 'III.6 La responsabilidad patrimonial de las Administraciones públicas') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-36-responsabilidad' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 de la Ley 29/1998, ¿ante qué orden jurisdiccional se sustancian las cuestiones relativas a la responsabilidad patrimonial de las Administraciones públicas, aunque en la producción del daño concurran particulares o la Administración cuente con un seguro de responsabilidad?', 'El art. 2.e) LJCA atribuye al orden contencioso-administrativo la responsabilidad patrimonial de las Administraciones cualquiera que sea la naturaleza de la actividad, sin que puedan ser demandadas por este motivo ante los órdenes civil o social.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 2.e) LJCA', 'e) La responsabilidad patrimonial de las Administraciones públicas, cualquiera que sea la naturaleza de la actividad o el tipo de relación de que derive, no pudiendo ser demandadas aquellas por este motivo ante los órdenes jurisdiccionales civil o social, aun cuando en la producción del daño concurran con particulares o cuenten con un seguro de responsabilidad.', null, '3792bb41d6740566a2de5572935b603034266b106a24c87be9c5e5b206950841', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3792bb41d6740566a2de5572935b603034266b106a24c87be9c5e5b206950841')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El orden contencioso-administrativo.', true), ('B', 'El orden civil.', false), ('C', 'El orden social.', false), ('D', 'El orden civil cuando concurran particulares, y el contencioso-administrativo en los demás casos.', false)) as v(label, body, ok)
)
