-- Lote age-adm-36-responsabilidad-lopj-v1 (1 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-36-responsabilidad', 'III.6 La responsabilidad patrimonial de las Administraciones públicas') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-36-responsabilidad' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 293 de la Ley Orgánica 6/1985, del Poder Judicial, cuando la decisión judicial que reconozca el error no resulte de un recurso de revisión, la acción judicial para el reconocimiento del error deberá instarse inexcusablemente en el plazo de:', 'El art. 293.1 LOPJ exige que la reclamación por error judicial vaya precedida de una decisión judicial que lo reconozca; fuera del recurso de revisión, la acción para su reconocimiento se ejercita en tres meses ante la Sala correspondiente del Tribunal Supremo. Es la responsabilidad del Estado por el funcionamiento de la Administración de Justicia (art. 121 CE; art. 32.7 LRJSP).', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 293.1.a) LOPJ', 'La reclamación de indemnización por causa de error deberá ir precedida de una decisión judicial que expresamente lo reconozca. Esta previa decisión podrá resultar directamente de una sentencia dictada en virtud de recurso de revisión. En cualquier otro caso distinto de éste se aplicaran las reglas siguientes: a) La acción judicial para el reconocimiento del error deberá instarse inexcusablemente en el plazo de tres meses, a partir del día en que pudo ejercitarse.', null, 'eb784f3ee11a1f662d67f6f4d60cbf684e5b8922170977624159f4a6e3492a52', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'eb784f3ee11a1f662d67f6f4d60cbf684e5b8922170977624159f4a6e3492a52')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un año, a partir de la notificación de la resolución errónea.', false), ('B', 'Tres meses, a partir del día en que pudo ejercitarse.', true), ('C', 'Dos meses, a partir de la firmeza de la resolución.', false), ('D', 'Seis meses, a partir del día en que pudo ejercitarse.', false)) as v(label, body, ok)
)
