insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-36-responsabilidad' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una persona sufre lesiones físicas al caer en una zanja mal señalizada de una obra pública. Recibe el alta médica, con determinación de secuelas, ocho meses después. Según el artículo 67 de la Ley 39/2015, ¿cuándo prescribe su derecho a reclamar?', 'El art. 67.1 LPAC fija un plazo de prescripción de un año; en los daños físicos o psíquicos a las personas empieza a computarse desde la curación o la determinación del alcance de las secuelas.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 67.1 LPAC', 'El derecho a reclamar prescribirá al año de producido el hecho o el acto que motive la indemnización o se manifieste su efecto lesivo. En caso de daños de carácter físico o psíquico a las personas, el plazo empezará a computarse desde la curación o la determinación del alcance de las secuelas.', null, 'a85fa32843151d7d02c26fbf93b676d0c2b16a89fc3fd9e16f4e413f792f8aea', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a85fa32843151d7d02c26fbf93b676d0c2b16a89fc3fd9e16f4e413f792f8aea')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al año desde la fecha de la caída, en todo caso.', false), ('B', 'A los seis meses desde la curación.', false), ('C', 'A los cuatro años desde la fecha de la caída.', false), ('D', 'Al año desde la curación o la determinación del alcance de las secuelas.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 81 de la Ley 39/2015, en los procedimientos de responsabilidad patrimonial será preceptivo solicitar informe al servicio cuyo funcionamiento haya ocasionado la presunta lesión, que deberá emitirse en un plazo no superior a:', 'El art. 81.1 LPAC exige el informe del servicio causante en un plazo máximo de diez días; el dictamen del Consejo de Estado, cuando es preceptivo, se emite en dos meses (art. 81.2).', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 81.1 LPAC', 'En el caso de los procedimientos de responsabilidad patrimonial será preceptivo solicitar informe al servicio cuyo funcionamiento haya ocasionado la presunta lesión indemnizable, no pudiendo exceder de diez días el plazo de su emisión.', null, '3595f7ce23e4037f6b2b3cfb646f2a77e5357fc0b986bff64211441aeeed86e3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3595f7ce23e4037f6b2b3cfb646f2a77e5357fc0b986bff64211441aeeed86e3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
