insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un particular reclama a un Ministerio una indemnización de 62.000 euros por responsabilidad patrimonial. Según el artículo 81 de la Ley 39/2015, antes de resolver:', 'El art. 81.2 LPAC exige dictamen del Consejo de Estado (u órgano consultivo autonómico) cuando la indemnización reclamada sea igual o superior a 50.000 euros; el dictamen se emite en dos meses y se pronuncia sobre la relación de causalidad, la valoración del daño y la cuantía y modo de la indemnización.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 81.2 LPAC', 'Cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 50.000 euros o a la que se establezca en la correspondiente legislación autonómica, así como en aquellos casos que disponga la Ley Orgánica 3/1980, de 22 de abril, del Consejo de Estado, será preceptivo solicitar dictamen del Consejo de Estado o, en su caso, del órgano consultivo de la Comunidad Autónoma. […] El dictamen se emitirá en el plazo de dos meses', null, '92e782aaed85ef47b44e630fd232ee24012623db16e6124e1be7022712463ddc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '92e782aaed85ef47b44e630fd232ee24012623db16e6124e1be7022712463ddc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
