with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 91 de la Ley 39/2015, transcurridos seis meses desde que se inició el procedimiento de responsabilidad patrimonial sin que haya recaído y se notifique resolución expresa ni se haya formalizado el acuerdo:', 'El art. 91.3 LPAC prevé el silencio desestimatorio a los seis meses, en coherencia con el art. 24.1 LPAC.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 91.3 LPAC', 'Transcurridos seis meses desde que se inició el procedimiento sin que haya recaído y se notifique resolución expresa o, en su caso, se haya formalizado el acuerdo, podrá entenderse que la resolución es contraria a la indemnización del particular.', null, 'b51cd7c563791a01b4ccdef304d68df46d68289cc1d9651711ac9ebd657853e4', false
