with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 92 de la Ley 39/2015, en el ámbito de la Administración General del Estado los procedimientos de responsabilidad patrimonial se resolverán, con carácter general, por:', 'El art. 92 LPAC atribuye la resolución al Ministro respectivo, y al Consejo de Ministros en los casos del art. 32.3 LRJSP (actos legislativos) o cuando una ley así lo disponga.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 92 LPAC', 'En el ámbito de la Administración General del Estado, los procedimientos de responsabilidad patrimonial se resolverán por el Ministro respectivo o por el Consejo de Ministros en los casos del artículo 32.3 de la Ley de Régimen Jurídico del Sector Público o cuando una ley así lo disponga.', null, '9dfb2b20cc2866bda28837b0ebe1c515d3abd349d58255b6ebe6d630833f85cc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9dfb2b20cc2866bda28837b0ebe1c515d3abd349d58255b6ebe6d630833f85cc')
