insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 96 de la Ley 39/2015, si iniciado un procedimiento de responsabilidad patrimonial el órgano competente considera inequívocas la relación de causalidad, la valoración del daño y la cuantía de la indemnización, podrá acordar de oficio la tramitación simplificada, que, salvo que reste menos para la ordinaria, deberá resolverse en:', 'El art. 96.4 LPAC permite suspender el procedimiento general e iniciar uno simplificado en esos casos, y el art. 96.6 fija el plazo de resolución en treinta días desde el día siguiente a la notificación del acuerdo de tramitación simplificada.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 96.4 y 96.6 LPAC', 'si una vez iniciado el procedimiento administrativo el órgano competente para su tramitación considera inequívoca la relación de causalidad entre el funcionamiento del servicio público y la lesión, así como la valoración del daño y el cálculo de la cuantía de la indemnización, podrá acordar de oficio la suspensión del procedimiento general y la iniciación de un procedimiento simplificado. […] Salvo que reste menos para su tramitación ordinaria, los procedimientos administrativos tramitados de manera simplificada deberán ser resueltos en treinta días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento', null, 'f443b13216f7d563efc3d6209b5e7901b674e48c910cfe26cda464126356dc0a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f443b13216f7d563efc3d6209b5e7901b674e48c910cfe26cda464126356dc0a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Diez días desde la presentación de la reclamación.', false), ('B', 'Tres meses desde la iniciación del procedimiento.', false), ('C', 'Treinta días desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada.', true), ('D', 'Quince días desde la emisión del informe del servicio.', false)) as v(label, body, ok)
)
