insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-36-responsabilidad' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 32 de la Ley 40/2015, los particulares tendrán derecho a ser indemnizados por las Administraciones Públicas de toda lesión que sufran en sus bienes y derechos siempre que sea consecuencia del:', 'El art. 32.1 LRJSP configura una responsabilidad objetiva: se indemniza la lesión derivada del funcionamiento normal o anormal, salvo fuerza mayor o daños que el particular tenga el deber jurídico de soportar.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 32.1 LRJSP', 'Los particulares tendrán derecho a ser indemnizados por las Administraciones Públicas correspondientes, de toda lesión que sufran en cualquiera de sus bienes y derechos, siempre que la lesión sea consecuencia del funcionamiento normal o anormal de los servicios públicos salvo en los casos de fuerza mayor o de daños que el particular tenga el deber jurídico de soportar de acuerdo con la Ley.', null, '9c71bc12ce433404bf02ef35258beb1a38f55e47bb8ba11b982d4e1edce42490', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9c71bc12ce433404bf02ef35258beb1a38f55e47bb8ba11b982d4e1edce42490')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Funcionamiento normal o anormal de los servicios públicos.', true), ('B', 'Funcionamiento anormal de los servicios públicos, únicamente.', false), ('C', 'Funcionamiento de los servicios públicos, solo cuando medie culpa o negligencia del personal.', false), ('D', 'Funcionamiento de los servicios públicos, solo si el acto causante ha sido anulado judicialmente.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 32.1 de la Ley 40/2015, la anulación en vía administrativa o por el orden jurisdiccional contencioso-administrativo de los actos o disposiciones administrativas:', 'El art. 32.1, párrafo segundo, LRJSP dispone que la anulación no presupone por sí misma el derecho a indemnización: habrá que acreditar los requisitos generales de la responsabilidad.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 32.1 LRJSP', 'La anulación en vía administrativa o por el orden jurisdiccional contencioso administrativo de los actos o disposiciones administrativas no presupone, por sí misma, derecho a la indemnización.', null, '846e7f8ce3eafdaa0399ef128c7772a603cf6fee0b178cd1e65b1736822925cc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '846e7f8ce3eafdaa0399ef128c7772a603cf6fee0b178cd1e65b1736822925cc')
  returning id
