insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 32.2 de la Ley 40/2015, el daño alegado en una reclamación de responsabilidad patrimonial habrá de ser, en todo caso:', 'El art. 32.2 LRJSP exige un daño efectivo, evaluable económicamente e individualizado; no establece cuantía mínima ni exige funcionamiento anormal.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 32.2 LRJSP', 'En todo caso, el daño alegado habrá de ser efectivo, evaluable económicamente e individualizado con relación a una persona o grupo de personas.', null, '2d76fcb5333613db5c67cd6ec87887487bd03b770b0046872a8e487f2f1ece01', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2d76fcb5333613db5c67cd6ec87887487bd03b770b0046872a8e487f2f1ece01')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Efectivo, evaluable económicamente y de cuantía superior a 6.000 euros.', false), ('B', 'Probable, evaluable económicamente y referido a la generalidad de los ciudadanos.', false), ('C', 'Efectivo, evaluable económicamente e individualizado con relación a una persona o grupo de personas.', true), ('D', 'Efectivo y causado necesariamente por el funcionamiento anormal del servicio.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 32.4 de la Ley 40/2015, si la lesión es consecuencia de la aplicación de una norma con rango de ley declarada inconstitucional, procederá su indemnización cuando el particular:', 'El art. 32.4 LRJSP exige sentencia firme desestimatoria de un recurso contra la actuación dañosa en el que se hubiera alegado la inconstitucionalidad después declarada. El derecho a reclamar prescribe al año de la publicación de la sentencia del TC en el BOE (art. 67.1 LPAC).', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 32.4 LRJSP', 'Si la lesión es consecuencia de la aplicación de una norma con rango de ley declarada inconstitucional, procederá su indemnización cuando el particular haya obtenido, en cualquier instancia, sentencia firme desestimatoria de un recurso contra la actuación administrativa que ocasionó el daño, siempre que se hubiera alegado la inconstitucionalidad posteriormente declarada.', null, '9d7432f8e1bfc17a0c88f13bfe915a4df8b23698a6a3e12b40aa50475112e7fa', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9d7432f8e1bfc17a0c88f13bfe915a4df8b23698a6a3e12b40aa50475112e7fa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Haya interpuesto recurso de amparo ante el Tribunal Constitucional en el plazo de tres meses.', false), ('B', 'Lo solicite dentro de los cinco años siguientes a la entrada en vigor de la ley, sin necesidad de recurso previo.', false), ('C', 'Haya obtenido, en cualquier instancia, sentencia firme desestimatoria de un recurso contra la actuación administrativa que ocasionó el daño, siempre que hubiera alegado la inconstitucionalidad posteriormente declarada.', true), ('D', 'Haya obtenido sentencia firme estimatoria del recurso contra la actuación que ocasionó el daño.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 33 de la Ley 40/2015, cuando de la gestión dimanante de fórmulas conjuntas de actuación entre varias Administraciones públicas se derive responsabilidad, las Administraciones intervinientes responderán frente al particular:', 'El art. 33.1 LRJSP impone la responsabilidad solidaria frente al particular, sin perjuicio de que el instrumento regulador de la actuación conjunta distribuya la responsabilidad entre ellas.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 33.1 LRJSP', 'Cuando de la gestión dimanante de fórmulas conjuntas de actuación entre varias Administraciones públicas se derive responsabilidad en los términos previstos en la presente Ley, las Administraciones intervinientes responderán frente al particular, en todo caso, de forma solidaria.', null, 'b8eeb49e3041e41882fd43b0c8ff3fbd5e69280f151a8c628c245980c9dd22e5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b8eeb49e3041e41882fd43b0c8ff3fbd5e69280f151a8c628c245980c9dd22e5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En todo caso, de forma solidaria.', true), ('B', 'De forma mancomunada, en proporción a su participación.', false), ('C', 'Solo la Administración que hubiera dictado el acto causante del daño.', false), ('D', 'De forma subsidiaria, primero la Administración local y después la estatal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un consorcio formado por el Estado, una Comunidad Autónoma y un Ayuntamiento causa un daño a un particular. Los estatutos del consorcio no indican qué Administración debe tramitar las reclamaciones de responsabilidad. Según el artículo 33 de la Ley 40/2015, ¿a quién corresponde incoar, instruir y resolver el procedimiento?', 'El art. 33.3 LRJSP atribuye la competencia a la que fijen los estatutos o reglas de la organización colegiada y, en su defecto, a la Administración con mayor participación en la financiación del servicio, que debe consultar a las demás para que en quince días expongan lo procedente (art. 33.4).', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 33.3 LRJSP', 'la Administración competente para incoar, instruir y resolver los procedimientos en los que exista una responsabilidad concurrente de varias Administraciones Públicas, será la fijada en los Estatutos o reglas de la organización colegiada. En su defecto, la competencia vendrá atribuida a la Administración Pública con mayor participación en la financiación del servicio.', null, '5acddfcc1a46a1310378ec1e066bd40520398169e4eaed62623475b6f8860866', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5acddfcc1a46a1310378ec1e066bd40520398169e4eaed62623475b6f8860866')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A la Administración General del Estado, en todo caso.', false), ('B', 'A la Administración en cuyo territorio se haya producido el daño.', false), ('C', 'A la Administración que elija libremente el particular reclamante.', false), ('D', 'A la Administración Pública con mayor participación en la financiación del servicio.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 34 de la Ley 40/2015, no serán indemnizables los daños que se deriven de hechos o circunstancias:', 'El art. 34.1 LRJSP excluye los llamados riesgos del desarrollo, sin perjuicio de las prestaciones asistenciales o económicas que las leyes puedan establecer.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 34.1 LRJSP', 'No serán indemnizables los daños que se deriven de hechos o circunstancias que no se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de producción de aquéllos, todo ello sin perjuicio de las prestaciones asistenciales o económicas que las leyes puedan establecer para estos casos.', null, '2326dc6f15e194e5c40ee29b43b98418b0313c4469627800109964fd4e63f72f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2326dc6f15e194e5c40ee29b43b98418b0313c4469627800109964fd4e63f72f')
  returning id
), o as (
