  select 'De acuerdo con el artículo 34.4 de la Ley 40/2015, la indemnización procedente podrá sustituirse por una compensación en especie o ser abonada mediante pagos periódicos:', 'El art. 34.4 LRJSP admite la compensación en especie o los pagos periódicos si es más adecuado para la reparación, conviene al interés público y hay acuerdo con el interesado.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 34.4 LRJSP', 'La indemnización procedente podrá sustituirse por una compensación en especie o ser abonada mediante pagos periódicos, cuando resulte más adecuado para lograr la reparación debida y convenga al interés público, siempre que exista acuerdo con el interesado.', null, 'c6c7c41f14175528f3509a561a810cf781284c0fcce88af720a76727b150b738', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c6c7c41f14175528f3509a561a810cf781284c0fcce88af720a76727b150b738')
