with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un conductor de un vehículo oficial causa por negligencia grave un accidente que daña el coche de un particular. Según el artículo 36 de la Ley 40/2015:', 'El art. 36 LRJSP establece la acción directa contra la Administración y la acción de regreso de oficio frente a autoridades y personal cuando hayan actuado con dolo, culpa o negligencia graves.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 36.1-2 LRJSP', 'Para hacer efectiva la responsabilidad patrimonial a que se refiere esta Ley, los particulares exigirán directamente a la Administración Pública correspondiente las indemnizaciones por los daños y perjuicios causados por las autoridades y personal a su servicio. 2. La Administración correspondiente, cuando hubiere indemnizado a los lesionados, exigirá de oficio en vía administrativa de sus autoridades y demás personal a su servicio la responsabilidad en que hubieran incurrido por dolo, o culpa o negligencia graves, previa instrucción del correspondiente procedimiento.', null, 'c71b64eb5b1767464743d0c059eaf6030bbc19f6126f5b5b32a25731fdc40b05', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c71b64eb5b1767464743d0c059eaf6030bbc19f6126f5b5b32a25731fdc40b05')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
