  select 'Según el artículo 37 de la Ley 40/2015, la exigencia de responsabilidad penal del personal al servicio de las Administraciones Públicas:', 'El art. 37.2 LRJSP establece la regla de no suspensión, con la excepción de que la determinación de los hechos en el orden penal sea necesaria para fijar la responsabilidad patrimonial.', 'age_adm_36_responsabilidad', (select id from public.topics where slug = 'age-adm-36-responsabilidad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 37.2 LRJSP', 'La exigencia de responsabilidad penal del personal al servicio de las Administraciones Públicas no suspenderá los procedimientos de reconocimiento de responsabilidad patrimonial que se instruyan, salvo que la determinación de los hechos en el orden jurisdiccional penal sea necesaria para la fijación de la responsabilidad patrimonial.', null, '7e4ee44b95286bd1cb968a449f12ebac97d08293b0b8c63113e0f6f9928bb375', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7e4ee44b95286bd1cb968a449f12ebac97d08293b0b8c63113e0f6f9928bb375')
