with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una funcionaria de la Administración General del Estado cesa en su puesto y toma posesión de otro obtenido por concurso. Según el artículo 37 del Reglamento General de Ingreso (RD 364/1995), las diligencias de cese y toma de posesión deben comunicarse al Registro Central de Personal:', 'El art. 37 del RD 364/1995 fija un plazo de tres días hábiles desde la formalización del cese y la toma de posesión para comunicarlos al Registro Central de Personal.', 'age_adm_41_personal', (select id from public.topics where slug = 'age-adm-41-personal'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 37 RD 364/1995', 'Las diligencias de cese y toma de posesión de los funcionarios que accedan a un puesto de trabajo deberán ser comunicadas al Registro Central de Personal dentro de los tres días hábiles siguientes a su formalización.', null, '616676776adc6b78c2d694b037c25e3dfbba50fab636f51b9df9100616ed5dc4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '616676776adc6b78c2d694b037c25e3dfbba50fab636f51b9df9100616ed5dc4')
  returning id
