with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 8.1 del texto refundido de la Ley del Estatuto Básico del Empleado Público, son empleados públicos:', 'El art. 8.1 TREBEP define a los empleados públicos por dos notas: funciones retribuidas en las Administraciones Públicas y servicio a los intereses generales. El art. 8.2 incluye también al personal laboral y al eventual.', 'age_adm_41_personal', (select id from public.topics where slug = 'age-adm-41-personal'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 8.1 TREBEP', 'Son empleados públicos quienes desempeñan funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales.', null, '5496a1af26a4c198d8b14928075975f321a2a64f213eed098c3aad65baf7e3a4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5496a1af26a4c198d8b14928075975f321a2a64f213eed098c3aad65baf7e3a4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Únicamente quienes han superado un proceso selectivo por oposición o concurso-oposición.', false), ('B', 'Quienes desempeñan funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales.', true), ('C', 'Quienes prestan servicios en las Administraciones Públicas, con o sin retribución, en virtud de nombramiento o contrato.', false), ('D', 'Exclusivamente los funcionarios de carrera y los funcionarios interinos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 9.1 del TREBEP, los funcionarios de carrera están vinculados a una Administración Pública por una relación:', 'El art. 9.1 TREBEP configura la relación del funcionario de carrera como estatutaria, regulada por el Derecho Administrativo, nacida de un nombramiento legal y de carácter permanente.', 'age_adm_41_personal', (select id from public.topics where slug = 'age-adm-41-personal'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 9.1 TREBEP', 'Son funcionarios de carrera quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente.', null, '0a62403b41e19d629552077ff5de6d11f243732ff5f3ed01d61927e9df369063', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0a62403b41e19d629552077ff5de6d11f243732ff5f3ed01d61927e9df369063')
  returning id
), o as (
