with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 9.2 del TREBEP, el ejercicio de las funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales corresponde:', 'El art. 9.2 TREBEP reserva esas funciones, en todo caso, a los funcionarios públicos, en los términos de la ley de desarrollo de cada Administración.', 'age_adm_41_personal', (select id from public.topics where slug = 'age-adm-41-personal'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 9.2 TREBEP', 'En todo caso, el ejercicio de las funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales del Estado y de las Administraciones Públicas corresponden exclusivamente a los funcionarios públicos, en los términos que en la ley de desarrollo de cada Administración Pública se establezca.', null, 'c9e7bdd111e4b178a2e6ad943fdd62d4323849342beb216dc932346a27473fec', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c9e7bdd111e4b178a2e6ad943fdd62d4323849342beb216dc932346a27473fec')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
