with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 10.1 del TREBEP, cuando un funcionario interino se nombra para la sustitución transitoria de los titulares, su nombramiento durará:', 'El art. 10.1.b) TREBEP no fija un plazo cerrado para la sustitución transitoria de titulares: dura el tiempo estrictamente necesario. Los tres años corresponden a las plazas vacantes y los nueve meses en dieciocho, al exceso o acumulación de tareas.', 'age_adm_41_personal', (select id from public.topics where slug = 'age-adm-41-personal'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 10.1.b) TREBEP', 'b) La sustitución transitoria de los titulares, durante el tiempo estrictamente necesario.', null, 'f1df0e17611442a5ac31ff447604a9960334db64a110bcb8d03b21194d75438c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f1df0e17611442a5ac31ff447604a9960334db64a110bcb8d03b21194d75438c')
  returning id
), o as (
