)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 11.1 del TREBEP, en función de la duración del contrato, el personal laboral podrá ser:', 'El art. 11.1 TREBEP exige contrato de trabajo formalizado por escrito y distingue, por su duración, entre personal laboral fijo, por tiempo indefinido o temporal.', 'age_adm_41_personal', (select id from public.topics where slug = 'age-adm-41-personal'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 11.1 TREBEP', 'Es personal laboral el que en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, presta servicios retribuidos por las Administraciones Públicas. En función de la duración del contrato éste podrá ser fijo, por tiempo indefinido o temporal.', null, '478fad2046f77b63824e7fd011f9da5bae8f02d2562de0afaa2149c4d4407712', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '478fad2046f77b63824e7fd011f9da5bae8f02d2562de0afaa2149c4d4407712')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fijo, por tiempo indefinido o temporal.', true), ('B', 'Fijo o interino.', false), ('C', 'De carrera, interino o eventual.', false), ('D', 'Permanente o eventual.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 11.3 del TREBEP, además de los principios de igualdad, mérito y capacidad, ¿qué principio rige igualmente los procedimientos de selección del personal laboral temporal?', 'El art. 11.3 TREBEP añade, para el personal laboral temporal, el principio de celeridad, ya que su selección atiende a razones expresamente justificadas de necesidad y urgencia.', 'age_adm_41_personal', (select id from public.topics where slug = 'age-adm-41-personal'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 11.3 TREBEP', 'Los procedimientos de selección del personal laboral serán públicos, rigiéndose en todo caso por los principios de igualdad, mérito y capacidad. En el caso del personal laboral temporal se regirá igualmente por el principio de celeridad, teniendo por finalidad atender razones expresamente justificadas de necesidad y urgencia.', null, '5ee68474704696c628679857dcbc94baf04f51a30991654f3cec462d07c36995', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5ee68474704696c628679857dcbc94baf04f51a30991654f3cec462d07c36995')
