  select 'Una persona que ha trabajado cuatro años como asesora en el gabinete de un Ministro, nombrada como personal eventual, se presenta a un proceso selectivo y pide que ese tiempo se le valore como mérito. Según el artículo 12 del TREBEP:', 'El art. 12.4 TREBEP prohíbe que la condición de personal eventual constituya mérito, tanto para el acceso a la Función Pública como para la promoción interna.', 'age_adm_41_personal', (select id from public.topics where slug = 'age-adm-41-personal'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 12.4 TREBEP', 'La condición de personal eventual no podrá constituir mérito para el acceso a la Función Pública o para la promoción interna.', null, 'e64334169938f6961d954706abd81d67b51fe7d331cd8e6f728a049dbd512555', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e64334169938f6961d954706abd81d67b51fe7d331cd8e6f728a049dbd512555')
