  select 'Según el artículo 7 del TREBEP, el personal laboral al servicio de las Administraciones públicas se rige:', 'El art. 7 TREBEP combina la legislación laboral y las normas convencionales con los preceptos del Estatuto que así lo dispongan.', 'age_adm_41_personal', (select id from public.topics where slug = 'age-adm-41-personal'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 7 TREBEP', 'El personal laboral al servicio de las Administraciones públicas se rige, además de por la legislación laboral y por las demás normas convencionalmente aplicables, por los preceptos de este Estatuto que así lo dispongan.', null, '10aad2a23b19f222adaa6c3e579d7abba07147eccf23c66d49bd8d751cce177d', false
