  select 'Por un aumento puntual de expedientes, la Subdirección encarga a un funcionario del Subgrupo C1 tareas distintas de las de su puesto, adecuadas a su clasificación. Según el artículo 73.2 del TREBEP, esta asignación:', 'El art. 73.2 TREBEP permite asignar funciones, tareas o responsabilidades distintas de las del puesto si son adecuadas a la clasificación, grado o categoría y las necesidades del servicio lo justifican, siempre sin merma en las retribuciones.', 'age_adm_41_personal', (select id from public.topics where slug = 'age-adm-41-personal'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 73.2 TREBEP', 'Las Administraciones Públicas podrán asignar a su personal funciones, tareas o responsabilidades distintas a las correspondientes al puesto de trabajo que desempeñen siempre que resulten adecuadas a su clasificación, grado o categoría, cuando las necesidades del servicio lo justifiquen sin merma en las retribuciones.', null, 'b9ca99dd0f49c808528b2c24b2d4890cc079b6a31309ec2b75abeb591d7ef766', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b9ca99dd0f49c808528b2c24b2d4890cc079b6a31309ec2b75abeb591d7ef766')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es posible cuando las necesidades del servicio lo justifiquen, sin merma en las retribuciones.', true), ('B', 'Requiere en todo caso la convocatoria de un concurso de provisión.', false), ('C', 'Exige el consentimiento expreso del funcionario y la reducción proporcional de su jornada.', false), ('D', 'Solo es posible si el funcionario pasa a la situación de servicios especiales.', false)) as v(label, body, ok)
)
