with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con los registros de personal, el artículo 71 del TREBEP establece que:', 'El art. 71.1 TREBEP obliga a cada Administración Pública a constituir su propio Registro de personal; el contenido mínimo común se fija por convenio de Conferencia Sectorial (art. 71.3).', 'age_adm_41_personal', (select id from public.topics where slug = 'age-adm-41-personal'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 71.1 TREBEP', 'Cada Administración Pública constituirá un Registro en el que se inscribirán los datos relativos al personal contemplado en los artículos 2 y 5 del presente Estatuto y que tendrá en cuenta las peculiaridades de determinados colectivos.', null, '72bdb7495cc0b12e7690dd050436ecf729ee2cc8f85624c9a52bb84699b5fa03', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '72bdb7495cc0b12e7690dd050436ecf729ee2cc8f85624c9a52bb84699b5fa03')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Existirá un único Registro común a todas las Administraciones Públicas, gestionado por la Administración General del Estado.', false), ('B', 'Cada Administración Pública constituirá un Registro en el que se inscribirán los datos relativos a su personal.', true), ('C', 'Solo la Administración General del Estado está obligada a disponer de un registro de personal.', false), ('D', 'El personal de las entidades locales se inscribirá en el registro de la comunidad autónoma correspondiente.', false)) as v(label, body, ok)
)
