with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 23.2 de la Constitución Española, los ciudadanos tienen derecho a acceder en condiciones de igualdad a las funciones y cargos públicos:', 'El art. 23.2 CE reconoce el derecho de acceso en condiciones de igualdad a las funciones y cargos públicos y remite a las leyes la fijación de los requisitos.', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 23.2 CE', 'Asimismo, tienen derecho a acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen las leyes.', null, '643c418d01002c3d2b8c19c7e8292b10c3cf2b5a9b6a2f68cb5cecbe9e4746f8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '643c418d01002c3d2b8c19c7e8292b10c3cf2b5a9b6a2f68cb5cecbe9e4746f8')
  returning id
), o as (
