  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Con los requisitos que establezca cada Administración mediante reglamento.', false), ('B', 'Siempre que acrediten su residencia legal en España durante al menos cinco años.', false), ('C', 'Sin que puedan exigirse otros requisitos que la nacionalidad española.', false), ('D', 'Con los requisitos que señalen las leyes.', true)) as v(label, body, ok)
)
