with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 103.3 de la Constitución, la ley regulará el acceso a la función pública de acuerdo con los principios de:', 'El art. 103.3 CE remite a la ley el estatuto de los funcionarios y el acceso a la función pública conforme a los principios de mérito y capacidad. Junto con la igualdad del art. 23.2 CE, forman los principios constitucionales de acceso.', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 103.3 CE', 'La ley regulará el estatuto de los funcionarios públicos, el acceso a la función pública de acuerdo con los principios de mérito y capacidad, las peculiaridades del ejercicio de su derecho a sindicación, el sistema de incompatibilidades y las garantías para la imparcialidad en el ejercicio de sus funciones.', null, '98fe20fbfb53db90fa0c9fa8a0ec191d96046ed71424b103d4212e55233f5a74', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '98fe20fbfb53db90fa0c9fa8a0ec191d96046ed71424b103d4212e55233f5a74')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Mérito y capacidad.', true), ('B', 'Publicidad y transparencia.', false), ('C', 'Eficacia y jerarquía.', false), ('D', 'Objetividad y celeridad.', false)) as v(label, body, ok)
)
