with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 7 del Reglamento General de Ingreso (RD 364/1995), las necesidades de recursos humanos que no puedan cubrirse con los efectivos de personal existentes serán objeto de oferta de empleo público:', 'El art. 7 del RD 364/1995 condiciona la inclusión en la oferta a la existencia de crédito presupuestario y a la conveniencia de cubrir la necesidad durante el ejercicio.', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 7 RD 364/1995', 'Las necesidades de recursos humanos que no puedan ser cubiertas con los efectivos de personal existentes serán objeto de oferta de empleo público, siempre que exista crédito presupuestario y se considere conveniente su cobertura durante el ejercicio.', null, 'afde1c57f76c2d27492320cc93c57a03ba693f304e0b7ec53b87a455ae10e7de', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'afde1c57f76c2d27492320cc93c57a03ba693f304e0b7ec53b87a455ae10e7de')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En todo caso, aunque no exista crédito presupuestario, que se habilitará en el ejercicio siguiente.', false), ('B', 'Siempre que exista crédito presupuestario y se considere conveniente su cobertura durante el ejercicio.', true), ('C', 'Solo cuando lo solicite la Junta de Personal del departamento afectado.', false), ('D', 'Únicamente si las vacantes llevan más de tres años sin cubrir.', false)) as v(label, body, ok)
)
