with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 11 del RD 364/1995, los Tribunales de selección estarán constituidos por:', 'El art. 11 del RD 364/1995 exige número impar de miembros, todos funcionarios de carrera, no menos de cinco, con igual número de suplentes y titulación igual o superior a la exigida para el ingreso.', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 11 RD 364/1995', 'Estarán constituidos por un número impar de miembros, funcionarios de carrera, no inferior a cinco, debiendo designarse el mismo número de miembros suplentes y en su composición se velará por el cumplimiento del principio de especialidad.', null, 'f69dfe20886082101308260e7da10700f0c566a9b05492ee53f730bcc8666c9c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f69dfe20886082101308260e7da10700f0c566a9b05492ee53f730bcc8666c9c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un número par de miembros, no inferior a cuatro.', false), ('B', 'Un número impar de miembros, no inferior a tres, que podrán ser funcionarios interinos.', false), ('C', 'Cinco miembros como máximo, de los que uno será designado a propuesta sindical.', false), ('D', 'Un número impar de miembros, funcionarios de carrera, no inferior a cinco.', true)) as v(label, body, ok)
)
