with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Se propone como vocal de un tribunal a un funcionario que, hasta hace tres años, impartía clases en una academia que preparaba aspirantes a pruebas selectivas. Según el artículo 13.2 del RD 364/1995:', 'El art. 13.2 del RD 364/1995 excluye de los órganos de selección a quienes hayan preparado aspirantes en los cinco años anteriores a la publicación de la convocatoria. Tres años quedan dentro de ese periodo.', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 13.2 RD 364/1995', 'No podrán formar parte de los órganos de selección aquellos funcionarios que hubiesen realizado tareas de preparación de aspirantes a pruebas selectivas en los cinco años anteriores a la publicación de la correspondiente convocatoria.', null, '5d01a26ce93f14318704accff32054ee8b1ac8c677f8fa5b137e031cfc7d1021', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5d01a26ce93f14318704accff32054ee8b1ac8c677f8fa5b137e031cfc7d1021')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Puede formar parte del tribunal, porque han transcurrido más de dos años desde que dejó la preparación.', false), ('B', 'Puede formar parte del tribunal si lo autoriza el presidente.', false), ('C', 'No puede formar parte del órgano de selección, porque realizó tareas de preparación de aspirantes en los cinco años anteriores a la publicación de la convocatoria.', true), ('D', 'Solo puede actuar como asesor especialista, con voz y voto.', false)) as v(label, body, ok)
)
