with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 16.j) del RD 364/1995, desde la total conclusión de un ejercicio o prueba hasta el comienzo del siguiente deberá transcurrir un plazo:', 'El art. 16.j) del RD 364/1995 fija entre ejercicios un mínimo de 72 horas y un máximo de 45 días naturales.', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 16.j) RD 364/1995', 'Desde la total conclusión de un ejercicio o prueba hasta el comienzo del siguiente deberá transcurrir un plazo mínimo de setenta y dos horas y máximo de cuarenta y cinco días naturales.', null, '1c6898c302c9303c45762fc75333a1075471c96fbf2fc87e469b65e53fbba0e1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1c6898c302c9303c45762fc75333a1075471c96fbf2fc87e469b65e53fbba0e1')
