with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 4.1 del Reglamento General de Ingreso (RD 364/1995), ¿cuál es el sistema ordinario de ingreso del personal funcionario?', 'El art. 4.1 del RD 364/1995 establece la oposición como sistema ordinario; el concurso-oposición se usa cuando es más adecuado por la naturaleza de las funciones. El art. 61.6 TREBEP reserva el concurso a los casos previstos por ley.', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 4.1 RD 364/1995', 'La oposición será el sistema ordinario de ingreso, salvo cuando, por la naturaleza de las funciones a desempeñar, sea más adecuada la utilización del concurso-oposición y, excepcionalmente, del concurso.', null, '0eb48a63ad91c80d90142fa19246bd6e976a276a6773a5798267c66d9e3e847d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0eb48a63ad91c80d90142fa19246bd6e976a276a6773a5798267c66d9e3e847d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El concurso-oposición.', false), ('B', 'La oposición.', true), ('C', 'El concurso.', false), ('D', 'La libre designación.', false)) as v(label, body, ok)
)
