with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 27.1 del RD 364/1995, el nombramiento del personal funcionario interino de la Administración General del Estado se efectuará, con arreglo a los principios de mérito y capacidad, por:', 'El art. 27.1 del RD 364/1995 atribuye el nombramiento al Subsecretario del departamento de adscripción del Cuerpo o Escala o, para los Cuerpos y Escalas dependientes de la Secretaría de Estado competente en función pública, al Director general de la Función Pública. El procedimiento debe ser ágil, por la urgencia de la cobertura.', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 27.1 RD 364/1995', 'El nombramiento del personal funcionario interino se efectuará, con arreglo a los principios de mérito y capacidad, por el Subsecretario del Departamento al que figuren adscritos los correspondientes Cuerpos y Escalas o por el Director general de la Función Pública, cuando se trate de Cuerpos y Escalas dependientes de la Secretaría de Estado para la Administración Pública.', null, '91977124e926b80746d32aef498b44899c2e97210cf563f2ba70a46c0e894ba0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '91977124e926b80746d32aef498b44899c2e97210cf563f2ba70a46c0e894ba0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Ministro del Departamento en el que vaya a prestar servicios.', false), ('B', 'El Consejo de Ministros, a propuesta del Ministro competente en materia de función pública.', false), ('C', 'El tribunal calificador de la última convocatoria del Cuerpo o Escala.', false), ('D', 'El Subsecretario del Departamento al que figuren adscritos los Cuerpos y Escalas o, en su caso, el Director general de la Función Pública.', true)) as v(label, body, ok)
)
