with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Además de los principios constitucionales, el artículo 55.2 del TREBEP exige que los procedimientos de selección garanticen, entre otros, el principio de:', 'El art. 55.2 TREBEP enumera la publicidad de convocatorias y bases, la transparencia, la imparcialidad y profesionalidad de los miembros de los órganos de selección, su independencia y discrecionalidad técnica, la adecuación de las pruebas a las funciones y la agilidad.', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 55.2 TREBEP', 'd) Independencia y discrecionalidad técnica en la actuación de los órganos de selección.', null, '5686f5f416b385319137047c936781e95147e3b45d097100b6e8e0bfec9802bd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5686f5f416b385319137047c936781e95147e3b45d097100b6e8e0bfec9802bd')
