insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un ciudadano de un país no perteneciente a la Unión Europea, con residencia legal en España, pregunta en la oficina de información si puede presentarse a las pruebas de la Administración General del Estado. Según el artículo 57 del TREBEP, podrá acceder:', 'El art. 57.4 TREBEP permite a los extranjeros con residencia legal en España acceder como personal laboral en igualdad de condiciones que los españoles. El acceso como funcionario queda reservado a los nacionales de la UE y asimilados (art. 57.1-3), salvo exención por ley (art. 57.5).', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 57.4 TREBEP', 'Los extranjeros a los que se refieren los apartados anteriores, así como los extranjeros con residencia legal en España podrán acceder a las Administraciones Públicas, como personal laboral, en igualdad de condiciones que los españoles.', null, '90ceddb664699ff6f819d5bd06702ffa10f1b1d63ae6bf0a1d7e0fb4aee5a0e8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '90ceddb664699ff6f819d5bd06702ffa10f1b1d63ae6bf0a1d7e0fb4aee5a0e8')
  returning id
