  select 'Según el artículo 57.5 del TREBEP, ¿qué norma puede eximir del requisito de la nacionalidad por razones de interés general para el acceso a la condición de personal funcionario?', 'El art. 57.5 TREBEP reserva a la ley, estatal o autonómica, la exención del requisito de nacionalidad para acceder como funcionario.', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 57.5 TREBEP', 'Sólo por ley de las Cortes Generales o de las asambleas legislativas de las comunidades autónomas podrá eximirse del requisito de la nacionalidad por razones de interés general para el acceso a la condición de personal funcionario.', null, 'bb0bce27127e77b64dc23478b01288ffe6c5eeef89f543126786317ac85f0aa4', false
