  select 'Según el artículo 70.2 del TREBEP, la Oferta de empleo público o instrumento similar:', 'El art. 70.2 TREBEP atribuye la aprobación anual de la Oferta a los órganos de Gobierno de cada Administración y exige su publicación en el diario oficial.', 'age_adm_42_seleccion', (select id from public.topics where slug = 'age-adm-42-seleccion'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 70.2 TREBEP', 'La Oferta de empleo público o instrumento similar, que se aprobará anualmente por los órganos de Gobierno de las Administraciones Públicas, deberá ser publicada en el Diario oficial correspondiente.', null, '26a65f3b518f4802c3f175ea688e905c25e5fe3b24eaf56093e2348e7bd72a4f', false
