with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 36 del RD 364/1995, ¿mediante qué procedimientos podrán cubrirse temporalmente los puestos de trabajo adscritos a funcionarios, en los supuestos previstos en el Reglamento?', 'El art. 36 del RD 364/1995 distingue entre provisión ordinaria (concurso, sistema normal, y libre designación), redistribución o reasignación de efectivos y provisión temporal (comisión de servicios y adscripción provisional).', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 36.3 RD 364/1995', 'Temporalmente podrán ser cubiertos mediante comisión de servicios y adscripción provisional, en los supuestos previstos en este Reglamento.', null, 'e2e64a1d4cfea394f7783d92a1fbfdc9fb42857e6b0d57e74d7063bf4b7b5c59', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e2e64a1d4cfea394f7783d92a1fbfdc9fb42857e6b0d57e74d7063bf4b7b5c59')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Concurso y libre designación.', false), ('B', 'Redistribución de efectivos y reasignación de efectivos.', false), ('C', 'Comisión de servicios y adscripción provisional.', true), ('D', 'Concurso específico y permuta.', false)) as v(label, body, ok)
)
