with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Con carácter general, según el artículo 41.2 del RD 364/1995, ¿cuánto tiempo deben permanecer los funcionarios en cada puesto de destino definitivo para poder participar en los concursos de provisión?', 'El art. 41.2 del RD 364/1995 exige dos años de permanencia en el destino definitivo. No se exigen dentro del ámbito de una Secretaría de Estado o de un departamento ni en caso de supresión del puesto.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 41.2 RD 364/1995', 'Los funcionarios deberán permanecer en cada puesto de trabajo de destino definitivo un mínimo de dos años para poder participar en los concursos de provisión', null, 'b8195eb08cd6f3a06170d2c9f95a10a09c8c30ba1d207f04e66c308ec047324d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b8195eb08cd6f3a06170d2c9f95a10a09c8c30ba1d207f04e66c308ec047324d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mínimo de un año.', false), ('B', 'Un mínimo de dos años.', true), ('C', 'Un mínimo de tres años.', false), ('D', 'Un mínimo de seis meses.', false)) as v(label, body, ok)
)
