with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 42.2 del RD 364/1995, el plazo de presentación de instancias en los concursos de provisión de puestos de trabajo será de:', 'El art. 42.2 del RD 364/1995 fija quince días hábiles desde el día siguiente al de la publicación en el BOE.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 42.2 RD 364/1995', 'El plazo de presentación de instancias será de quince días hábiles, contados a partir del siguiente al de la publicación de la convocatoria en el «Boletín Oficial del Estado».', null, '3769010d3d34182819f10592635062f84a14516d5f475141cc3de7bc238d3faf', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3769010d3d34182819f10592635062f84a14516d5f475141cc3de7bc238d3faf')
