with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 44.3 del RD 364/1995, en los concursos, la puntuación de cada uno de los conceptos de mérito:', 'El art. 44.3 del RD 364/1995 limita cada concepto a una horquilla de entre el 10 % y el 40 % de la puntuación máxima total.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 44.3 RD 364/1995', 'La puntuación de cada uno de los conceptos enunciados en los apartados anteriores no podrá exceder en ningún caso del 40 por 100 de la puntuación máxima total ni ser inferior al 10 por 100 de la misma.', null, '8e1a81c7b414dd56d8b6b804fd7c148669d140b93ea5e43e82cbbbfa87365a1c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8e1a81c7b414dd56d8b6b804fd7c148669d140b93ea5e43e82cbbbfa87365a1c')
  returning id
), o as (
