  select 'De acuerdo con el artículo 46.1 del RD 364/1995, las Comisiones de Valoración de los concursos estarán constituidas:', 'El art. 46.1 del RD 364/1995 exige un mínimo de cuatro miembros designados por la autoridad convocante, al menos uno a propuesta del centro directivo de administración de personal. Los representantes sindicales nunca pueden igualar o superar a los de la Administración.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 46.1 RD 364/1995', 'Las Comisiones de Valoración estarán constituidas como mínimo por cuatro miembros designados por la autoridad convocante, de los que uno, al menos, será designado a propuesta del centro directivo al que corresponda la administración de personal.', null, '4bde9ea3bcec0306e89fddc4de4d59e87988fb8ec30e02199f59d008f612c32e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4bde9ea3bcec0306e89fddc4de4d59e87988fb8ec30e02199f59d008f612c32e')
