with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario destinado en Sevilla obtiene por concurso un puesto en Madrid, lo que implica cambio de residencia. Según el artículo 48.1 del RD 364/1995, ¿de qué plazo dispone para tomar posesión?', 'El art. 48.1 del RD 364/1995 fija tres días hábiles si no hay cambio de residencia y un mes si lo hay o si se trata de reingreso al servicio activo.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 48.1 RD 364/1995', 'El plazo para tomar posesión será de tres días hábiles si no implica cambio de residencia del funcionario, o de un mes si comporta cambio de residencia o el reingreso al servicio activo.', null, '93cd719494298c6610c9e3179cc3a3c56863a1e486f5263520739c233e122344', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '93cd719494298c6610c9e3179cc3a3c56863a1e486f5263520739c233e122344')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De tres días hábiles.', false), ('B', 'De un mes.', true), ('C', 'De quince días hábiles.', false), ('D', 'De veinte días naturales.', false)) as v(label, body, ok)
)
