with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una funcionaria obtiene destino en un concurso y, antes de tomar posesión, decide que prefiere quedarse en su puesto actual. Según el artículo 49.1 del RD 364/1995:', 'El art. 49.1 del RD 364/1995 declara irrenunciables los destinos adjudicados. La única salvedad es haber obtenido otro destino por convocatoria pública antes de que termine el plazo de toma de posesión.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 49.1 RD 364/1995', 'Los destinos adjudicados serán irrenunciables, salvo que, antes de finalizar el plazo de toma de posesión, se hubiere obtenido otro destino mediante convocatoria pública.', null, 'e404b40ccc956157a3fc2ea0baa9c8e650c6afdefd0a51e1b7022ded20574c72', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e404b40ccc956157a3fc2ea0baa9c8e650c6afdefd0a51e1b7022ded20574c72')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El destino es irrenunciable, salvo que antes de finalizar el plazo de toma de posesión haya obtenido otro destino mediante convocatoria pública.', true), ('B', 'Puede renunciar libremente en cualquier momento antes de la toma de posesión.', false), ('C', 'Puede renunciar dentro de los diez días siguientes a la publicación de la resolución del concurso.', false), ('D', 'Puede renunciar si lo autoriza el Subsecretario de su departamento de origen.', false)) as v(label, body, ok)
)
