with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la provisión por libre designación, si el nombramiento va a recaer en un funcionario destinado en otro departamento, el artículo 54.1 del RD 364/1995 exige informe favorable de este. ¿Qué ocurre si no se emite en plazo?', 'El art. 54.1 del RD 364/1995 entiende favorable el informe no emitido en quince días naturales. Aunque sea desfavorable, el nombramiento puede hacerse con autorización del Secretario de Estado competente.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 54.1 RD 364/1995', 'Si fuera a recaer en un funcionario destinado en otro Departamento, se requerirá informe favorable de éste. De no emitirse en el plazo de quince días naturales se considerará favorable.', null, 'fb5371e09b644bc2234048618b6faf56e2105da414c4ab1551a8e500e24c298c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fb5371e09b644bc2234048618b6faf56e2105da414c4ab1551a8e500e24c298c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Si no se emite en el plazo de diez días hábiles, se considerará desfavorable.', false), ('B', 'Si no se emite en el plazo de un mes, el procedimiento queda suspendido.', false), ('C', 'Si no se emite en el plazo de quince días hábiles, la convocatoria se declara desierta.', false), ('D', 'Si no se emite en el plazo de quince días naturales, se considerará favorable.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 64.3 del RD 364/1995, las comisiones de servicios tendrán una duración máxima de:', 'El art. 64.3 del RD 364/1995 fija un año, prorrogable por otro si el puesto no se ha cubierto con carácter definitivo.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 64.3 RD 364/1995', 'Las citadas comisiones de servicios tendrán una duración máxima de un año prorrogable por otro en caso de no haberse cubierto el puesto con carácter definitivo', null, '6f5a6a156fa76b2db501701a7ab6462040c8ea97fafa3a099c57844412e252a6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6f5a6a156fa76b2db501701a7ab6462040c8ea97fafa3a099c57844412e252a6')
  returning id
), o as (
