  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Seis meses, prorrogables por otros seis.', false), ('B', 'Dos años, improrrogables.', false), ('C', 'Tres años, prorrogables por uno más.', false), ('D', 'Un año, prorrogable por otro en caso de no haberse cubierto el puesto con carácter definitivo.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
