with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 59.1 del RD 364/1995, mediante la redistribución de efectivos, los funcionarios que ocupen con carácter definitivo puestos no singularizados podrán ser adscritos, por necesidades del servicio, a otros puestos:', 'El art. 59.1 del RD 364/1995 exige identidad de naturaleza, nivel y complemento específico y el mismo procedimiento de provisión, y prohíbe el cambio de municipio. El puesto así obtenido tiene carácter definitivo.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 59.1 RD 364/1995', 'Los funcionarios que ocupen con carácter definitivo puestos no singularizados podrán ser adscritos, por necesidades del servicio, a otros de la misma naturaleza, nivel de complemento de destino y complemento específico, siempre que para la provisión de los referidos puestos esté previsto el mismo procedimiento y sin que ello suponga cambio de municipio.', null, '98897e9a2e2f8e3c538ae5cd8a81bd0bdf4409d49bf4968a9015e7dc8b656292', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '98897e9a2e2f8e3c538ae5cd8a81bd0bdf4409d49bf4968a9015e7dc8b656292')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De nivel superior, siempre que se produzca dentro de la misma provincia.', false), ('B', 'De cualquier naturaleza y nivel, con carácter provisional y por un máximo de un año.', false), ('C', 'De la misma naturaleza, nivel de complemento de destino y complemento específico, sin que ello suponga cambio de municipio.', true), ('D', 'De la misma naturaleza, aunque suponga cambio de municipio, con derecho a indemnización.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
