  select 'Según el artículo 70.2 del RD 364/1995, los funcionarios de carrera adquieren un grado personal por el desempeño de uno o más puestos del nivel correspondiente durante:', 'El art. 70.2 del RD 364/1995 exige dos años continuados o tres con interrupción, sea cual sea el sistema de provisión.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 70.2 RD 364/1995', 'Todos los funcionarios de carrera adquirirán un grado personal por el desempeño de uno o más puestos del nivel correspondiente durante dos años continuados o tres con interrupción', null, '168ddfb585707ba069add2c3c4f62efc6c9c77cf424046fdacf21084606701af', false
