with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 73 del RD 364/1995, la promoción interna consiste en:', 'El art. 73 del RD 364/1995 incluye en la promoción interna el ascenso al Grupo inmediato superior y el acceso a otros Cuerpos o Escalas del mismo Grupo. Ascender en la estructura de puestos es carrera vertical, y progresar de grado sin cambiar de puesto, carrera horizontal (art. 16.3 TREBEP).', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 73 RD 364/1995', 'La promoción interna consiste en el ascenso desde Cuerpos o Escalas de un Grupo de titulación a otro del inmediato superior o en el acceso a Cuerpos o Escalas del mismo Grupo de titulación.', null, '9d8d5b64226c42b20cb0b15291032bbaf4904f612b27a8b344a106f46f09b2ab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9d8d5b64226c42b20cb0b15291032bbaf4904f612b27a8b344a106f46f09b2ab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El ascenso en la estructura de puestos de trabajo mediante concurso o libre designación.', false), ('B', 'El ascenso desde Cuerpos o Escalas de un Grupo de titulación a otro del inmediato superior o en el acceso a Cuerpos o Escalas del mismo Grupo de titulación.', true), ('C', 'La progresión de grado o escalón sin necesidad de cambiar de puesto de trabajo.', false), ('D', 'La consolidación de un grado personal superior al del puesto desempeñado.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
