with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un proceso de promoción interna por concurso-oposición, un funcionario obtiene muchos puntos en la fase de concurso, pero no alcanza la nota mínima de un ejercicio de la oposición. Según el artículo 74.2 del RD 364/1995:', 'El art. 74.2 del RD 364/1995 permite fijar una puntuación mínima de concurso para acceder a la oposición, pero prohíbe usar la puntuación del concurso para superar los ejercicios.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 74.2 RD 364/1995', 'En ningún caso la puntuación obtenida en la fase de concurso podrá aplicarse para superar los ejercicios de la fase de oposición.', null, '18a14c1a0ce4bcccf9faf9509db5faacbc0281a57dfdd03c3fec5bfaa1d0be7e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '18a14c1a0ce4bcccf9faf9509db5faacbc0281a57dfdd03c3fec5bfaa1d0be7e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los puntos de la fase de concurso se suman a la nota del ejercicio para superarlo.', false), ('B', 'Puede compensar el ejercicio no superado si la puntuación de concurso supera el 40 por 100 del total.', false), ('C', 'La Comisión de Valoración puede declararle apto si su antigüedad supera diez años.', false), ('D', 'La puntuación de la fase de concurso no puede aplicarse en ningún caso para superar los ejercicios de la fase de oposición.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 78.1 del RD 364/1995, los funcionarios que accedan a otros Cuerpos y Escalas por el turno de promoción interna:', 'El art. 78.1 del RD 364/1995 da preferencia a los aspirantes de promoción interna para cubrir las vacantes de la convocatoria.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 78.1 RD 364/1995', 'Los funcionarios que accedan a otros Cuerpos y Escalas por el turno de promoción interna tendrán, en todo caso, preferencia para cubrir los puestos vacantes de la respectiva convocatoria sobre los aspirantes que no procedan de este turno.', null, 'd31a1f1b665c7e5d498744a1b844af41ff3e6b2eea08f9b5d061895753c6cd40', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd31a1f1b665c7e5d498744a1b844af41ff3e6b2eea08f9b5d061895753c6cd40')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tendrán, en todo caso, preferencia para cubrir los puestos vacantes de la respectiva convocatoria sobre los aspirantes que no procedan de este turno.', true), ('B', 'Elegirán destino después de los aspirantes del turno libre.', false), ('C', 'Elegirán destino junto con los aspirantes del turno libre, según la puntuación total obtenida.', false), ('D', 'Deberán permanecer obligatoriamente en el puesto que vinieran desempeñando.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la disposición adicional novena del RD 364/1995, para la promoción interna desde Cuerpos o Escalas del Grupo D al Grupo C, a falta de la titulación requerida, se exigirá:', 'La disposición adicional novena del RD 364/1995 permite suplir la titulación con diez años de antigüedad en el Grupo D, o con cinco años más un curso específico de formación al que se accede por criterios objetivos.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Disp. adic. 9.ª RD 364/1995', 'A estos efectos se requerirá la titulación establecida en el artículo 25 de la Ley 30/1984, de 2 de agosto, o una antigüedad de diez años en un Cuerpo o Escala del Grupo D, o de cinco años y la superación de un curso específico de formación al que se accederá por criterios objetivos.', 'El RD 364/1995 usa la clasificación anterior al TREBEP (Grupos C y D). Según la disposición transitoria tercera del TREBEP, el antiguo Grupo C equivale al Subgrupo C1 y el D al C2; conviene confirmar que la redacción de la pregunta es adecuada.', '46391765eaa27fd3eb1842d8af3fbb47d252fb883f28b9a797ce09103e45e2de', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '46391765eaa27fd3eb1842d8af3fbb47d252fb883f28b9a797ce09103e45e2de')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una antigüedad de cinco años en un Cuerpo o Escala del Grupo D, o de tres años y la superación de un curso específico de formación.', false), ('B', 'Una antigüedad de dos años en el Grupo D y la superación de una prueba de nivel.', false), ('C', 'Una antigüedad de diez años en un Cuerpo o Escala del Grupo D, o de cinco años y la superación de un curso específico de formación.', true), ('D', 'Una antigüedad de quince años en el Grupo D, sin posibilidad de sustituirla por un curso.', false)) as v(label, body, ok)
)
