with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes es un derecho de carácter individual de los empleados públicos según el artículo 14 del TREBEP?', 'El art. 14.g) TREBEP recoge el derecho individual a la formación continua. La libertad sindical, la huelga y los conflictos colectivos son derechos individuales que se ejercen de forma colectiva (art. 15).', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 14.g) TREBEP', 'g) A la formación continua y a la actualización permanente de sus conocimientos y capacidades profesionales, preferentemente en horario laboral.', null, '79f8aa6af14069a93ef576587f63c71e5db74d4d108ef9c31005e4004051323b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '79f8aa6af14069a93ef576587f63c71e5db74d4d108ef9c31005e4004051323b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La libertad sindical.', false), ('B', 'El ejercicio de la huelga, con la garantía del mantenimiento de los servicios esenciales.', false), ('C', 'La formación continua y la actualización permanente de sus conocimientos y capacidades profesionales, preferentemente en horario laboral.', true), ('D', 'El planteamiento de conflictos colectivos de trabajo.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
