with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 52 del TREBEP, ¿cuál de los siguientes figura entre los principios que inspiran el Código de Conducta de los empleados públicos?', 'El art. 52 TREBEP enumera, entre otros, objetividad, integridad, neutralidad, responsabilidad, imparcialidad, confidencialidad, dedicación al servicio público, transparencia, ejemplaridad, austeridad, accesibilidad, eficacia y honradez.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 52 TREBEP', 'deberán actuar con arreglo a los siguientes principios: objetividad, integridad, neutralidad, responsabilidad, imparcialidad, confidencialidad, dedicación al servicio público, transparencia, ejemplaridad, austeridad, accesibilidad, eficacia, honradez, promoción del entorno cultural y medioambiental, y respeto a la igualdad entre mujeres y hombres', null, 'fdebc5260cc05ee954c268654c66ba2af8c9149586a870dfdf77502bbfdb563d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fdebc5260cc05ee954c268654c66ba2af8c9149586a870dfdf77502bbfdb563d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Rentabilidad.', false), ('B', 'Ejemplaridad.', true), ('C', 'Discrecionalidad.', false), ('D', 'Oportunidad.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una jefa de sección ordena a un funcionario que registre una solicitud con fecha anterior a la de su presentación real, lo que supone una infracción manifiesta del ordenamiento jurídico. Según el artículo 54.3 del TREBEP, el funcionario:', 'El art. 54.3 TREBEP obliga a obedecer las órdenes profesionales de los superiores, salvo las que constituyan una infracción manifiesta del ordenamiento; en ese caso deben comunicarse de inmediato a los órganos de inspección.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 54.3 TREBEP', 'Obedecerán las instrucciones y órdenes profesionales de los superiores, salvo que constituyan una infracción manifiesta del ordenamiento jurídico, en cuyo caso las pondrán inmediatamente en conocimiento de los órganos de inspección procedentes.', null, 'd4696084eeb3f6d90687328c25b173789b0d8e17f57b09ad97c271ad847ab31b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd4696084eeb3f6d90687328c25b173789b0d8e17f57b09ad97c271ad847ab31b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No está obligado a obedecer y debe ponerlo inmediatamente en conocimiento de los órganos de inspección procedentes.', true), ('B', 'Debe obedecer y, después, presentar un recurso de alzada contra la orden.', false), ('C', 'Debe obedecer, porque las órdenes de los superiores son siempre vinculantes.', false), ('D', 'Puede negarse, pero solo si lo autoriza previamente la Junta de Personal.', false)) as v(label, body, ok)
)
