select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Entre los principios de conducta del artículo 54 del TREBEP, los empleados públicos garantizarán la atención al ciudadano:', 'El art. 54.11 TREBEP garantiza la atención en la lengua que solicite el ciudadano, siempre que sea oficial en el territorio.', 'age_adm_45_provision_carrera', (select id from public.topics where slug = 'age-adm-45-provision-carrera'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 54.11 TREBEP', 'Garantizarán la atención al ciudadano en la lengua que lo solicite siempre que sea oficial en el territorio.', null, '0a2efc760cfe84f8957fec50521f851c6eaee599f6dbc38110898cefc19dda03', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0a2efc760cfe84f8957fec50521f851c6eaee599f6dbc38110898cefc19dda03')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exclusivamente en castellano, como lengua oficial del Estado.', false), ('B', 'En cualquier lengua de la Unión Europea que solicite.', false), ('C', 'En la lengua que elija el empleado público entre las oficiales del territorio.', false), ('D', 'En la lengua que lo solicite siempre que sea oficial en el territorio.', true)) as v(label, body, ok)
)
