insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 53/1984, de 26 de diciembre, de Incompatibilidades del personal al servicio de las Administraciones Públicas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-46-incompatibilidades', 'IV.6 Las incompatibilidades y el régimen disciplinario') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-46-incompatibilidades' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1.1 de la Ley 53/1984, de Incompatibilidades del personal al servicio de las Administraciones Públicas, el personal incluido en su ámbito de aplicación:', 'El art. 1.1 de la Ley 53/1984 sienta el principio de dedicación a un solo puesto en el sector público, con las excepciones previstas en la propia ley. Las actividades privadas no se prohíben de forma absoluta: requieren reconocimiento de compatibilidad (art. 14).', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 1.1 Ley 53/1984', 'El personal comprendido en el ámbito de aplicación de esta Ley no podrá compatibilizar sus actividades con el desempeño, por sí o mediante sustitución, de un segundo puesto de trabajo, cargo o actividad en el sector público, salvo en los supuestos previstos en la misma.', null, '6770d09113373c955031887297b96dfe7660aa00cc238b7d9ee67d9ddf19a902', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6770d09113373c955031887297b96dfe7660aa00cc238b7d9ee67d9ddf19a902')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No podrá compatibilizar sus actividades con el desempeño de un segundo puesto de trabajo, cargo o actividad en el sector público, salvo en los supuestos previstos en la misma.', true), ('B', 'Podrá desempeñar libremente un segundo puesto en el sector público si no coincide en horario con el principal.', false), ('C', 'Podrá desempeñar hasta dos puestos en el sector público, previa comunicación a su superior jerárquico.', false), ('D', 'No podrá ejercer ninguna actividad privada, en ningún caso.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 3.1 de la Ley 53/1984, para el ejercicio de una segunda actividad en el sector público será indispensable:', 'El art. 3.1 de la Ley 53/1984 exige autorización previa y expresa, que no modifica jornada ni horario de ninguno de los dos puestos y se condiciona a su estricto cumplimiento. Se concede siempre en razón del interés público.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 3.1 Ley 53/1984', 'Para el ejercicio de la segunda actividad será indispensable la previa y expresa autorización de compatibilidad, que no supondrá modificación de la jornada de trabajo y horario de los dos puestos y que se condiciona a su estricto cumplimiento en ambos.', null, 'ac1061d27e87fea3ad467a55fee67b0d8483c14857557dbfd42e242f8e037482', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ac1061d27e87fea3ad467a55fee67b0d8483c14857557dbfd42e242f8e037482')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La simple comunicación al órgano de personal en los diez días siguientes al inicio de la actividad.', false), ('B', 'La previa y expresa autorización de compatibilidad, que no supondrá modificación de la jornada de trabajo y horario de los dos puestos.', true), ('C', 'La autorización de compatibilidad, que podrá conceder la reducción de jornada en el puesto principal.', false), ('D', 'La autorización tácita, que se entiende concedida si no se resuelve en un mes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3.2 de la Ley 53/1984, ¿qué efecto tiene el desempeño de un puesto de trabajo en el sector público sobre la percepción de una pensión de jubilación o retiro por Derechos Pasivos o por cualquier régimen público y obligatorio de Seguridad Social?', 'El art. 3.2 de la Ley 53/1984 declara incompatible el puesto público con la pensión de jubilación o retiro y deja la pensión en suspenso, sin afectar a sus actualizaciones. En el ámbito laboral, la jubilación parcial es compatible con un puesto a tiempo parcial.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 3.2 Ley 53/1984', 'La percepción de las pensiones indicadas quedará en suspenso por el tiempo que dure el desempeño de dicho puesto, sin que ello afecte a sus actualizaciones.', null, 'ee8f43b329a3781bca0ef526e0270e316249143e20447f677dab818981d77a14', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ee8f43b329a3781bca0ef526e0270e316249143e20447f677dab818981d77a14')
  returning id
