insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario de la Administración General del Estado es elegido concejal de su ayuntamiento, sin dedicación exclusiva. Según el artículo 5.1 de la Ley 53/1984:', 'El art. 5.1.b) de la Ley 53/1984 permite compatibilizar la actividad con el cargo de miembro de una corporación local, salvo que se desempeñe un cargo retribuido en dedicación exclusiva. Según el art. 5.2, solo se percibe la retribución de una actividad, sin perjuicio de dietas, indemnizaciones o asistencias por la otra.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 5.1.b) Ley 53/1984', 'b) Miembros de las Corporaciones locales, salvo que desempeñen en las mismas cargos retribuidos en régimen de dedicación exclusiva.', null, 'd508ae1fb1d28dc1cb7b0752031714eb5e304fabb153c8ab7cce9a5cafa88bb8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd508ae1fb1d28dc1cb7b0752031714eb5e304fabb153c8ab7cce9a5cafa88bb8')
  returning id
), o as (
