  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Debe pasar necesariamente a la situación de servicios especiales.', false), ('B', 'Debe optar por uno de los dos cargos en el plazo de toma de posesión.', false), ('C', 'Puede compatibilizar su puesto con el cargo electivo, porque no desempeña en la corporación un cargo retribuido en régimen de dedicación exclusiva.', true), ('D', 'Solo puede compatibilizarlo si renuncia a cualquier dieta o indemnización por asistencias.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Para autorizar la compatibilidad de actividades públicas, el artículo 7.1 de la Ley 53/1984 exige que la cantidad total percibida por ambos puestos no supere la remuneración prevista en los Presupuestos Generales del Estado para el cargo de Director General ni la correspondiente al puesto principal incrementada, para los funcionarios del grupo C o personal de nivel equivalente, en:', 'El art. 7.1 de la Ley 53/1984 escalona el incremento por grupos: 30 % (A), 35 % (B), 40 % (C), 45 % (D) y 50 % (E). Superar estos límites requiere acuerdo expreso del Gobierno, del órgano autonómico competente o del Pleno de la corporación local.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 7.1 Ley 53/1984', '– Un 40 por 100, para los funcionarios del grupo C o personal de nivel equivalente.', null, '2b9966a7895b9b4be6ee89e6853b66c11b3b2cbf93804c15ba20ccdb23ec9622', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2b9966a7895b9b4be6ee89e6853b66c11b3b2cbf93804c15ba20ccdb23ec9622')
  returning id
), o as (
