)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una funcionaria que ocupa un puesto en un organismo autónomo supera una oposición a otro cuerpo, cuyo puesto es incompatible con el que ya tiene, y no ejerce ninguna opción. Según el artículo 10 de la Ley 53/1984:', 'El art. 10 de la Ley 53/1984 obliga a optar dentro del plazo de toma de posesión; si no se opta, se entiende elegido el nuevo puesto, con excedencia voluntaria en el anterior.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 10 Ley 53/1984', 'Quienes accedan por cualquier título a un nuevo puesto del sector público que con arreglo a esta Ley resulte incompatible con el que vinieran desempeñando habrán de optar por uno de ellos dentro del plazo de toma de posesión. A falta de opción en el plazo señalado se entenderá que optan por el nuevo puesto, pasando a la situación de excedencia voluntaria en los que vinieran desempeñando.', null, '9c3c2308a90cbad62bdd96e200a74bafe0546a801c50db8e954962e3e5802854', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9c3c2308a90cbad62bdd96e200a74bafe0546a801c50db8e954962e3e5802854')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se entenderá que opta por el puesto que venía desempeñando y perderá el derecho al nuevo nombramiento.', false), ('B', 'Se entenderá que opta por el puesto mejor retribuido.', false), ('C', 'La Administración la declarará en situación de suspensión de funciones hasta que opte.', false), ('D', 'Se entenderá que opta por el nuevo puesto y pasará a la situación de excedencia voluntaria en el que venía desempeñando.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
