with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 12.1 de la Ley 53/1984, el personal incluido en su ámbito de aplicación no podrá tener, en las empresas o sociedades concesionarias o contratistas de obras, servicios o suministros con el sector público, una participación en el capital superior al:', 'El art. 12.1.d) de la Ley 53/1984 prohíbe en todo caso la participación superior al 10 % en el capital de las empresas o sociedades del párrafo c): concesionarias, contratistas, arrendatarias, etc.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 12.1.d) Ley 53/1984', 'd) La participación superior al 10 por 100 en el capital de las Empresas o Sociedades a que se refiere el párrafo anterior.', null, '9dc654339348ef3c875453cda12c678eb78d8b968b4c2891ce71bd6b9d9086b3', false
