with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 14 de la Ley 53/1984, la resolución motivada que reconozca la compatibilidad para actividades privadas o declare la incompatibilidad se dictará en el plazo de:', 'El art. 14 de la Ley 53/1984 exige reconocimiento previo de compatibilidad para actividades profesionales, laborales, mercantiles o industriales fuera de la Administración, mediante resolución motivada que debe dictarse en dos meses.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 14 Ley 53/1984', 'La resolución motivada reconociendo la compatibilidad o declarando la incompatibilidad, que se dictará en el plazo de dos meses', null, '5378a741e197e6ad7cc2e8e54efab1f83bbd427a86d3435fa3e050a28457963b', false
