with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 16.4 de la Ley 53/1984, por excepción podrá reconocerse compatibilidad para actividades privadas al personal cuyo puesto comporte la percepción de complemento específico, siempre que su cuantía:', 'El art. 16.4 de la Ley 53/1984 fija el límite en el 30 % de la retribución básica, sin computar los conceptos derivados de la antigüedad, y mantiene las limitaciones de los arts. 1.3, 11, 12 y 13.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 16.4 Ley 53/1984', 'podrá reconocerse compatibilidad para el ejercicio de actividades privadas al personal que desempeñe puestos de trabajo que comporten la percepción de complementos específicos, o concepto equiparable, cuya cuantía no supere el 30 por 100 de su retribución básica, excluidos los conceptos que tengan su origen en la antigüedad.', 'El art. 16.1 tiene una nueva redacción (disp. final 3.ª TREBEP) que solo surtirá efectos cuando se aprueben las leyes de Función Pública de desarrollo (disp. final 4.ª TREBEP). La excepción del 16.4 se ha redactado sobre el texto consolidado vigente; conviene revisarla si cambia el régimen del apartado 1.', '021706e05dc888b51fbcbbb985e3b9618e497714a5048d902da86ed47873c90c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '021706e05dc888b51fbcbbb985e3b9618e497714a5048d902da86ed47873c90c')
