  select '¿Cuál de las siguientes actividades queda exceptuada del régimen de incompatibilidades según el artículo 19 de la Ley 53/1984?', 'El art. 19.c) de la Ley 53/1984 excluye del régimen de incompatibilidades la participación en tribunales calificadores. Las otras tres actividades están expresamente prohibidas por el art. 12.1.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 19.c) Ley 53/1984', 'c) La participación en Tribunales calificadores de pruebas selectivas para ingreso en las Administraciones Públicas.', null, '191e1d7502c3eddc1cc77da78abcf8e2b575c8853f37e58f7ff58f5389364939', false
