with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 93.2 del TREBEP, los funcionarios públicos o el personal laboral que indujeren a otros a la realización de actos o conductas constitutivos de falta disciplinaria:', 'El art. 93.2 TREBEP equipara la responsabilidad de quien induce a la del autor de la falta. El encubrimiento de faltas muy graves o graves genera responsabilidad cuando cause daño grave a la Administración o a los ciudadanos (art. 93.3).', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 93.2 TREBEP', 'Los funcionarios públicos o el personal laboral que indujeren a otros a la realización de actos o conductas constitutivos de falta disciplinaria incurrirán en la misma responsabilidad que éstos.', null, '0b9f7c1a54c724c1b14d92d9c9a7d3e61c850edd9dfe5f76658c9d49348c043c', false
