with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes es uno de los principios de ejercicio de la potestad disciplinaria recogidos en el artículo 94.2 del TREBEP?', 'El art. 94.2 TREBEP enumera la legalidad y tipicidad, la irretroactividad de lo desfavorable y retroactividad de lo favorable, la proporcionalidad, la culpabilidad y la presunción de inocencia.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 94.2 TREBEP', 'e) Principio de presunción de inocencia.', null, 'b72e373b891c81757c65382422fb3712815a483ea38f6d9523ece5136393fa7b', false
