with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Durante la instrucción de un expediente disciplinario por la desaparición de fondos de una caja pagadora, el instructor aprecia indicios fundados de delito. Según el artículo 94.3 del TREBEP, deberá:', 'El art. 94.3 TREBEP obliga a suspender el procedimiento disciplinario y comunicarlo al Ministerio Fiscal cuando haya indicios fundados de criminalidad; los hechos probados por resoluciones judiciales firmes vinculan a la Administración.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 94.3 TREBEP', 'Cuando de la instrucción de un procedimiento disciplinario resulte la existencia de indicios fundados de criminalidad, se suspenderá su tramitación poniéndolo en conocimiento del Ministerio Fiscal.', null, 'a8d37710e266f8079e301d50b8d4345c2dbdbe5a253fa3965278b25a0fb5afca', false
