  select 'Según el artículo 95.3 del TREBEP, las faltas graves serán establecidas:', 'El art. 95.3 TREBEP remite la tipificación de las faltas graves a la ley (estatal o autonómica) o al convenio colectivo para el personal laboral. Deben atender al grado de vulneración de la legalidad, a la gravedad de los daños y al descrédito para la imagen pública de la Administración.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 95.3 TREBEP', 'Las faltas graves serán establecidas por ley de las Cortes Generales o de la asamblea legislativa de la correspondiente comunidad autónoma o por los convenios colectivos en el caso de personal laboral', null, 'd8777f342197378897deea9fcbad77d5e0b59f78bc2a0cef6e8f9f986a8f2992', false
