with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 98.2 del TREBEP, en el procedimiento disciplinario:', 'El art. 98.2 TREBEP exige eficacia, celeridad y economía procesal, con pleno respeto a las garantías de defensa, y la separación entre la fase instructora y la sancionadora, encomendadas a órganos distintos.', 'age_adm_46_incompatibilidades', (select id from public.topics where slug = 'age-adm-46-incompatibilidades'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 98.2 TREBEP', 'En el procedimiento quedará establecida la debida separación entre la fase instructora y la sancionadora, encomendándose a órganos distintos.', null, '83be0aa96f192ceeae2cfdfe613a8511028206df23dad13f6f505d2e13b5dfb1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '83be0aa96f192ceeae2cfdfe613a8511028206df23dad13f6f505d2e13b5dfb1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mismo órgano instruirá y resolverá, para garantizar la celeridad.', false), ('B', 'Quedará establecida la debida separación entre la fase instructora y la sancionadora, encomendándose a órganos distintos.', true), ('C', 'La fase instructora corresponderá siempre a la Junta de Personal.', false), ('D', 'La resolución corresponderá al mismo funcionario que haya instruido el expediente.', false)) as v(label, body, ok)
