with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la disposición adicional tercera del texto refundido de la Ley General de la Seguridad Social, el personal comprendido en el artículo 2.1 del texto refundido de la Ley de Clases Pasivas que acceda a esa condición a partir del 1 de enero de 2011 queda incluido obligatoriamente en:', 'La DA 3.ª.1 LGSS incluye en el Régimen General, desde el 1 de enero de 2011 y solo a los efectos propios de Clases Pasivas (pensiones), al personal de nuevo ingreso; el mutualismo administrativo se mantiene (art. 2.2 RDLeg 4/2000).', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Disp. adic. 3.ª.1 LGSS', '1. Con efectos de 1 de enero de 2011, el personal que se relaciona en el artículo 2.1 del texto refundido de la Ley de Clases Pasivas del Estado, aprobado por el Real Decreto Legislativo 670/1987, de 30 de abril, excepción hecha del comprendido en la letra i), estará obligatoriamente incluido, a los exclusivos efectos de lo dispuesto en dicha norma y en sus disposiciones de desarrollo, en el Régimen General de la Seguridad Social siempre que el acceso a la condición de que se trate se produzca a partir de aquella fecha.', null, 'bd401190d9d9c62cf03a784177fdafae375504b68d97b4385a240d10bf246960', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bd401190d9d9c62cf03a784177fdafae375504b68d97b4385a240d10bf246960')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Régimen General de la Seguridad Social, a los exclusivos efectos de lo dispuesto en la normativa de Clases Pasivas.', true), ('B', 'El Régimen de Clases Pasivas del Estado, a todos los efectos.', false), ('C', 'El Régimen General de la Seguridad Social, a todos los efectos, con baja en el mutualismo administrativo.', false), ('D', 'El Régimen Especial de Trabajadores por Cuenta Propia o Autónomos.', false)) as v(label, body, ok)
)
