with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el texto refundido de la Ley sobre Seguridad Social de los Funcionarios Civiles del Estado, ¿qué mecanismos de cobertura integran este Régimen especial?', 'El art. 2.1 del RDLeg 4/2000 integra el Régimen especial con dos mecanismos: Clases Pasivas del Estado (con sus normas específicas) y el Mutualismo Administrativo que regula la propia ley.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 2.1 RDLeg 4/2000', '1. Este Régimen especial queda integrado por los siguientes mecanismos de cobertura: a) El Régimen de Clases Pasivas del Estado, de acuerdo con sus normas específicas. b) El Régimen del Mutualismo Administrativo que se regula en la presente Ley.', null, '2a8a713d431d298d60ffd0bb9708032392592a20c811a819d1aaf217ebb97f29', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2a8a713d431d298d60ffd0bb9708032392592a20c811a819d1aaf217ebb97f29')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Régimen General de la Seguridad Social y el Régimen de Clases Pasivas del Estado.', false), ('B', 'El Régimen del Mutualismo Administrativo y la Asistencia Sanitaria del Sistema Nacional de Salud.', false), ('C', 'Únicamente el Régimen del Mutualismo Administrativo.', false), ('D', 'El Régimen de Clases Pasivas del Estado y el Régimen del Mutualismo Administrativo.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 del RDLeg 4/2000, ¿cuál de los siguientes colectivos queda excluido del Régimen especial de la Seguridad Social de los Funcionarios Civiles del Estado?', 'El art. 3.2 excluye, entre otros, a los funcionarios de la Administración Local, de organismos autónomos, de la Administración Militar, de Justicia y de la Seguridad Social y al PAS propio de las universidades. Los funcionarios de carrera y en prácticas de la Administración Civil del Estado están incluidos (art. 3.1) y la excedencia forzosa conserva la condición de mutualista (art. 7.1.d).', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 3.2 RDLeg 4/2000', '2. Quedan excluidos de este Régimen especial y se regirán por sus normas específicas: […] h) El personal de administración y servicios propio de las universidades.', null, '9de21a26ec4b9b10d19e5af010fb7356aa8a00853244e4a3f93ed502c9eb86e2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9de21a26ec4b9b10d19e5af010fb7356aa8a00853244e4a3f93ed502c9eb86e2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los funcionarios de carrera de la Administración Civil del Estado.', false), ('B', 'El personal de administración y servicios propio de las universidades.', true), ('C', 'Los funcionarios en prácticas que aspiren a incorporarse a Cuerpos de la Administración Civil del Estado.', false), ('D', 'Los funcionarios de carrera de la Administración Civil del Estado en situación de excedencia forzosa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el RDLeg 4/2000, la Mutualidad General de Funcionarios Civiles del Estado (MUFACE) es:', 'El art. 5.1 configura MUFACE como organismo público con personalidad jurídica diferenciada, patrimonio y tesorería propios y autonomía de gestión, al que se aplican las previsiones de los organismos autónomos.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 5.1 RDLeg 4/2000', '1. La Mutualidad General de Funcionarios Civiles del Estado es un organismo público con personalidad jurídica pública diferenciada, patrimonio y tesorería propios y autonomía de gestión, y se regirá por las previsiones de la Ley 6/1997, de 14 de abril, de Organización y Funcionamiento de la Administración General del Estado, relativas a los organismos autónomos', 'El texto consolidado sigue remitiendo a la Ley 6/1997 (LOFAGE), derogada por la Ley 40/2015; la naturaleza de organismo autónomo no cambia, pero conviene que joel confirme la redacción del enunciado.', '5f9d3198cfdc435f8003cb79ce909ec08da78ff6e3f7414f6bb30da1cc34d3ff', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5f9d3198cfdc435f8003cb79ce909ec08da78ff6e3f7414f6bb30da1cc34d3ff')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una entidad pública empresarial sujeta al Derecho privado.', false), ('B', 'Una dirección general del Ministerio competente en función pública, sin personalidad jurídica propia.', false), ('C', 'Un organismo público con personalidad jurídica pública diferenciada, patrimonio y tesorería propios y autonomía de gestión, regido por las previsiones relativas a los organismos autónomos.', true), ('D', 'Una mutua colaboradora con la Seguridad Social de carácter privado.', false)) as v(label, body, ok)
)
