  select 'Según el artículo 7 del RDLeg 4/2000, los funcionarios de carrera de la Administración Civil del Estado se incorporan obligatoriamente como mutualistas a MUFACE:', 'El art. 7.1 fija la incorporación obligatoria en el momento de la toma de posesión, cuando se adquiere la condición de funcionario, se rehabilita o se reingresa al servicio activo.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 7.1 RDLeg 4/2000', '1. Los funcionarios de carrera de la Administración Civil del Estado se incorporarán obligatoriamente, como mutualistas, a la Mutualidad General de Funcionarios Civiles del Estado, en el momento de la toma de posesión de su cargo', null, 'd3d7ebfab32840ae155a8f5e5d5efd5ca7d8eb0bb5a252d8be6499a79961fe07', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd3d7ebfab32840ae155a8f5e5d5efd5ca7d8eb0bb5a252d8be6499a79961fe07')
  returning id
), o as (
