with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 7.1 del RDLeg 4/2000, ¿en cuál de las siguientes situaciones administrativas conserva el funcionario la condición de mutualista con los mismos derechos y obligaciones que en servicio activo?', 'El art. 7.1 enumera los servicios especiales, servicios en CC. AA., expectativa de destino, excedencia forzosa, excedencia por cuidado de familiares y suspensión de funciones. La excedencia voluntaria y la pérdida de la condición de funcionario causan baja como mutualista obligatorio (art. 8.1).', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 7.1 RDLeg 4/2000', 'a) Servicios especiales, salvo lo dispuesto en el párrafo c) del apartado 1 y en el apartado 3 del artículo 8. b) Servicios en Comunidades Autónomas. c) Expectativa de destino. d) Excedencia forzosa. e) Excedencia por el cuidado de familiares. f) Suspensión provisional o firme de funciones.', null, 'ca686a3108c190a72f77b58858a42016a1ee33730ce14e27301b52de8fcfae65', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ca686a3108c190a72f77b58858a42016a1ee33730ce14e27301b52de8fcfae65')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Excedencia voluntaria por interés particular.', false), ('B', 'Excedencia por el cuidado de familiares.', true), ('C', 'Excedencia voluntaria por agrupación familiar.', false), ('D', 'Pérdida de la condición de funcionario por renuncia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una funcionaria del Cuerpo General Administrativo pasa a la situación de excedencia voluntaria por interés particular. Según el RDLeg 4/2000, ¿cuál es su situación respecto de MUFACE?', 'La excedencia voluntaria causa baja como mutualista obligatorio (art. 8.1.a), pero el art. 8.2 permite mantener facultativamente el alta como mutualista voluntario si se abonan exclusivamente a su cargo las cuotas del funcionario y del Estado.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 8.1.a) y 8.2 RDLeg 4/2000', 'a) Los funcionarios que pasen a la situación de excedencia voluntaria, en cualquiera de sus modalidades, salvo que ejerciten la opción de mantener la condición de mutualistas […] 2. Podrán mantener facultativamente la situación de alta como mutualistas voluntarios, con igualdad de derechos, los funcionarios a que se refieren los párrafos a), b) y c) del apartado 1 de este artículo, siempre que abonen exclusivamente a su cargo las cuotas correspondientes al funcionario y al Estado.', null, 'aed7ced28be3b93f8b0f918ed5753f4ae553e77a956578ddecf51d180c8d3c31', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'aed7ced28be3b93f8b0f918ed5753f4ae553e77a956578ddecf51d180c8d3c31')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Conserva la condición de mutualista obligatoria con los mismos derechos que en servicio activo.', false), ('B', 'Causa baja definitiva sin posibilidad alguna de mantener el alta.', false), ('C', 'Causa baja como mutualista obligatoria, pero puede mantener el alta como mutualista voluntaria abonando a su cargo las cuotas del funcionario y del Estado.', true), ('D', 'Puede mantener el alta como mutualista voluntaria abonando solo la cuota correspondiente al funcionario.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario de carrera de la Administración Civil del Estado accede por promoción interna a una Escala departamental de un organismo autónomo y queda incluido en el Régimen General de la Seguridad Social. Si desea mantener su condición de mutualista de MUFACE, según el artículo 7.3 del RDLeg 4/2000, debe ejercitar la opción:', 'El art. 7.3 permite mantener la condición de mutualista ejerciendo la opción una sola vez en quince días desde la toma de posesión; ese mantenimiento no supone inclusión en Clases Pasivas.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 7.3 RDLeg 4/2000', 'En el caso de que deseen mantener su condición de mutualistas, deberán ejercitar esta opción, por una sola vez, en el plazo de quince días desde la toma de posesión en el nuevo Cuerpo o Escala.', null, 'b38171e58f32d0e31ff31cc0c4345653bf762f6ac34df974220faba5561c1722', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b38171e58f32d0e31ff31cc0c4345653bf762f6ac34df974220faba5561c1722')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por una sola vez, en el plazo de un mes desde la publicación del nombramiento.', false), ('B', 'En cualquier momento mientras permanezca en la nueva Escala.', false), ('C', 'Cada año, en el plazo de quince días desde el inicio del ejercicio.', false), ('D', 'Por una sola vez, en el plazo de quince días desde la toma de posesión en el nuevo Cuerpo o Escala.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 10 del RDLeg 4/2000, la cotización a MUFACE es obligatoria para todos los mutualistas, con excepción de:', 'El art. 10.1 solo exceptúa de cotizar a los mutualistas jubilados y a los excedentes para el cuidado de hijos o familiares.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 10.1 RDLeg 4/2000', '1. La cotización a la Mutualidad General de Funcionarios Civiles del Estado será obligatoria para todos los mutualistas, con excepción de los mutualistas jubilados y de quienes se encuentren en la situación de excedencia voluntaria para atender al cuidado de hijos o familiares.', null, '12b4f9649e51b0e54d62fb771b68afe25c3726c246dc808d073eb575b1f6001c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '12b4f9649e51b0e54d62fb771b68afe25c3726c246dc808d073eb575b1f6001c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los mutualistas jubilados y quienes se encuentren en excedencia voluntaria para atender al cuidado de hijos o familiares.', true), ('B', 'Los mutualistas en situación de servicios especiales y los jubilados.', false), ('C', 'Los mutualistas en incapacidad temporal desde el cuarto mes de licencia.', false), ('D', 'Los funcionarios en prácticas y los mutualistas en expectativa de destino.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
