  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 10.4 del RDLeg 4/2000, la cuota mensual de cotización a MUFACE se obtiene dividiendo la cantidad resultante de aplicar el tipo a la base de cotización anual entre:', 'El art. 10.4 divide la cuota anual en catorce partes y cobra doble en junio y diciembre, coincidiendo con las pagas extraordinarias.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 10.4 RDLeg 4/2000', '4. La cuota mensual de cotización se obtendrá dividiendo por catorce la cantidad resultante de aplicar a la base de cotización anual, reducida en su caso, el tipo porcentual establecido y se abonará doblemente en los meses de junio y diciembre.', null, '83e649d90edf55293a8e36ed0aa6fee556aa5f1209a33e0351faf4e7641723e8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '83e649d90edf55293a8e36ed0aa6fee556aa5f1209a33e0351faf4e7641723e8')
  returning id
