)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el RDLeg 4/2000, la obligación de pago de las cotizaciones a MUFACE prescribe:', 'El art. 10.6 fija un plazo de prescripción de cuatro años, que se interrumpe por las causas ordinarias y por actuaciones administrativas con conocimiento formal del obligado.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 10.6 RDLeg 4/2000', '6. La obligación de pago de las cotizaciones a la Mutualidad prescribirá a los cuatro años a contar desde la fecha en que preceptivamente debieron ser ingresadas.', null, '119f2fda8f29e49aa3b6a74137172fc0a5a4b59662ef6eb563ba03ce1f92ddd2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '119f2fda8f29e49aa3b6a74137172fc0a5a4b59662ef6eb563ba03ce1f92ddd2')
  returning id
), o as (
