)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de las siguientes es una de las contingencias protegidas por el mutualismo administrativo según el artículo 11 del RDLeg 4/2000?', 'El art. 11 protege la asistencia sanitaria, la incapacidad temporal, la incapacidad permanente, las cargas familiares y la incapacidad temporal especial por donación de órganos. La jubilación de los funcionarios corresponde a Clases Pasivas.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 11 RDLeg 4/2000', 'Los mutualistas y, en su caso, los familiares o asimilados a su cargo quedan concretamente protegidos, de acuerdo con lo previsto en esta Ley, en las siguientes contingencias: a) Necesidad de asistencia sanitaria. b) Incapacidad temporal, derivada bien de enfermedad común o profesional, bien de accidente común o en acto de servicio o como consecuencia de él. c) Incapacidad permanente en los mismos supuestos del apartado anterior. d) Cargas familiares.', null, '802b261d98752e3b371e1b3ca6561157d0a7036e695cbbdf79e8eae85188809a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '802b261d98752e3b371e1b3ca6561157d0a7036e695cbbdf79e8eae85188809a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El desempleo.', false), ('B', 'La jubilación por edad.', false), ('C', 'El cese de actividad.', false), ('D', 'Las cargas familiares.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
