  select 'Según el artículo 15 del RDLeg 4/2000, MUFACE presta a su cargo asistencia sanitaria al recién nacido cuando la madre sea mutualista o beneficiaria, aunque no tenga reconocida la condición de beneficiario, durante:', 'El art. 15.3 excluye la asistencia a familiares sin condición de beneficiario, salvo al recién nacido (y en adopción o acogimiento) durante los primeros quince días.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 15.3 RDLeg 4/2000', 'salvo en el caso del recién nacido cuando la madre sea mutualista o beneficiaria y en los supuestos de adopción o acogimiento, durante los primeros quince días desde el momento del parto', null, '4f562bdbcbdefc6725e7a95ff60f68f031e8bc0d06f1505de28e9184c7f298a3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4f562bdbcbdefc6725e7a95ff60f68f031e8bc0d06f1505de28e9184c7f298a3')
