)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un mutualista de MUFACE inicia su cuarto mes en situación de incapacidad temporal por enfermedad común. Según el artículo 21 del RDLeg 4/2000, desde ese momento percibirá:', 'Desde el cuarto mes el funcionario percibe las retribuciones básicas, la prestación por hijo a cargo y un subsidio de MUFACE fijo e invariable (el mayor entre el 80 % de las básicas más la sexta parte de una paga extra y el 75 % de las complementarias del tercer mes).', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 21.1.b) RDLeg 4/2000', 'b) Desde el cuarto mes percibirá las retribuciones básicas, la prestación por hijo a cargo, en su caso, y un subsidio por incapacidad temporal a cargo de la Mutualidad General de Funcionarios Civiles del Estado', null, 'dd69f5ec68f1a087b6fbc6bad956914b70aa5951b003b369b3b84a091944c24e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'dd69f5ec68f1a087b6fbc6bad956914b70aa5951b003b369b3b84a091944c24e')
