)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 21 del RDLeg 4/2000, durante los tres primeros meses de incapacidad temporal la persona mutualista tiene derecho a percibir:', 'El último párrafo del art. 21.1 garantiza durante los tres primeros meses la totalidad de las retribuciones, abonadas por los órganos de personal.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 21.1 RDLeg 4/2000', 'Durante los tres primeros meses la persona mutualista tendrá derecho al percibo de la totalidad de las retribuciones previstas en las Leyes y Reglamentos aplicables según su respectiva Carrera, Cuerpo y Escala, a cargo de los órganos de personal correspondientes.', null, 'a73fcf053a0d43e74a802a001146f50bbe459204d5837ae142977836f3e6744f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a73fcf053a0d43e74a802a001146f50bbe459204d5837ae142977836f3e6744f')
