)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario de un ministerio presenta el parte médico de baja por un proceso patológico que le impide trabajar. Según el RDLeg 4/2000, ¿a quién corresponde conceder la licencia por enfermedad y sus prórrogas?', 'El art. 19.3 atribuye la concesión de las licencias y prórrogas a los órganos de gestión de personal; MUFACE puede ejercer el control y seguimiento mediante sus Unidades Médicas (art. 19.4).', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 19.3 RDLeg 4/2000', '3. La concesión de las licencias y sus posibles prórrogas a los que tendrán derecho los funcionarios que se encuadren en la situación establecida en el apartado 1 corresponderá a los órganos administrativos con competencia en materias de gestión de personal.', null, '0f16a89fb404df342f32b7839565c9769e23112f9768183d175f0cb8ce2e925b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0f16a89fb404df342f32b7839565c9769e23112f9768183d175f0cb8ce2e925b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A los órganos administrativos con competencia en materia de gestión de personal.', true), ('B', 'A la Dirección General de MUFACE.', false), ('C', 'Al Instituto Nacional de la Seguridad Social.', false), ('D', 'Al servicio público de salud de la comunidad autónoma.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
