  select 'Según el artículo 22 del RDLeg 4/2000, en las situaciones de riesgo durante el embarazo o durante la lactancia natural, el subsidio a cargo de MUFACE equivale a:', 'El art. 22.4 aplica el régimen del art. 21 con la particularidad de que el subsidio es del 100 % de las retribuciones complementarias del tercer mes de licencia.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 22.4 RDLeg 4/2000', 'la prestación económica equivalente al subsidio por incapacidad temporal consistirá en un subsidio a cargo de la Mutualidad General de Funcionarios Civiles del Estado en cuantía igual al 100 por ciento de las retribuciones complementarias devengadas en el tercer mes de licencia.', null, '44ad246ccb481d868cc6fba72ecbf2493558ad365d0acb8e86c0c0c84d4d2f06', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '44ad246ccb481d868cc6fba72ecbf2493558ad365d0acb8e86c0c0c84d4d2f06')
