with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el RDLeg 4/2000, la gran invalidez da derecho, además de a la jubilación, a una cantidad mensual destinada a remunerar a la persona encargada de la asistencia, equivalente al:', 'El art. 26 fija una cantidad mensual del 50 % de la pensión de jubilación de Clases Pasivas para remunerar a quien asiste al gran inválido.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 26 RDLeg 4/2000', 'La gran invalidez originará la jubilación del funcionario y dará derecho a una cantidad mensual equivalente al 50 por 100 de la pensión de jubilación que le corresponda con arreglo al Régimen de Clases Pasivas, destinada a remunerar a la persona encargada de su asistencia.', null, '5cf7d73497f95135f4d3887b89cdd7defedbb6301338067e4549abb1f079233e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5cf7d73497f95135f4d3887b89cdd7defedbb6301338067e4549abb1f079233e')
  returning id
