with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una mutualista quiere impugnar la resolución del Director general de MUFACE que le deniega una prestación. Según el artículo 37 del RDLeg 4/2000, con carácter general:', 'El art. 37.1 dispone que los actos y resoluciones del Director general no agotan la vía administrativa y son recurribles en alzada ante el Ministro; agotada esa vía, cabe el contencioso-administrativo. Las excepciones del art. 37.2 (p. ej., materia de personal) ponen fin a la vía administrativa.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 37.1 RDLeg 4/2000', '1. Los actos y resoluciones del Director general de la Mutualidad General de Funcionarios Civiles del Estado no ponen fin a la vía administrativa, pudiéndose recurrir en alzada ante el Ministro de Administraciones Públicas.', null, '4e57533b6132c8ff38c8c08cbbf862ef576aa05698cc78276c70096af6d7e6db', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4e57533b6132c8ff38c8c08cbbf862ef576aa05698cc78276c70096af6d7e6db')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La resolución pone fin a la vía administrativa y solo cabe recurso contencioso-administrativo.', false), ('B', 'La resolución pone fin a la vía administrativa y cabe recurso potestativo de reposición.', false), ('C', 'Debe presentarse reclamación previa ante el Consejo General de MUFACE.', false), ('D', 'La resolución no pone fin a la vía administrativa y puede recurrirse en alzada ante el Ministro.', true)) as v(label, body, ok)
)
