  select 'A efectos del cómputo de plazos de la incapacidad temporal de los mutualistas, el artículo 20 del RDLeg 4/2000 considera que existe, en todo caso, un nuevo proceso patológico cuando las licencias se hayan interrumpido durante un periodo mínimo de:', 'El art. 20.2 considera nuevo proceso el de enfermedades diferentes o sin relación directa con las anteriores y, en todo caso, cuando las licencias se hayan interrumpido al menos 6 meses.', 'age_adm_47_muface', (select id from public.topics where slug = 'age-adm-47-muface'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'Art. 20.2 RDLeg 4/2000', 'A efectos de cómputo de plazos, se considerará que existe nuevo proceso patológico cuando las enfermedades que padezca el funcionario sean diferentes o no tengan relación directa con las del proceso anterior y, en todo caso, cuando se hayan interrumpido las licencias durante un periodo mínimo de 6 meses.', null, 'cb241c1d775bdb83902720f04c197f12b5fd643faa941149fe930104bd85c18c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cb241c1d775bdb83902720f04c197f12b5fd643faa941149fe930104bd85c18c')
  returning id
), o as (
