insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-48-personal-laboral' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una trabajadora con contrato laboral en un ministerio pregunta si le afecta la Ley 53/1984, de Incompatibilidades. Según su artículo 2, la Ley se aplica en su ámbito:', 'El art. 2.2 de la Ley 53/1984 incluye a todo el personal del ámbito delimitado, cualquiera que sea su relación de empleo; el personal laboral queda, por tanto, sujeto al régimen de incompatibilidades.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 2.2 Ley 53/1984', '2. En el ámbito delimitado en el apartado anterior se entenderá incluido todo el personal, cualquiera que sea la naturaleza jurídica de la relación de empleo.', null, '669052350e7f4ae0cdba2a551d58b826e4b372ed0b3704e0de9eae2988ad5a44', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '669052350e7f4ae0cdba2a551d58b826e4b372ed0b3704e0de9eae2988ad5a44')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A todo el personal, cualquiera que sea la naturaleza jurídica de la relación de empleo.', true), ('B', 'Solo a los funcionarios de carrera e interinos.', false), ('C', 'Solo al personal laboral que ocupe puestos de nivel directivo.', false), ('D', 'Al personal laboral únicamente cuando lo prevea su convenio colectivo.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 de la Ley 53/1984, cuando por razón de interés público el Consejo de Ministros determine, mediante real decreto, un supuesto de compatibilidad para un segundo puesto en el sector público, esa actividad solo podrá prestarse:', 'El art. 3.1 de la Ley 53/1984 limita este supuesto al régimen laboral, a tiempo parcial y con duración determinada; además exige autorización previa y expresa de compatibilidad.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 3.1 Ley 53/1984', 'en este último supuesto la actividad sólo podrá prestarse en régimen laboral, a tiempo parcial y con duración determinada, en las condiciones establecidas por la legislación laboral.', null, 'b3193f62012f0e06703326f29caff674539bf1a6f4c4f8af6fbfef6cd509148a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b3193f62012f0e06703326f29caff674539bf1a6f4c4f8af6fbfef6cd509148a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En régimen funcionarial, a tiempo completo y por tiempo indefinido.', false), ('B', 'En régimen laboral, a tiempo completo y con duración determinada.', false), ('C', 'En régimen laboral, a tiempo parcial y con duración determinada.', true), ('D', 'En cualquier régimen, siempre que no supere setenta y cinco horas al año.', false)) as v(label, body, ok)
)
