insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-48-personal-laboral' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un ministerio necesita cubrir con personal laboral fijo de nuevo ingreso varias plazas vacantes adscritas a él. Según el Reglamento General de Ingreso (RD 364/1995), ¿quién convoca el proceso selectivo?', 'El art. 28.1 RGI atribuye la convocatoria a los Departamentos ministeriales, previo informe favorable de la Dirección General de la Función Pública y conforme a la oferta de empleo público.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 28.1 RD 364/1995', '1. Los Departamentos ministeriales convocarán, previo informe favorable de la Dirección General de la Función Pública, los procesos selectivos para el acceso a las plazas vacantes adscritas a los mismos que deban cubrirse con personal laboral fijo de nuevo ingreso, de acuerdo con lo previsto en la oferta de empleo público.', null, 'e36f5ea9288a87b24a45f1e3568f03827ebcb5f883034584b5479564e60606ab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e36f5ea9288a87b24a45f1e3568f03827ebcb5f883034584b5479564e60606ab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El propio Departamento ministerial, previo informe favorable de la Dirección General de la Función Pública y de acuerdo con la oferta de empleo público.', true), ('B', 'La Dirección General de la Función Pública, previo informe del Departamento interesado.', false), ('C', 'El Consejo de Ministros, a propuesta del Ministerio de Hacienda.', false), ('D', 'La Comisión Permanente de Selección, sin necesidad de informe previo.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 30 del RD 364/1995, los órganos de selección del personal laboral de la Administración General del Estado:', 'El art. 30 RGI exige órganos constituidos en cada convocatoria, con número impar de miembros y, al menos, uno designado a propuesta de la representación de los trabajadores.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 30 RD 364/1995', 'Los órganos de selección se constituirán en cada convocatoria y deberán estar formados por un número impar de miembros, uno de los cuales, al menos, será designado a propuesta de la representación de los trabajadores.', null, '547579991002f3008f0750202f6d9bf7e0b9195cf029af21454e8563d0d31b5e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '547579991002f3008f0750202f6d9bf7e0b9195cf029af21454e8563d0d31b5e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Son permanentes y están formados por un número par de miembros designados por la Dirección General de la Función Pública.', false), ('B', 'Se constituyen en cada convocatoria con cinco miembros, todos ellos funcionarios de carrera.', false), ('C', 'Se constituyen en cada convocatoria y la mitad de sus miembros se designa a propuesta de las organizaciones sindicales.', false), ('D', 'Se constituyen en cada convocatoria con un número impar de miembros, al menos uno de ellos designado a propuesta de la representación de los trabajadores.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
