with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En los procesos selectivos de personal laboral regulados por el RD 364/1995, la fecha, lugar y hora de realización de las pruebas se publicará en el «Boletín Oficial del Estado» en el plazo máximo de:', 'El art. 31.2 RGI fija un mes desde que termina el plazo de instancias para publicar en el BOE la fecha, lugar y hora de las pruebas, con indicación del lugar donde se exponen las listas de admitidos.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 31.2 RD 364/1995', '2. En el plazo máximo de un mes, a partir de la fecha de terminación del plazo previsto en cada convocatoria para la presentación de instancias, se publicará en el «Boletín Oficial del Estado» la fecha, lugar y hora de realización de las pruebas', null, 'cc013b372e0f6f1014b32530143855ef55eb13e2b6e030e1afd641b34ae728d7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cc013b372e0f6f1014b32530143855ef55eb13e2b6e030e1afd641b34ae728d7')
  returning id
), o as (
