)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el RD 364/1995, ¿en qué momento adquiere el aspirante seleccionado la condición de personal laboral fijo?', 'El art. 33 RGI exige formalizar el contrato y, transcurrido el período de prueba de la convocatoria, quien lo supere adquiere la condición de personal laboral fijo.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 33.2 RD 364/1995', '2. Transcurrido el período de prueba que se determine en cada convocatoria, el personal que lo supere satisfactoriamente adquirirá la condición de personal laboral fijo.', null, 'ab9fc4e5533f5bacb2465027a92224f5d34ea4d8f2594e5736bd4aa036018c60', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ab9fc4e5533f5bacb2465027a92224f5d34ea4d8f2594e5736bd4aa036018c60')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el momento de la publicación de la relación de aprobados.', false), ('B', 'Cuando supera satisfactoriamente el período de prueba que se determine en cada convocatoria.', true), ('C', 'En el momento de la firma del contrato, sin período de prueba.', false), ('D', 'Cuando transcurre un año desde su incorporación al puesto de trabajo.', false)) as v(label, body, ok)
)
