insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto Legislativo 5/2015, de 30 de octubre, texto refundido de la Ley del Estatuto Básico del Empleado Público (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-48-personal-laboral', 'IV.8 El personal laboral al servicio de las Administraciones públicas') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-48-personal-laboral' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 11 del texto refundido del Estatuto Básico del Empleado Público, en función de la duración del contrato, el personal laboral podrá ser:', 'El art. 11.1 TREBEP define el personal laboral por el contrato de trabajo formalizado por escrito y lo clasifica, según su duración, en fijo, por tiempo indefinido o temporal.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 11.1 TREBEP', '1. Es personal laboral el que en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, presta servicios retribuidos por las Administraciones Públicas. En función de la duración del contrato éste podrá ser fijo, por tiempo indefinido o temporal.', null, 'cc6064d5facb22d9c19588132e79c41042598343010ae86b936bd44d4b618cbb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cc6064d5facb22d9c19588132e79c41042598343010ae86b936bd44d4b618cbb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fijo, interino o eventual.', false), ('B', 'De carrera, interino o en prácticas.', false), ('C', 'Fijo, por tiempo indefinido o temporal.', true), ('D', 'Fijo o eventual, exclusivamente.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 7 del TREBEP, el personal laboral al servicio de las Administraciones públicas se rige:', 'El art. 7 TREBEP combina la legislación laboral y los convenios con los preceptos del propio Estatuto que expresamente se refieran al personal laboral.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 7 TREBEP', 'El personal laboral al servicio de las Administraciones públicas se rige, además de por la legislación laboral y por las demás normas convencionalmente aplicables, por los preceptos de este Estatuto que así lo dispongan.', null, '1037ebe96917a41bf777c5af52455cd4bca7ac633018264ae1ccef1e1db23fc7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1037ebe96917a41bf777c5af52455cd4bca7ac633018264ae1ccef1e1db23fc7')
