with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 7 del TREBEP, en materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica, de lactancia y parental, el personal laboral de las Administraciones públicas se rige por:', 'El párrafo segundo del art. 7 TREBEP equipara al personal laboral con el funcionario en estos permisos: se aplica el Estatuto Básico y no las suspensiones del contrato del Estatuto de los Trabajadores.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 7 TREBEP', 'No obstante, en materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica, de lactancia y parental, el personal laboral al servicio de las Administraciones públicas se regirá por lo previsto en el presente Estatuto, no siendo de aplicación a este personal, por tanto, las previsiones del texto refundido de la Ley del Estatuto de los Trabajadores sobre las suspensiones de los contratos de trabajo que, en su caso, corresponderían por los mismos supuestos de hecho.', null, '309b9f69e46e1fe9758876163fb9f2175cc9836a22ae404aa48d368b9f95acd6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '309b9f69e46e1fe9758876163fb9f2175cc9836a22ae404aa48d368b9f95acd6')
