with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El artículo 11.2 del TREBEP ordena respetar el artículo 9.2 al determinar los puestos que puede desempeñar el personal laboral. Según ese artículo 9.2, corresponde exclusivamente a los funcionarios públicos el ejercicio de las funciones que impliquen:', 'El art. 9.2 TREBEP reserva en todo caso a los funcionarios las funciones que implican participar en el ejercicio de potestades públicas o salvaguardar los intereses generales; el art. 11.2 obliga a respetarlo al fijar qué puestos pueden ser laborales.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 9.2 TREBEP', '2. En todo caso, el ejercicio de las funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales del Estado y de las Administraciones Públicas corresponden exclusivamente a los funcionarios públicos', null, '6ae8cef6b7af1d20c110da9e6714f55f66a74927034d9d4be4f25063d3d3f535', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6ae8cef6b7af1d20c110da9e6714f55f66a74927034d9d4be4f25063d3d3f535')
  returning id
