  select 'Según el artículo 61 del TREBEP, los sistemas selectivos de personal laboral fijo serán:', 'El art. 61.7 TREBEP admite para el personal laboral fijo la oposición, el concurso-oposición o el concurso de valoración de méritos; en cambio, para funcionarios de carrera el concurso solo cabe excepcionalmente en virtud de ley (art. 61.6).', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 61.7 TREBEP', '7. Los sistemas selectivos de personal laboral fijo serán los de oposición, concurso-oposición, con las características establecidas en el apartado anterior, o concurso de valoración de méritos.', null, '632c4fcc3ac6cd3a5476c971111668451740fb2a4f70a8b88f46e64262cd6cab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '632c4fcc3ac6cd3a5476c971111668451740fb2a4f70a8b88f46e64262cd6cab')
  returning id
