with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un ciudadano de un país no perteneciente a la Unión Europea, con residencia legal en España, desea presentarse a un proceso selectivo de la Administración General del Estado. Según el artículo 57 del TREBEP, podrá acceder:', 'El art. 57.4 TREBEP permite a los extranjeros con residencia legal en España acceder como personal laboral en igualdad de condiciones que los españoles; para ser funcionario, la exención del requisito de nacionalidad exige ley (art. 57.5).', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 57.4 TREBEP', '4. Los extranjeros a los que se refieren los apartados anteriores, así como los extranjeros con residencia legal en España podrán acceder a las Administraciones Públicas, como personal laboral, en igualdad de condiciones que los españoles.', null, 'af7cb7b9cc3bc3469d558e5ce850750a9f01d4ca236618c270befb3ef5017a7e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'af7cb7b9cc3bc3469d558e5ce850750a9f01d4ca236618c270befb3ef5017a7e')
  returning id
), o as (
