  select 'Según el artículo 32 del TREBEP, los órganos de gobierno de las Administraciones Públicas pueden suspender o modificar el cumplimiento de convenios colectivos ya firmados que afecten al personal laboral:', 'El art. 32.2 TREBEP garantiza el cumplimiento de los convenios, salvo suspensión o modificación excepcional por causa grave de interés público derivada de una alteración sustancial de las circunstancias económicas; la Administración debe informar a los sindicatos de las causas.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 32.2 TREBEP', '2. Se garantiza el cumplimiento de los convenios colectivos y acuerdos que afecten al personal laboral, salvo cuando excepcionalmente y por causa grave de interés público derivada de una alteración sustancial de las circunstancias económicas, los órganos de gobierno de las Administraciones Públicas suspendan o modifiquen el cumplimiento de convenios colectivos o acuerdos ya firmados en la medida estrictamente necesaria para salvaguardar el interés público.', null, 'e625c4f0c95ce64f83814a6d8cad1297781d086a858ea998850221709bccab8d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e625c4f0c95ce64f83814a6d8cad1297781d086a858ea998850221709bccab8d')
