with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 19 del TREBEP, la carrera profesional y la promoción del personal laboral se harán efectivas:', 'El art. 19 TREBEP reconoce al personal laboral el derecho a la promoción profesional y remite su carrera y promoción al Estatuto de los Trabajadores o a los convenios colectivos.', 'age_adm_48_personal_laboral', (select id from public.topics where slug = 'age-adm-48-personal-laboral'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 19 TREBEP', '1. El personal laboral tendrá derecho a la promoción profesional. 2. La carrera profesional y la promoción del personal laboral se hará efectiva a través de los procedimientos previstos en el Estatuto de los Trabajadores o en los convenios colectivos.', null, '51f59ebb2e27dbfa1a8d705e2178f3ddd282fbda43f3bbf068e60c7ed1415a0e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '51f59ebb2e27dbfa1a8d705e2178f3ddd282fbda43f3bbf068e60c7ed1415a0e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A través de los grados y niveles propios de la carrera horizontal de los funcionarios.', false), ('B', 'Exclusivamente mediante promoción interna a cuerpos y escalas de funcionarios.', false), ('C', 'A través de los procedimientos que fije cada año la Ley de Presupuestos Generales del Estado.', false), ('D', 'A través de los procedimientos previstos en el Estatuto de los Trabajadores o en los convenios colectivos.', true)) as v(label, body, ok)
)
