with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un ministerio contrata a una persona como personal laboral fijo. Según el artículo 136 del texto refundido de la Ley General de la Seguridad Social, ¿en qué régimen queda incluida obligatoriamente?', 'El art. 136.2.k) LGSS declara expresamente comprendido en el Régimen General al personal civil no funcionario de las administraciones públicas, salvo que una ley especial lo incluya en otro régimen obligatorio.', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 136.2.k) LGSS', 'k) El personal civil no funcionario de las administraciones públicas y de las entidades y organismos vinculados o dependientes de ellas siempre que no estén incluidos en virtud de una ley especial en otro régimen obligatorio de previsión social.', null, '75da2f804ecd42743f65f695cdc413f8b634305022a4460d9f812b91a77872ab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '75da2f804ecd42743f65f695cdc413f8b634305022a4460d9f812b91a77872ab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el Régimen especial de la Seguridad Social de los Funcionarios Civiles del Estado (MUFACE).', false), ('B', 'En el Régimen General de la Seguridad Social, como personal civil no funcionario de las administraciones públicas.', true), ('C', 'En el Régimen de Clases Pasivas del Estado.', false), ('D', 'En el Régimen Especial de Trabajadores por Cuenta Propia o Autónomos.', false)) as v(label, body, ok)
)
