  select 'Según el artículo 155 de la LGSS, la acción protectora del Régimen General es la establecida en el artículo 42 con excepción de:', 'El art. 155.1 LGSS excluye del Régimen General la protección por cese de actividad (propia de los autónomos) y las prestaciones no contributivas.', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 155.1 LGSS', '1. La acción protectora del Régimen General será la establecida en el artículo 42, con excepción de la protección por cese de actividad y las prestaciones no contributivas.', null, 'ab0ce2827850bec28864f8c3bb15f721209f811cd185d7c3c48c6891efc90f31', false
