with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 156 de la LGSS, se entiende por accidente de trabajo:', 'El art. 156.1 LGSS define el accidente de trabajo; la enfermedad profesional (cuadro reglamentario) se define en el art. 157 y la enfermedad común en el art. 158.', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 156.1 LGSS', '1. Se entiende por accidente de trabajo toda lesión corporal que el trabajador sufra con ocasión o por consecuencia del trabajo que ejecute por cuenta ajena.', null, '62b467c38e13ad8e40f61a315e7755ccffd8a889ff68d3d6162117b8a464e1e0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '62b467c38e13ad8e40f61a315e7755ccffd8a889ff68d3d6162117b8a464e1e0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Toda alteración de la salud que no tenga la condición de enfermedad profesional.', false), ('B', 'La enfermedad contraída a consecuencia del trabajo en las actividades especificadas en el cuadro reglamentario.', false), ('C', 'Toda lesión corporal sufrida durante la jornada, cualquiera que sea su causa.', false), ('D', 'Toda lesión corporal que el trabajador sufra con ocasión o por consecuencia del trabajo que ejecute por cuenta ajena.', true)) as v(label, body, ok)
)
