with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un trabajador laboral de una delegación del Gobierno sufre una caída cuando se dirigía desde su domicilio a su centro de trabajo. Según la LGSS, esa lesión tiene la consideración de:', 'El art. 156.2.a) LGSS considera accidente de trabajo el sufrido al ir o al volver del lugar de trabajo (accidente in itinere).', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 156.2.a) LGSS', 'a) Los que sufra el trabajador al ir o al volver del lugar de trabajo.', null, '653d3f5fbde2c15c02c0d168a633fd9a511b798b2cc8fd07ede7c2bcee3a9025', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '653d3f5fbde2c15c02c0d168a633fd9a511b798b2cc8fd07ede7c2bcee3a9025')
