with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 156 de la LGSS, NO tendrán la consideración de accidente de trabajo los que sean debidos a:', 'El art. 156.4 excluye la fuerza mayor extraña al trabajo y el dolo o la imprudencia temeraria del accidentado; en cambio, la imprudencia profesional y la culpa de un compañero no impiden la calificación (art. 156.5) y los actos de salvamento conectados con el trabajo son accidente de trabajo (art. 156.2.d).', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 156.4.b) LGSS', '4. No obstante lo establecido en los apartados anteriores, no tendrán la consideración de accidente de trabajo: […] b) Los que sean debidos a dolo o a imprudencia temeraria del trabajador accidentado.', null, '1a8abd10a5b18ffa6abbabebcb5867db759b2892b8bf51aac2825b0248dea852', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1a8abd10a5b18ffa6abbabebcb5867db759b2892b8bf51aac2825b0248dea852')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Imprudencia profesional derivada de la confianza que inspira el ejercicio habitual del trabajo.', false), ('B', 'Culpabilidad civil o criminal de un compañero de trabajo relacionada con el trabajo.', false), ('C', 'Dolo o imprudencia temeraria del trabajador accidentado.', true), ('D', 'Actos de salvamento que tengan conexión con el trabajo.', false)) as v(label, body, ok)
)
