with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la redacción del artículo 194 de la LGSS aplicable transitoriamente (disposición transitoria vigésima sexta) mientras no se desarrolle reglamentariamente, se entiende por incapacidad permanente total para la profesión habitual:', 'La DT 26.ª LGSS mantiene, hasta el desarrollo reglamentario del art. 194, los grados clásicos: parcial (disminución no inferior al 33 %), total (todas o las fundamentales tareas de su profesión, pudiendo dedicarse a otra), absoluta (toda profesión u oficio) y gran incapacidad (necesidad de asistencia de otra persona).', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Disp. trans. 26.ª LGSS (art. 194.4)', '4. Se entenderá por incapacidad permanente total para la profesión habitual la que inhabilite al trabajador para la realización de todas o de las fundamentales tareas de dicha profesión, siempre que pueda dedicarse a otra distinta.', null, '654c1114505621a1312a6aa3e2f8b123a7b355bdfaca93e2651dabf80bc71f0f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '654c1114505621a1312a6aa3e2f8b123a7b355bdfaca93e2651dabf80bc71f0f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La que inhabilite al trabajador para la realización de todas o de las fundamentales tareas de dicha profesión, siempre que pueda dedicarse a otra distinta.', true), ('B', 'La que, sin alcanzar el grado de total, ocasione al trabajador una disminución no inferior al 33 por ciento en su rendimiento normal para dicha profesión.', false), ('C', 'La que inhabilite por completo al trabajador para toda profesión u oficio.', false), ('D', 'La situación del trabajador que necesite la asistencia de otra persona para los actos más esenciales de la vida.', false)) as v(label, body, ok)
)
