with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la LGSS, para que una enfermedad tenga la consideración de enfermedad profesional debe haberse contraído a consecuencia del trabajo por cuenta ajena:', 'El art. 157 LGSS exige que la actividad y el agente causante figuren en el cuadro reglamentario. Las enfermedades no incluidas que tengan por causa exclusiva el trabajo se consideran accidente de trabajo (art. 156.2.e).', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 157 LGSS', 'Se entenderá por enfermedad profesional la contraída a consecuencia del trabajo ejecutado por cuenta ajena en las actividades que se especifiquen en el cuadro que se apruebe por las disposiciones de aplicación y desarrollo de esta ley, y que esté provocada por la acción de los elementos o sustancias que en dicho cuadro se indiquen para cada enfermedad profesional.', null, '74f97d1803ce42e4da8077ee74026d56565d009ddcf29c6a52d301d97778062e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '74f97d1803ce42e4da8077ee74026d56565d009ddcf29c6a52d301d97778062e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En cualquier actividad, siempre que se pruebe que tuvo por causa exclusiva la ejecución del trabajo.', false), ('B', 'En las actividades especificadas en el cuadro aprobado por las disposiciones de desarrollo y provocada por los elementos o sustancias que en él se indiquen.', true), ('C', 'En las actividades que determine cada convenio colectivo.', false), ('D', 'En cualquier actividad, siempre que se manifieste durante la jornada laboral.', false)) as v(label, body, ok)
)
