with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 165 de la LGSS, salvo disposición legal expresa en contrario, no se exigirán períodos previos de cotización para las prestaciones derivadas de:', 'El art. 165.4 LGSS exime de carencia las prestaciones derivadas de accidente (laboral o no) y de enfermedad profesional; la enfermedad común sí exige períodos previos (p. ej., 180 días para la IT, art. 172.a).', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 165.4 LGSS', '4. No se exigirán períodos previos de cotización para el derecho a las prestaciones derivadas de accidente, sea o no de trabajo, o de enfermedad profesional, salvo disposición legal expresa en contrario.', null, 'd995a95d0cbb02d2ec0c5591f061acfee23e792590a08abf75cd0e8378045947', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd995a95d0cbb02d2ec0c5591f061acfee23e792590a08abf75cd0e8378045947')
