with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 166 de la LGSS, los trabajadores del Régimen General se consideran de pleno derecho en situación de alta, aunque su empresario hubiera incumplido sus obligaciones, a efectos de:', 'El art. 166.4 LGSS fija el alta de pleno derecho para accidentes de trabajo, enfermedades profesionales y desempleo, y la extiende a la asistencia sanitaria por enfermedad común, maternidad y accidente no laboral.', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 166.4 LGSS', '4. Los trabajadores comprendidos en el campo de aplicación de este Régimen General se considerarán, de pleno derecho, en situación de alta a efectos de accidentes de trabajo, enfermedades profesionales y desempleo, aunque su empresario hubiera incumplido sus obligaciones.', null, '8a885909bdd8a660135d202c952af3a4280f07b9693f13eb44545bf7bb485f2d', false
