with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 169 de la LGSS, la situación de incapacidad temporal debida a enfermedad o accidente tiene una duración máxima de:', 'El art. 169.1.a) LGSS fija 365 días de duración máxima, prorrogables 180 días más si se presume la curación en ese plazo.', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 169.1.a) LGSS', 'con una duración máxima de trescientos sesenta y cinco días, prorrogables por otros 180 días cuando se presuma que durante ellos puede el trabajador ser dado de alta médica por curación.', null, '485b3ca12779030759c15009d48c28cf2294b0b65b4c14a946448b6696dc31ca', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '485b3ca12779030759c15009d48c28cf2294b0b65b4c14a946448b6696dc31ca')
