with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 172 de la LGSS, para causar derecho al subsidio por incapacidad temporal derivada de enfermedad común se exige un período mínimo de cotización de:', 'El art. 172.a) LGSS exige 180 días cotizados en los cinco años anteriores; para accidente (laboral o no) y enfermedad profesional no se exige carencia (art. 172.b).', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 172.a) LGSS', 'a) En caso de enfermedad común, 180 días dentro de los cinco años inmediatamente anteriores al hecho causante.', null, '88612ed854448323c8da94ce1ffc461a522f8113372f24d69a6a5d1cb8c9c85a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '88612ed854448323c8da94ce1ffc461a522f8113372f24d69a6a5d1cb8c9c85a')
  returning id
), o as (
