)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una trabajadora laboral de un organismo público causa baja por una gripe (enfermedad común). Según el artículo 173 de la LGSS, ¿desde cuándo se abona el subsidio por incapacidad temporal y quién lo paga inicialmente?', 'En enfermedad común o accidente no laboral el subsidio se abona desde el cuarto día de baja y del 4.º al 15.º lo paga el empresario. En accidente de trabajo o enfermedad profesional se abona desde el día siguiente a la baja (art. 173.1).', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 173.1 LGSS', 'En caso de enfermedad común o de accidente no laboral, el subsidio se abonará a partir del cuarto día de baja en el trabajo, si bien desde el día cuarto al decimoquinto de baja, ambos inclusive, el subsidio estará a cargo del empresario.', null, '0d3950a3eab6a2e5a27b1718dc9991a509673e3c3f9dac90b95d5482b76ab865', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0d3950a3eab6a2e5a27b1718dc9991a509673e3c3f9dac90b95d5482b76ab865')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Desde el día siguiente al de la baja, a cargo de la entidad gestora desde el primer momento.', false), ('B', 'Desde el cuarto día de baja, a cargo de la entidad gestora desde ese mismo día.', false), ('C', 'Desde el decimosexto día de baja, a cargo del empresario hasta el día treinta.', false), ('D', 'Desde el cuarto día de baja, estando a cargo del empresario desde el día cuarto al decimoquinto, ambos inclusive.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un trabajador lleva 365 días en incapacidad temporal y su médico de atención primaria considera que ya puede reincorporarse. Según el artículo 170 de la LGSS, agotado ese plazo, ¿quién es el único competente para emitir el alta médica?', 'Agotados los 365 días, el art. 170.2 LGSS atribuye en exclusiva a la inspección médica del INSS la emisión del alta (por curación, por mejoría, con propuesta de incapacidad permanente o por incomparecencia).', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 170.2 LGSS', '2. Agotado el plazo de duración de trescientos sesenta y cinco días indicado en el apartado anterior, la inspección médica del Instituto Nacional de la Seguridad Social será la única competente para emitir el alta médica por curación, por mejoría que permita la reincorporación al trabajo, con propuesta de incapacidad permanente o por incomparecencia injustificada a los reconocimientos médicos convocados por dicha entidad gestora.', null, 'c27c3ab93430311b7cab2d19f83f51c7d278e2506080122a308bb4ef43713bc7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c27c3ab93430311b7cab2d19f83f51c7d278e2506080122a308bb4ef43713bc7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El médico de atención primaria del servicio público de salud.', false), ('B', 'La inspección médica del Instituto Nacional de la Seguridad Social.', true), ('C', 'La mutua colaboradora con la Seguridad Social con la que la empresa tenga concertada la cobertura.', false), ('D', 'La Inspección de Trabajo y Seguridad Social.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 174 de la LGSS, cuando el subsidio de incapacidad temporal se extingue por el transcurso de los quinientos cuarenta y cinco días, la calificación de la incapacidad permanente puede demorarse si así lo aconseja la situación clínica, sin que en ningún caso puedan rebasarse:', 'El art. 174.2 LGSS exige examinar al interesado en un máximo de 90 días para calificar la incapacidad permanente; si se demora la calificación, el total de IT más prolongación de efectos no puede superar 730 días.', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 174.2 LGSS', 'esta podrá retrasarse por el período preciso, sin que en ningún caso se puedan rebasar los setecientos treinta días naturales sumados los de incapacidad temporal y los de prolongación de sus efectos.', null, '519e2650a3ee854d352a67a98937123d53ec28a998f3120ee3a2a51db3ed11cf', false
