  select 'Según el artículo 186 de la LGSS, la prestación correspondiente a la situación de riesgo durante el embarazo tiene la naturaleza de prestación derivada de:', 'El art. 186 LGSS califica la prestación por riesgo durante el embarazo como derivada de contingencias profesionales; por eso el subsidio es del 100 % de la base reguladora de la IT por contingencias profesionales (art. 187.3).', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 186 LGSS', 'La prestación correspondiente a la situación de riesgo durante el embarazo tendrá la naturaleza de prestación derivada de contingencias profesionales.', null, '4bca1b41d6ddfbd115efe40fcf216905b6264140b1dfda1dec12b2d2a25d6865', false
