  select 'Según la LGSS, la prestación económica por riesgo durante la lactancia natural se extingue, salvo reincorporación anterior de la trabajadora, en el momento en que el hijo cumpla:', 'El art. 189 LGSS extingue la prestación cuando el hijo cumple nueve meses o el día anterior a la reincorporación de la trabajadora a su puesto o a otro compatible.', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 189 LGSS', 'se extinguirá en el momento en que el hijo cumpla nueve meses, salvo que la beneficiaria se haya reincorporado con anterioridad a su puesto de trabajo anterior o a otro compatible con su situación', null, '409ffd8c24115e0e1609af4967a49acad7d3e5d203a0e0e414abf5cb9b054044', false
