with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Fallece por enfermedad común un trabajador en alta en el Régimen General. Según el artículo 219 de la LGSS, para que su cónyuge superviviente tenga derecho a la pensión de viudedad, el causante debe haber completado un período de cotización de:', 'Si el causante estaba en alta o asimilada, el art. 219.1 LGSS exige 500 días cotizados en los cinco años anteriores; sin alta, se exigen 15 años; si la muerte se debe a accidente o enfermedad profesional no se exige cotización previa.', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 219.1 LGSS', 'siempre que si el sujeto causante se encontrase en alta o en situación asimilada a la de alta en la fecha de su fallecimiento hubiera completado un período de cotización de quinientos días, dentro de los cinco años inmediatamente anteriores a la fecha del hecho causante de la pensión.', null, '2c9fc3cc4428b2b370c737244ef848d94fd1607880fd88a3c33f6c86010c4dc8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2c9fc3cc4428b2b370c737244ef848d94fd1607880fd88a3c33f6c86010c4dc8')
