with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la escala del artículo 269 de la LGSS, a una persona que acredita entre 360 y 539 días cotizados en los seis años anteriores a la situación legal de desempleo le corresponde una prestación contributiva por desempleo de:', 'El art. 269.1 LGSS relaciona la duración de la prestación con los días cotizados en los seis años anteriores: de 360 a 539 días cotizados corresponden 120 días de prestación; de 540 a 719, 180 días.', 'age_adm_49_seguridad_social', (select id from public.topics where slug = 'age-adm-49-seguridad-social'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 269.1 LGSS', '1. La duración de la prestación por desempleo estará en función de los períodos de ocupación cotizada en los seis años anteriores a la situación legal de desempleo o al momento en que cesó la obligación de cotizar, con arreglo a la siguiente escala: […] Desde 360 hasta 539 | 120', null, '430a54733a8545bf0b6dc993ef898f126d44f6e53be0ffe4fa72899f0dc3df3a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '430a54733a8545bf0b6dc993ef898f126d44f6e53be0ffe4fa72899f0dc3df3a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '120 días.', true), ('B', '180 días.', false), ('C', '90 días.', false), ('D', '360 días.', false)) as v(label, body, ok)
)
