  select 'Según el artículo 134.2 de la Constitución Española, los Presupuestos Generales del Estado:', 'El art. 134.2 CE recoge los principios de anualidad y universalidad: los Presupuestos son anuales, incluyen la totalidad de gastos e ingresos del sector público estatal y consignan el importe de los beneficios fiscales que afectan a los tributos del Estado.', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 134.2 CE', 'Los Presupuestos Generales del Estado tendrán carácter anual, incluirán la totalidad de los gastos e ingresos del sector público estatal y en ellos se consignará el importe de los beneficios fiscales que afecten a los tributos del Estado.', null, '20aa9bd8915e1d3b705ca503aee85dd7d825a476678c0003809efe299fb5fe25', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '20aa9bd8915e1d3b705ca503aee85dd7d825a476678c0003809efe299fb5fe25')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tendrán carácter bienal e incluirán la totalidad de los gastos e ingresos del sector público estatal.', false), ('B', 'Tendrán carácter anual e incluirán la totalidad de los gastos e ingresos del sector público estatal.', true), ('C', 'Tendrán carácter anual e incluirán únicamente los gastos e ingresos de la Administración General del Estado.', false), ('D', 'Tendrán carácter plurianual, con un horizonte de tres ejercicios, e incluirán los gastos del sector público estatal.', false)) as v(label, body, ok)
)
