  select 'De acuerdo con el artículo 27.4 de la Ley 47/2003, General Presupuestaria, los derechos liquidados y las obligaciones reconocidas se aplicarán a los presupuestos:', 'El art. 27.4 LGP consagra el principio de presupuesto bruto: aplicación por el importe íntegro y prohibición de atender obligaciones minorando derechos, salvo autorización expresa de una ley (no de una orden ministerial).', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 27.4 LGP', 'Los derechos liquidados y las obligaciones reconocidas se aplicarán a los presupuestos por su importe íntegro, sin que puedan atenderse obligaciones mediante minoración de los derechos a liquidar o ya ingresados, salvo que la ley lo autorice de modo expreso.', null, '86eb1e7ce276380fc1d7769aab54b772f5dc322ec346f89a25e505e2f4af7f90', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '86eb1e7ce276380fc1d7769aab54b772f5dc322ec346f89a25e505e2f4af7f90')
  returning id
), o as (
