with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 47.2 de la Ley General Presupuestaria, en los compromisos de gasto de carácter plurianual el gasto que se impute al ejercicio inmediato siguiente no podrá exceder, con carácter general, del siguiente porcentaje del crédito inicial:', 'El art. 47.2 LGP limita a cuatro el número de ejercicios y fija los porcentajes del 70 % (primer ejercicio siguiente), 60 % (segundo) y 50 % (tercero y cuarto).', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 47.2 LGP', 'El número de ejercicios a que pueden aplicarse los gastos no será superior a cuatro. El gasto que se impute a cada uno de los ejercicios posteriores no podrá exceder de la cantidad que resulte de aplicar al crédito inicial a que corresponda la operación los siguientes porcentajes: en el ejercicio inmediato siguiente, el 70 por ciento, en el segundo ejercicio, el 60 por ciento, y en los ejercicios tercero y cuarto, el 50 por ciento.', null, 'ccb342be5517b2f97c1f4ce248530fdd1b2b2a4f047602ade8be6f855ce293c4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ccb342be5517b2f97c1f4ce248530fdd1b2b2a4f047602ade8be6f855ce293c4')
  returning id
