with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 47.3 de la Ley General Presupuestaria, en casos especialmente justificados, ¿quién puede acordar la modificación de los porcentajes de los compromisos de gasto plurianuales o incrementar el número de anualidades?', 'El art. 47.3 LGP atribuye esta facultad al Gobierno; el Ministro de Hacienda eleva la propuesta al Consejo de Ministros, previo informe de la Dirección General de Presupuestos.', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 47.3 LGP', 'El Gobierno, en casos especialmente justificados, podrá acordar la modificación de los porcentajes anteriores, incrementar el número de anualidades o autorizar la adquisición de compromisos de gastos que hayan de atenderse en ejercicios posteriores en el caso de que no exista crédito inicial.', null, '9e4733aec62d29158ddb9803f4eea41772c647574e649ced0cd2c46640d4fc8f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9e4733aec62d29158ddb9803f4eea41772c647574e649ced0cd2c46640d4fc8f')
