with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de las siguientes figuras NO está enumerada en el artículo 51 de la Ley General Presupuestaria entre las modificaciones de los créditos iniciales?', 'El art. 51 LGP enumera como modificaciones las transferencias, generaciones, ampliaciones, créditos extraordinarios y suplementos de crédito e incorporaciones. Los anticipos de caja fija son provisiones de fondos extrapresupuestarias (art. 78 LGP), no modificaciones de crédito.', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 51 LGP', 'La cuantía y finalidad de los créditos contenidos en los presupuestos de gastos sólo podrán ser modificadas durante el ejercicio, dentro de los límites y con arreglo al procedimiento establecido en los artículos siguientes, mediante: a) Transferencias. b) Generaciones. c) Ampliaciones. d) Créditos extraordinarios y suplementos de crédito. e) Incorporaciones.', null, '18bc8f5a664803c667dbba9f477e434dc4dae73d31de5a880986cdb5f2753fc7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '18bc8f5a664803c667dbba9f477e434dc4dae73d31de5a880986cdb5f2753fc7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las generaciones de crédito.', false), ('B', 'Las incorporaciones de crédito.', false), ('C', 'Los anticipos de caja fija.', true), ('D', 'Las transferencias de crédito.', false)) as v(label, body, ok)
)
