with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El servicio de gestión económica de un ministerio propone una transferencia de crédito. Según el artículo 52.1 de la Ley General Presupuestaria, ¿cuál de las siguientes transferencias está prohibida con carácter general?', 'El art. 52.1.a) LGP prohíbe transferir desde operaciones financieras al resto de créditos y desde operaciones de capital a operaciones corrientes; el sentido inverso (de corrientes a capital) no está vedado por esa letra.', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 52.1 LGP', 'a) No podrán realizarse desde créditos para operaciones financieras al resto de los créditos, ni desde créditos para operaciones de capital a créditos para operaciones corrientes.', null, '67b34df3c48a2648673c174dc1686a34c44307fc583e13fe070e82062038009c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '67b34df3c48a2648673c174dc1686a34c44307fc583e13fe070e82062038009c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una transferencia desde créditos para operaciones corrientes a créditos para operaciones de capital.', false), ('B', 'Una transferencia desde créditos para operaciones de capital a créditos para operaciones corrientes.', true), ('C', 'Una transferencia entre créditos de un mismo programa que cree un crédito nuevo.', false), ('D', 'Una transferencia entre créditos para operaciones corrientes de la misma sección presupuestaria.', false)) as v(label, body, ok)
)
