  select 'Según la Ley General Presupuestaria, las modificaciones que incrementan los créditos como consecuencia de la realización de determinados ingresos no previstos o superiores a los contemplados en el presupuesto inicial se denominan:', 'El art. 53.1 LGP define las generaciones como modificaciones que incrementan los créditos por ingresos no previstos o superiores a los presupuestados.', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 53.1 LGP', 'Las generaciones son modificaciones que incrementan los créditos como consecuencia de la realización de determinados ingresos no previstos o superiores a los contemplados en el presupuesto inicial.', null, '3984f03beffe7371072e2d2cd1038e90dd15ef4b768b7326bb0df7c9cedc5c42', false
