with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 55.1 de la Ley General Presupuestaria, cuando haya de realizarse un gasto que no pueda demorarse hasta el ejercicio siguiente y el crédito consignado sea insuficiente y no ampliable, procede tramitar:', 'El art. 55.1 LGP prevé el crédito extraordinario cuando no existe crédito adecuado y el suplementario cuando el consignado es insuficiente y no ampliable, siempre que no sea posible su dotación por las demás figuras del art. 51.', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 55.1 LGP', 'Cuando haya de realizarse con cargo al Presupuesto del Estado algún gasto que no pueda demorarse hasta el ejercicio siguiente, y no exista crédito adecuado o sea insuficiente y no ampliable el consignado y su dotación no resulte posible a través de las restantes figuras previstas en el artículo 51, deberá procederse a la tramitación de un crédito extraordinario o suplementario del inicialmente previsto.', null, '81ff7a11a4ddf18a0841a87c3de70baa553028cf3912e482c680248de8042059', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '81ff7a11a4ddf18a0841a87c3de70baa553028cf3912e482c680248de8042059')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un suplemento de crédito.', true), ('B', 'Un crédito extraordinario.', false), ('C', 'Una generación de crédito.', false), ('D', 'Una incorporación de crédito.', false)) as v(label, body, ok)
)
