with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 55.3 de la Ley General Presupuestaria, los créditos extraordinarios y suplementos de crédito del Estado para atender obligaciones del ejercicio corriente que se financien con cargo al Fondo de Contingencia serán autorizados por:', 'El art. 55.3 LGP atribuye al Consejo de Ministros esta autorización; en cambio, si se financian con baja en otros créditos o afectan a operaciones financieras, se remite un proyecto de ley a las Cortes (art. 55.2).', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 55.3 LGP', 'El Consejo de Ministros autorizará los créditos extraordinarios y suplementos de crédito para atender obligaciones del ejercicio corriente o de ejercicios anteriores si se hubiera anulado crédito en el ejercicio de procedencia, cuando se financien con cargo al Fondo de Contingencia.', null, 'c9f14c56961784007bb3d27bbf0f088a0fcb6dc7c97ff208f99e6f0f97e95df3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c9f14c56961784007bb3d27bbf0f088a0fcb6dc7c97ff208f99e6f0f97e95df3')
  returning id
