with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El director de un organismo autónomo necesita un suplemento de crédito de 300.000 euros, que representa el 6 % del capítulo correspondiente de su presupuesto inicial de gastos no afecta a gastos de personal y es la única modificación de este tipo en el ejercicio. Según el artículo 56.3 de la Ley General Presupuestaria, ¿quién es competente para autorizarlo?', 'El art. 56.3.a) LGP atribuye la competencia a presidentes o directores hasta el 10 % del capítulo sin superar 500.000 euros (excluidos gastos de personal y créditos del art. 44.2); por encima, hasta el 20 % y 1.000.000 euros, al Ministro de Hacienda; en los demás casos, al Consejo de Ministros.', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 56.3 LGP', 'a. A los Presidentes o Directores de los organismos hasta un importe del 10 % del correspondiente capítulo de su presupuesto inicial de gastos, cuando no supere la cuantía de 500.000 euros, excluidos los que afecten a gastos de personal o a los contemplados en el apartado 2 del artículo 44 de esta Ley, dando cuenta de los acuerdos al Ministro de que dependan y al Ministro de Hacienda.', null, '458bdac126410cea61a3c423255ad92f28fe6b56e92da8794338f6f9e680def2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '458bdac126410cea61a3c423255ad92f28fe6b56e92da8794338f6f9e680def2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Ministro de Hacienda.', false), ('B', 'El propio presidente o director del organismo, dando cuenta al Ministro de que dependa y al Ministro de Hacienda.', true), ('C', 'El Consejo de Ministros.', false), ('D', 'El Ministro del que dependa el organismo, previo informe de la Intervención Delegada.', false)) as v(label, body, ok)
)
