with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En diciembre del ejercicio anterior se concedió mediante ley un crédito extraordinario que no llegó a comprometerse antes del cierre. Según el artículo 58 de la Ley General Presupuestaria, ¿qué figura permite aplicar ese remanente en el ejercicio actual?', 'El art. 58.d) LGP permite incorporar a los créditos de un ejercicio los remanentes del anterior que resulten de créditos extraordinarios y suplementos de crédito concedidos mediante norma con rango de ley en el último mes del ejercicio presupuestario anterior.', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 58.d) LGP', 'No obstante lo dispuesto en el artículo 49, se podrán incorporar a los correspondientes créditos de un ejercicio los remanentes de crédito del ejercicio anterior, en los siguientes casos: […] d) Los que resulten de créditos extraordinarios y suplementos de crédito que hayan sido concedidos mediante norma con rango de ley en el último mes del ejercicio presupuestario anterior.', null, 'de3fde1f629993ffd2dd98505ff2bcef932bb72e6b6906775dcca5f2f7adc4fd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'de3fde1f629993ffd2dd98505ff2bcef932bb72e6b6906775dcca5f2f7adc4fd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una incorporación de crédito.', true), ('B', 'Una generación de crédito.', false), ('C', 'Una ampliación de crédito.', false), ('D', 'Una transferencia de crédito.', false)) as v(label, body, ok)
)
