with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 60 de la Ley General Presupuestaria, los anticipos de Tesorería que puede conceder el Gobierno para atender gastos inaplazables tienen como límite máximo en cada ejercicio:', 'El art. 60.1 LGP fija el límite en el 1 % de los créditos autorizados al Estado y exige que se haya iniciado la tramitación del crédito extraordinario o suplemento con dictamen favorable del Consejo de Estado, o que se haya promulgado una ley que obligue a concederlo.', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 60.1 LGP', 'Con carácter excepcional, el Gobierno, a propuesta del Ministro de Economía, podrá conceder anticipos de Tesorería para atender gastos inaplazables, con el límite máximo en cada ejercicio del uno por ciento de los créditos autorizados al Estado por la Ley de Presupuestos Generales del Estado', null, '750ae2f2c7429f12119447a26989d41df1f129ea36d3bb041196eeacc046f9a5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '750ae2f2c7429f12119447a26989d41df1f129ea36d3bb041196eeacc046f9a5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El dos por ciento de los créditos autorizados al Estado por la Ley de Presupuestos Generales del Estado.', false), ('B', 'El siete por ciento de los créditos para gastos corrientes en bienes y servicios.', false), ('C', 'El cinco por ciento del total de gastos para operaciones no financieras.', false), ('D', 'El uno por ciento de los créditos autorizados al Estado por la Ley de Presupuestos Generales del Estado.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una subdirección necesita reforzar un crédito de inversiones reales con baja en un crédito de gastos corrientes en bienes y servicios del mismo programa de su ministerio, sin afectar a gastos de personal ni a los créditos del artículo 43.2. Según el artículo 63.1 de la Ley General Presupuestaria, ¿quién puede autorizar esta transferencia?', 'El art. 63.1.a) LGP permite a los titulares de los ministerios autorizar, previo informe favorable de la Intervención Delegada, las transferencias entre créditos de un mismo programa o entre programas de un mismo servicio, siempre que no afecten a los de personal ni incrementen los créditos del art. 43.2.', 'age_adm_51_presupuesto', (select id from public.topics where slug = 'age-adm-51-presupuesto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 63.1.a) LGP', 'Los titulares de los distintos ministerios podrán autorizar, previo informe favorable de la Intervención Delegada competente en el ministerio o, en su caso, en las entidades a que se refiere el artículo 3.1 de esta ley, las siguientes modificaciones presupuestarias: a) Transferencias entre créditos de un mismo programa o entre programas de un mismo servicio', null, '7be06a80bfbe456b6de58885269bdc1187acbf2bfc128a549291221fa27033c0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7be06a80bfbe456b6de58885269bdc1187acbf2bfc128a549291221fa27033c0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Ministro de Hacienda, en todo caso.', false), ('B', 'El Consejo de Ministros, a propuesta del Ministro de Hacienda.', false), ('C', 'El titular del ministerio, previo informe favorable de la Intervención Delegada competente.', true), ('D', 'El Subsecretario del departamento, sin necesidad de informe de la Intervención.', false)) as v(label, body, ok)
)
