with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 136 de la Constitución Española, el Tribunal de Cuentas:', 'El art. 136.1 CE configura el Tribunal de Cuentas como supremo órgano fiscalizador, dependiente directamente de las Cortes Generales, por delegación de las cuales examina y comprueba la Cuenta General del Estado.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 136.1 CE', 'El Tribunal de Cuentas es el supremo órgano fiscalizador de las cuentas y de la gestión económica de Estado, así como del sector público. Dependerá directamente de las Cortes Generales y ejercerá sus funciones por delegación de ellas en el examen y comprobación de la Cuenta General del Estado.', null, '5e6518fd2882cdffc4e12732d4048d87b1ba8e77e8b7c81faa97efc25848971a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5e6518fd2882cdffc4e12732d4048d87b1ba8e77e8b7c81faa97efc25848971a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es el supremo órgano fiscalizador de las cuentas del Estado y depende directamente del Gobierno.', false), ('B', 'Es un órgano de control interno integrado en el Ministerio de Hacienda.', false), ('C', 'Es el supremo órgano fiscalizador de las cuentas y de la gestión económica del Estado y del sector público, y depende directamente de las Cortes Generales.', true), ('D', 'Depende del Consejo General del Poder Judicial y ejerce funciones de control externo.', false)) as v(label, body, ok)
)
