with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 73 de la Ley General Presupuestaria, cuando la naturaleza de la operación o gasto así lo determine:', 'El art. 73.7 LGP permite acumular en un solo acto las fases de ejecución del gasto precisas cuando la naturaleza de la operación lo determine; no permite suprimir fases ni alterar su orden.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 73.7 LGP', 'Cuando la naturaleza de la operación o gasto así lo determinen, se acumularán en un solo acto las fases de ejecución precisas.', null, 'de3ec0fec4c4ebe3d9e206f5e8fb6888684fea8e832522a9a03fa05d7e7bc785', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'de3ec0fec4c4ebe3d9e206f5e8fb6888684fea8e832522a9a03fa05d7e7bc785')
  returning id
