with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un departamento ministerial prepara un convenio con una entidad privada del que se derivará un gasto de 15 millones de euros. Según el artículo 74.5 de la Ley General Presupuestaria, el órgano competente para suscribirlo:', 'El art. 74.5 LGP exige autorización del Consejo de Ministros para suscribir convenios o contratos-programa cuyo gasto supere doce millones de euros; esa autorización implica la aprobación del gasto.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 74.5 LGP', 'Los órganos de los departamentos ministeriales, de sus organismos autónomos y de las entidades gestoras y servicios comunes de la Seguridad Social, competentes para la suscripción de convenios o contratos-programa con otras Administraciones públicas o con entidades públicas o privadas, necesitarán autorización del Consejo de Ministros cuando el importe del gasto que de aquellos se derive sea superior a doce millones de euros.', null, '5b61e2713f8558b2787ccb1fba78f7b6e69988aa30a4687ef0d229a12606e520', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5b61e2713f8558b2787ccb1fba78f7b6e69988aa30a4687ef0d229a12606e520')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Podrá suscribirlo sin autorización, porque el límite para requerirla es de veinte millones de euros.', false), ('B', 'Necesitará autorización del Consejo de Ministros, por superar el gasto los doce millones de euros.', true), ('C', 'Necesitará únicamente autorización del Ministro de Hacienda.', false), ('D', 'Necesitará autorización de las Cortes Generales mediante ley.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 47.6 de la Ley General Presupuestaria, en la tramitación anticipada de expedientes de contratación, de encargos a medios propios y de convenios:', 'El art. 47.6 LGP permite ultimar la tramitación anticipada hasta la adjudicación y formalización, aunque la ejecución empiece en ejercicios posteriores, respetando los límites y anualidades de los apartados 2 a 5 del mismo artículo.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 47.6 LGP', 'En el caso de la tramitación anticipada de expedientes de contratación a que se refiere el artículo 117.2 de la Ley de Contratos del Sector Público, de encargos a medios propios y de convenios, podrá ultimarse incluso con la adjudicación y formalización del correspondiente contrato, la formalización del encargo o la suscripción del convenio, aun cuando su ejecución, ya sea en una o en varias anualidades, deba iniciarse en ejercicios posteriores.', null, '8256b1f15782fe7e04ec82b53cba646c81c064d7b57e5aee99f97c88db82ae2b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8256b1f15782fe7e04ec82b53cba646c81c064d7b57e5aee99f97c88db82ae2b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo podrá llegarse hasta la aprobación del expediente, quedando la adjudicación para el ejercicio en que se inicie la ejecución.', false), ('B', 'No resultan aplicables los límites y porcentajes de los compromisos de gasto plurianuales.', false), ('C', 'Podrá ultimarse incluso con la adjudicación y formalización del contrato, aun cuando su ejecución deba iniciarse en ejercicios posteriores.', true), ('D', 'Se requiere en todo caso autorización previa del Consejo de Ministros.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
