with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un compromiso de gasto plurianual fue adquirido correctamente, pero la Ley de Presupuestos de un ejercicio posterior no autoriza crédito suficiente para atenderlo. Según el artículo 47 bis de la Ley General Presupuestaria, ¿qué debe hacer en primer lugar el órgano competente para aprobar y comprometer el gasto?', 'El art. 47 bis LGP ordena comunicarlo al tercero; después, si hay disponibilidades, se reprograman las obligaciones y se reajustan anualidades, y solo si no es posible se acuerda la resolución fijando las compensaciones que procedan.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 47 bis LGP', '1.º) El órgano competente para aprobar y comprometer el gasto estará obligado a comunicar tal circunstancia al tercero, tan pronto como se tenga conocimiento de ello.', null, 'f012ac118d496d7cfe1c6986d59489643984ac63d4251e059231a74751aefb93', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f012ac118d496d7cfe1c6986d59489643984ac63d4251e059231a74751aefb93')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Acordar directamente la resolución del negocio, sin compensación alguna.', false), ('B', 'Comunicar tal circunstancia al tercero, tan pronto como se tenga conocimiento de ello.', true), ('C', 'Solicitar un anticipo de Tesorería al Gobierno.', false), ('D', 'Imputar la anualidad al crédito para obligaciones de ejercicios anteriores.', false)) as v(label, body, ok)
)
