  select 'De acuerdo con el artículo 75.3 de la Ley General Presupuestaria, las órdenes de pago se expedirán, como regla general:', 'El art. 75.3 LGP establece como regla la expedición a favor del acreedor; por orden ministerial pueden regularse supuestos de expedición a favor de Habilitaciones, Cajas pagadoras, Depositarías, entidades colaboradoras u otros agentes mediadores.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 75.3 LGP', 'Las órdenes de pago se expedirán a favor del acreedor que figura en la correspondiente propuesta de pago si bien, por Orden del Ministro de Economía, se podrán regular los supuestos en que puedan expedirse a favor de Habilitaciones, Cajas pagadoras o Depositarías de fondos', null, '8fc644d867ef8eaaa93123beaa520292bc59fa656ba45ce93d03927f14149db3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8fc644d867ef8eaaa93123beaa520292bc59fa656ba45ce93d03927f14149db3')
  returning id
