  select 'Según el artículo 107 de la Ley General Presupuestaria, en la expedición de las órdenes de pago el Ordenador de Pagos aplicará:', 'El art. 107 LGP obliga al Ordenador de Pagos a aplicar criterios objetivos y cita a título de ejemplo la fecha de recepción, el importe, la aplicación presupuestaria y la forma de pago.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 107 LGP', 'El Ordenador de Pagos aplicará criterios objetivos en la expedición de las órdenes de pago, tales como la fecha de recepción, el importe de la operación, la aplicación presupuestaria y la forma de pago, entre otros.', null, 'c4975b3ef38d27cbd8ad25126426295034bbbbf7e1dc3d1626ef85ef27bda730', false
