  select 'Según el artículo 110 de la Ley General Presupuestaria, los pagos de la Administración General del Estado y sus organismos autónomos podrán realizarse:', 'El art. 110 LGP admite transferencia, cheque, efectivo o cualquier otro medio de pago, bancario o no, en las condiciones que establezcan los Ministros de Economía y de Hacienda.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 110 LGP', 'los ingresos y los pagos de la Administración General del Estado y sus organismos autónomos podrán realizarse mediante transferencia bancaria, cheque, efectivo o cualesquiera otros medios de pago, sean o no bancarios.', null, '81a5a5c18ffb6be0de35aabc3e7fc85cfca78a63b6567fe248f97c11497fcb23', false
