  select 'Según el artículo 142.2 de la Ley General Presupuestaria, el control de la Intervención General de la Administración del Estado se realizará mediante:', 'El art. 142.2 LGP enumera las tres modalidades de control interno: función interventora, control financiero permanente y auditoría pública.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 142.2 LGP', 'El control se realizará mediante el ejercicio de la función interventora, el control financiero permanente y la auditoría pública, a que se refieren los capítulos II, III y IV de este título.', null, '800b3c3bccb901f47c4310d0e94f634ac74ce968c8ae9deaae3f68bd7a433a79', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '800b3c3bccb901f47c4310d0e94f634ac74ce968c8ae9deaae3f68bd7a433a79')
