  select 'Según el artículo 148 de la Ley General Presupuestaria, la función interventora tiene por objeto controlar los actos del sector público estatal que den lugar al reconocimiento de derechos o a la realización de gastos:', 'El art. 148 LGP define la función interventora como un control previo (antes de la aprobación de los actos); el control continuo es el financiero permanente (art. 157) y el posterior, la auditoría pública (art. 162).', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 148 LGP', 'La función interventora tiene por objeto controlar, antes de que sean aprobados, los actos del sector público estatal que den lugar al reconocimiento de derechos o a la realización de gastos, así como los ingresos y pagos que de ellos se deriven', null, 'c4092c93825ba32ba58618eee8abcae1c4a96791e303adc9538437981ff3de6e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c4092c93825ba32ba58618eee8abcae1c4a96791e303adc9538437981ff3de6e')
