  select 'De acuerdo con el artículo 150.2 de la Ley General Presupuestaria, respecto de la ordenación del pago, el ejercicio de la función interventora comprende:', 'El art. 150.2 LGP comprende la fiscalización previa de los actos que aprueban gastos o reconocen derechos, la intervención del reconocimiento de obligaciones y de la comprobación de la inversión, la intervención formal de la ordenación del pago y la intervención material del pago.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 150.2 LGP', 'a) La fiscalización previa de los actos que reconozcan derechos de contenido económico, aprueben gastos, adquieran compromisos de gasto, o acuerden movimientos de fondos y valores. b) La intervención del reconocimiento de las obligaciones y de la comprobación de la inversión. c) La intervención formal de la ordenación del pago. d) La intervención material del pago.', null, 'bed4c9c6be04e81fd4333ac1e8064ece308e6cb3041e33f7cd03b60bb7ddbcaf', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bed4c9c6be04e81fd4333ac1e8064ece308e6cb3041e33f7cd03b60bb7ddbcaf')
  returning id
), o as (
