  select 'Una unidad tramita un contrato menor de suministro de material de oficina. Según el artículo 151 de la Ley General Presupuestaria, en relación con la fiscalización previa:', 'El art. 151.a) LGP excluye de la fiscalización previa los contratos menores y los asimilados a ellos en virtud de la legislación contractual.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 151.a) LGP', 'No estarán sometidos a la fiscalización previa prevista en el apartado 2.a) del artículo anterior: a) los contratos menores así como los asimilados a ellos en virtud de la legislación contractual;', null, '2e6b8d5c1ecd36ba4ddf7a9fd93f37fd512ad8d6d1366313a629e4ef0ec6a1df', false
