  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Está sometido a fiscalización previa de requisitos básicos.', false), ('B', 'No está sometido a fiscalización previa.', true), ('C', 'Está sometido a fiscalización previa solo si supera 5.000 euros.', false), ('D', 'Debe someterse a fiscalización previa del Tribunal de Cuentas.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Al fiscalizar un expediente de gasto, la Intervención Delegada se manifiesta en desacuerdo con el procedimiento seguido y formula reparo por escrito. Según el artículo 154.1 de la Ley General Presupuestaria, la formulación del reparo:', 'El art. 154.1 LGP dispone que el reparo suspende la tramitación hasta que se subsanen las deficiencias o, si no se acepta, se resuelva la discrepancia conforme al art. 155.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 154.1 LGP', 'La formulación del reparo suspenderá la tramitación del expediente hasta que sea solventado, bien por la subsanación de las deficiencias observadas o bien, en el caso de no aceptación del reparo, por la resolución del procedimiento previsto en el artículo siguiente.', null, '886386efdd58a2d9bae61134e7728b858622073ed7373459fc356d1302ac7c2f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '886386efdd58a2d9bae61134e7728b858622073ed7373459fc356d1302ac7c2f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Suspenderá la tramitación del expediente hasta que sea solventado.', true), ('B', 'No suspenderá la tramitación, pero deberá constar en el expediente.', false), ('C', 'Supondrá el archivo definitivo del expediente.', false), ('D', 'Obligará a remitir el expediente al Tribunal de Cuentas.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un órgano gestor no acepta un reparo formulado directamente por la Intervención General de la Administración del Estado y plantea discrepancia. Según el artículo 155 de la Ley General Presupuestaria, ¿a quién corresponde adoptar la resolución definitiva?', 'El art. 155 LGP atribuye a la IGAE la resolución de las discrepancias con reparos de las intervenciones delegadas; cuando el reparo lo formula la propia IGAE (o lo confirma), la resolución definitiva corresponde al Consejo de Ministros.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 155.b) LGP', 'b) Cuando el reparo haya sido formulado por la Intervención General de la Administración del Estado o este centro directivo haya confirmado el de otra Intervención General o delegada, subsistiendo la discrepancia, corresponderá al Consejo de Ministros adoptar resolución definitiva.', null, '91a1a7b3b0682df2def862ddca59c400b2e7a4cb55a32ba17fe8f2b5a4d9b8f5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '91a1a7b3b0682df2def862ddca59c400b2e7a4cb55a32ba17fe8f2b5a4d9b8f5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Ministro de Hacienda.', false), ('B', 'A la propia Intervención General de la Administración del Estado.', false), ('C', 'Al Tribunal de Cuentas.', false), ('D', 'Al Consejo de Ministros.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 156 de la Ley General Presupuestaria, en caso de omisión de la función interventora preceptiva, acordar el sometimiento del asunto al Consejo de Ministros corresponde:', 'El art. 156.3 LGP atribuye esta competencia, indelegable, al titular del departamento; el acuerdo favorable del Consejo de Ministros no exime de las responsabilidades que procedan (art. 156.4).', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 156.3 LGP', 'Corresponderá al titular del departamento al que pertenezca el órgano responsable de la tramitación del expediente o al que esté adscrito el organismo autónomo, sin que dicha competencia pueda ser objeto de delegación, acordar, en su caso, el sometimiento del asunto al Consejo de Ministros para que adopte la resolución procedente.', null, '252f6ea1e7306f4fa6167bf010915a27ae6aa805260cbe01642777cdbddc9d63', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '252f6ea1e7306f4fa6167bf010915a27ae6aa805260cbe01642777cdbddc9d63')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al titular del departamento al que pertenezca el órgano responsable de la tramitación del expediente, sin que dicha competencia pueda ser objeto de delegación.', true), ('B', 'Al Interventor General de la Administración del Estado, que podrá delegarlo en los interventores delegados.', false), ('C', 'Al Subsecretario del departamento, por delegación del Ministro.', false), ('D', 'Al Ministro de Hacienda, en todo caso.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 164 de la Ley General Presupuestaria, la modalidad de auditoría pública que constituye el examen sistemático y objetivo de las operaciones y procedimientos para valorar su racionalidad económico-financiera y su adecuación a los principios de la buena gestión es:', 'El art. 164.1 LGP distingue la auditoría de regularidad contable (adecuación a la normativa contable), la de cumplimiento (conformidad con las normas aplicables) y la operativa (racionalidad económico-financiera y buena gestión).', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 164.1.c) LGP', 'c) La auditoría operativa, que constituye el examen sistemático y objetivo de las operaciones y procedimientos de una organización, programa, actividad o función pública, con el objeto de proporcionar una valoración independiente de su racionalidad económico-financiera y su adecuación a los principios de la buena gestión', null, '19ec3762d0b629728b176fa63c7a9b296f464c949b0788862be9377cda214f65', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '19ec3762d0b629728b176fa63c7a9b296f464c949b0788862be9377cda214f65')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La auditoría de regularidad contable.', false), ('B', 'La auditoría de cumplimiento.', false), ('C', 'La auditoría de cuentas anuales.', false), ('D', 'La auditoría operativa.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley General Presupuestaria, la Cuenta General del Estado se remite al Tribunal de Cuentas antes del 31 de octubre del año siguiente al que se refiera. ¿En qué plazo debe el Tribunal de Cuentas proceder a su examen y comprobación?', 'Según los arts. 131.1 y 132 LGP, la IGAE forma la Cuenta General, el Gobierno la remite al Tribunal de Cuentas antes del 31 de octubre del año siguiente y este, por delegación de las Cortes, la examina en seis meses; el Pleno, oído el Fiscal, dicta la declaración definitiva.', 'age_adm_53_ejecucion_gasto', (select id from public.topics where slug = 'age-adm-53-ejecucion-gasto'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Arts. 131.1 y 132 LGP', 'La Cuenta General del Estado de cada año se formará por la Intervención General de la Administración del Estado y se elevará al Gobierno para su remisión al Tribunal de Cuentas antes del día 31 de octubre del año siguiente al que se refiera. […] El Tribunal de Cuentas, por delegación de las Cortes Generales, procederá al examen y comprobación de la Cuenta General del Estado dentro del plazo de seis meses a partir de la fecha en que las haya recibido.', null, '181e7f2d70a51b954d49a3ecfdc172232bc5720ad8317321d42e188a8cf620f6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '181e7f2d70a51b954d49a3ecfdc172232bc5720ad8317321d42e188a8cf620f6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dentro del plazo de tres meses a partir de la fecha en que la haya recibido.', false), ('B', 'Dentro del plazo de seis meses a partir de la fecha en que la haya recibido.', true), ('C', 'Antes del 31 de diciembre del año en que la haya recibido.', false), ('D', 'Dentro del plazo de un año a partir de la fecha en que la haya recibido.', false)) as v(label, body, ok)
)
