insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 462/2002, de 24 de mayo, sobre indemnizaciones por razón del servicio (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
