insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-54-retribuciones' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes supuestos da origen a indemnización según el artículo 1 del Real Decreto 462/2002, sobre indemnizaciones por razón del servicio?', 'El art. 1.1 del RD 462/2002 enumera comisiones de servicio, desplazamientos dentro del término municipal por razón del servicio, traslados de residencia y asistencias. El desplazamiento habitual al centro de trabajo nunca es comisión de servicio (art. 3.1).', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 1.1 RD 462/2002', '1. Darán origen a indemnización o compensación los supuestos siguientes, en las circunstancias, condiciones y límites contenidos en el presente Real Decreto: a) Comisiones de servicio con derecho a indemnización. b) Desplazamientos dentro del término municipal por razón de servicio. c) Traslados de residencia.', null, 'e75aa2bca00ffa9cb12763fe438708c46a835b526bb91fb759c15028529e6ba1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e75aa2bca00ffa9cb12763fe438708c46a835b526bb91fb759c15028529e6ba1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las horas extraordinarias realizadas en la oficina.', false), ('B', 'Los traslados de residencia.', true), ('C', 'La especial dedicación exigida por el puesto.', false), ('D', 'El desplazamiento habitual desde el domicilio al centro de trabajo.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el RD 462/2002, con carácter general, la designación de las comisiones de servicio con derecho a indemnización compete:', 'El art. 4.1 del RD 462/2002 atribuye la designación al Subsecretario del Departamento o a la autoridad superior del organismo o entidad (en Defensa, también a los Jefes de Estado Mayor).', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 4.1 RD 462/2002', '1. La designación de las comisiones de servicio con derecho a indemnización compete al Subsecretario de cada Departamento ministerial o a la autoridad superior del Organismo o Entidad correspondiente.', null, '17eca5cec039b8ff96a3e3f1b1fdadb05c0f8aade5b2b83c3b371ab50d9f231f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '17eca5cec039b8ff96a3e3f1b1fdadb05c0f8aade5b2b83c3b371ab50d9f231f')
  returning id
), o as (
