  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Ministro de Hacienda.', false), ('B', 'Al jefe inmediato del comisionado.', false), ('C', 'Al Subsecretario de cada Departamento ministerial o a la autoridad superior del Organismo o Entidad correspondiente.', true), ('D', 'A la Dirección General de la Función Pública.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 5 del RD 462/2002, salvo casos excepcionales, toda comisión de servicio con derecho a indemnización no durará más de:', 'El art. 5.1 limita las comisiones a un mes en territorio nacional y tres en el extranjero; si se prevé mayor duración, tienen la consideración de residencia eventual (art. 6.1).', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 5.1 RD 462/2002', '1. Toda comisión con derecho a indemnización, salvo casos excepcionales, no durará más de un mes en territorio nacional y de tres en el extranjero.', null, '15f281bc74dfd5b9fbe10b9375beaf1f909f8b08810078c2ba48e5a6c81f4c5d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '15f281bc74dfd5b9fbe10b9375beaf1f909f8b08810078c2ba48e5a6c81f4c5d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes en territorio nacional y tres en el extranjero.', true), ('B', 'Quince días en territorio nacional y un mes en el extranjero.', false), ('C', 'Tres meses en territorio nacional y seis en el extranjero.', false), ('D', 'Un mes, tanto en territorio nacional como en el extranjero.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el RD 462/2002, la duración de una comisión con la consideración de residencia eventual no podrá exceder de:', 'El art. 6.2 fija un máximo de un año para la residencia eventual, prorrogable como máximo un año más; si se prevé más de un año, debe crearse el puesto de trabajo (art. 6.3).', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 6.2 RD 462/2002', '2. La duración de la residencia eventual no podrá exceder de un año, salvo que se prorrogue por el tiempo estrictamente indispensable por la autoridad que haya designado la comisión según lo previsto en el artículo 4.1 anterior. La duración de la prórroga no podrá en ningún caso exceder de un año.', null, '1a6f7b3e44b8717cb1400f9691ea908b2399126530e72e8d075983cf73312cc3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1a6f7b3e44b8717cb1400f9691ea908b2399126530e72e8d075983cf73312cc3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Seis meses, prorrogables por otros seis.', false), ('B', 'Tres meses, sin posibilidad de prórroga.', false), ('C', 'Un año, salvo prórroga por el tiempo estrictamente indispensable, que no podrá exceder de otro año.', true), ('D', 'Dos años, prorrogables por un año más.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una funcionaria realiza una comisión de servicio de un solo día que empieza a las 9:00 y termina a las 17:00, sin pernoctar. Según el artículo 12 del RD 462/2002, ¿qué indemnización por dietas le corresponde?', 'En comisiones de un día o menos no se cobran alojamiento ni manutención, salvo que duren al menos cinco horas, empiecen antes de las 14:00 y acaben después de las 16:00: entonces se percibe el 50 % de la dieta de manutención (art. 12.1).', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 12.1 RD 462/2002', '1. En las comisiones cuya duración sea igual o inferior a un día natural, en general no se percibirán indemnizaciones por gastos de alojamiento ni de manutención salvo cuando, teniendo la comisión una duración mínima de cinco horas, ésta se inicie antes de las catorce horas y finalice después de las dieciséis horas, supuesto en que se percibirá el 50 por 100 del importe de la dieta por manutención.', null, 'b98e596e49a5fcf4b44901916d5b78c3bdecb86f68c925d153116f5addcfe4d2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b98e596e49a5fcf4b44901916d5b78c3bdecb86f68c925d153116f5addcfe4d2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El 100 por 100 de la dieta por manutención y el alojamiento de un día.', false), ('B', 'El 50 por 100 del importe de la dieta por manutención.', true), ('C', 'Ninguna, porque la comisión no supera veinticuatro horas.', false), ('D', 'El 100 por 100 de la dieta por manutención, sin alojamiento.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el RD 462/2002, la cuantía de la indemnización por residencia eventual la fija la autoridad que confiere la comisión dentro del límite máximo, sin necesidad de justificación documental, del:', 'El art. 16.1 limita la indemnización de residencia eventual al 80 % de las dietas enteras de los anexos II y III; el porcentaje debe figurar expresamente en la orden de comisión.', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 16.1 RD 462/2002', '1. La cuantía del importe por indemnización de residencia eventual será fijada por la misma autoridad que confiera la comisión dentro del límite máximo, sin que se necesite justificación documental, del 80 por 100 del importe de las dietas enteras que corresponderían con arreglo a lo dispuesto en los anexos II y III del presente Real Decreto', null, '7e53447a38b3113f95051f7bb1a6b88102f88ae2b8122cb8f53a14d256d47df4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7e53447a38b3113f95051f7bb1a6b88102f88ae2b8122cb8f53a14d256d47df4')
