with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 19 del RD 462/2002, el personal al que se encomienda una comisión de servicio:', 'El art. 19.1 reconoce el derecho de anticipo del importe aproximado de dietas, pluses, residencia eventual y gastos de viaje, con devolución posterior de lo que proceda.', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 19.1 RD 462/2002', '1. El personal a quien se encomiende una comisión de servicio de las reguladas en el artículo 3 del presente Real Decreto tendrá derecho a percibir por adelantado el importe aproximado de las dietas, pluses, residencia eventual y gastos de viaje sin perjuicio de la devolución del anticipo, en la cuantía que proceda en su caso, una vez finalizada la comisión de servicios.', null, '54796d0215d6183acbd6523934d679385d1b300a03b2c9b6c9d6974b8295cae3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '54796d0215d6183acbd6523934d679385d1b300a03b2c9b6c9d6974b8295cae3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo puede percibir la indemnización una vez finalizada y justificada la comisión.', false), ('B', 'Puede percibir por adelantado únicamente los gastos de viaje.', false), ('C', 'Tiene derecho a un anticipo del doble del importe previsto, que no debe justificarse.', false), ('D', 'Tiene derecho a percibir por adelantado el importe aproximado de las dietas, pluses, residencia eventual y gastos de viaje, sin perjuicio de la devolución que proceda al finalizar la comisión.', true)) as v(label, body, ok)
)
