with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Por la supresión de la oficina en que presta servicio, un funcionario es trasladado forzosamente a otro municipio junto con su cónyuge e hijo. Según el RD 462/2002, ¿qué indemnización le corresponde?', 'El art. 23.1 indemniza el traslado forzoso (incluida la supresión de unidades, art. 23.2.b) con gastos de viaje, transporte de mobiliario y enseres y tres dietas por persona; los traslados por sanción no dan derecho a indemnización (art. 23.3).', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 23.1 y 23.3 RD 462/2002', '1. En caso de traslado forzoso que origine cambio del término municipal de residencia oficial dentro del territorio nacional, el personal tendrá derecho al abono de los gastos de viaje, incluidos los de su familia, al pago de los gastos de transporte de mobiliario y enseres y, en cualquier caso, a una indemnización equivalente a tres dietas por el titular y cada miembro de su familia que efectivamente se traslade.', null, '157e71f203e1c87fc95c102159c503155545f0e57629048e0f0cef7efef4ceb9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '157e71f203e1c87fc95c102159c503155545f0e57629048e0f0cef7efef4ceb9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los gastos de viaje, incluidos los de su familia, el transporte de mobiliario y enseres y una indemnización equivalente a tres dietas por el titular y cada miembro de su familia que se traslade.', true), ('B', 'Únicamente los gastos de viaje del titular.', false), ('C', 'Una indemnización equivalente a una dieta por el titular, sin derecho a gastos de familiares.', false), ('D', 'Ninguna, porque los traslados de residencia no son indemnizables.', false)) as v(label, body, ok)
)
