with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 27 del RD 462/2002, las cantidades percibidas por el conjunto de los tres tipos de asistencias no podrán totalizar por año natural un importe superior al:', 'El art. 27.3 fija un tope conjunto del 50 % de las retribuciones anuales del puesto (sin antigüedad); el exceso se ingresa en el Tesoro. Para órganos colegiados y consejos de administración el límite específico es del 40 % (art. 28.3).', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 27.3 RD 462/2002', '3. Dichas cantidades en ningún caso podrán totalizar, para el conjunto de los tres tipos de asistencias, un importe por año natural superior al 50 por 100 de las retribuciones anuales, excluidas las de carácter personal derivadas de la antigüedad, que se perciban por el puesto de trabajo desempeñado.', null, '784188697a47c43757486f2219cd9442117652924b33afa1f0d103c6885b2cef', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '784188697a47c43757486f2219cd9442117652924b33afa1f0d103c6885b2cef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '40 por 100 de las retribuciones anuales, incluidas las derivadas de la antigüedad.', false), ('B', '50 por 100 de las retribuciones anuales, excluidas las de carácter personal derivadas de la antigüedad, del puesto de trabajo desempeñado.', true), ('C', '30 por 100 de las retribuciones básicas anuales.', false), ('D', '100 por 100 de las retribuciones complementarias anuales.', false)) as v(label, body, ok)
)
