  select 'Según el RD 462/2002, en las comisiones de servicio en que se viaje en avión, se indemnizará el importe del billete dentro de las tarifas de:', 'El art. 17.2.a) limita los viajes en avión a clase turista o inferior; solo por urgencia, representación o duración del viaje puede autorizarse una clase superior.', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 17.2.a) RD 462/2002', 'a) Avión: clase turista o clase de cuantía inferior a la prevista para aquélla.', null, '53b56d6551e0c289a4fdd8ffe80fdab6fc17bbcc1eb750c7d79860036b139f98', false
