)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 22 del TREBEP, las retribuciones básicas retribuyen al funcionario:', 'El art. 22.2 TREBEP vincula las básicas al Subgrupo o Grupo y a la antigüedad; incluyen los componentes de sueldo y trienios de las pagas extraordinarias. Puesto, carrera y desempeño se retribuyen con las complementarias (art. 22.3).', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 22.2 TREBEP', '2. Las retribuciones básicas son las que retribuyen al funcionario según la adscripción de su cuerpo o escala a un determinado Subgrupo o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo, y por su antigüedad en el mismo.', null, 'f5c3939ffc63f007593abb2e52f90d0e57342b6cee36d97e2cfab756dae04786', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f5c3939ffc63f007593abb2e52f90d0e57342b6cee36d97e2cfab756dae04786')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Según las características del puesto de trabajo que desempeña.', false), ('B', 'Según la adscripción de su cuerpo o escala a un determinado Subgrupo o Grupo de clasificación profesional y por su antigüedad en el mismo.', true), ('C', 'Según el grado de interés, iniciativa o esfuerzo con que desempeña su trabajo.', false), ('D', 'Según la carrera profesional y el desempeño alcanzados.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 22 del TREBEP, ¿qué retribuyen las retribuciones complementarias?', 'El art. 22.3 TREBEP define las complementarias por el puesto, la carrera y el desempeño. Los gastos por razón del servicio se compensan con indemnizaciones (art. 28), que no son retribuciones.', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 22.3 TREBEP', '3. Las retribuciones complementarias son las que retribuyen las características de los puestos de trabajo, la carrera profesional o el desempeño, rendimiento o resultados alcanzados por el funcionario.', null, 'd035c8f3674c3ba03fe611b4510402448d0035a63fdd29b983c0f07d562e845e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd035c8f3674c3ba03fe611b4510402448d0035a63fdd29b983c0f07d562e845e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las características de los puestos de trabajo, la carrera profesional o el desempeño, rendimiento o resultados alcanzados por el funcionario.', true), ('B', 'La pertenencia a un Subgrupo o Grupo de clasificación profesional y la antigüedad.', false), ('C', 'Exclusivamente los servicios extraordinarios prestados fuera de la jornada normal.', false), ('D', 'Los gastos que el funcionario realiza por razón del servicio.', false)) as v(label, body, ok)
)
