with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una unidad de inspección propone repartir entre sus funcionarios un porcentaje de las multas que imponga, como incentivo. Según el TREBEP:', 'El art. 22.5 TREBEP prohíbe percibir participación en tributos u otros ingresos de las Administraciones y cualquier participación o premio en multas como contraprestación de un servicio.', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 22.5 TREBEP', '5. No podrá percibirse participación en tributos o en cualquier otro ingreso de las Administraciones Públicas como contraprestación de cualquier servicio, participación o premio en multas impuestas, aun cuando estuviesen normativamente atribuidas a los servicios.', null, 'c5477406d49ec4bccbe277b768f2207258e8f6d1430aeffe13f7560983aca8da', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c5477406d49ec4bccbe277b768f2207258e8f6d1430aeffe13f7560983aca8da')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es posible si se configura como complemento de productividad.', false), ('B', 'Es posible si lo autoriza la Ley de Presupuestos Generales del Estado de cada año.', false), ('C', 'Es posible siempre que el reparto no supere el 30 % de las retribuciones básicas.', false), ('D', 'No es posible: no puede percibirse participación ni premio en multas impuestas, aun cuando estuviesen normativamente atribuidas a los servicios.', true)) as v(label, body, ok)
)
