with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 21 del TREBEP, las cuantías de las retribuciones básicas de los funcionarios deben reflejarse para cada ejercicio presupuestario en:', 'El art. 21.1 TREBEP exige que las cuantías de las básicas, el incremento global de las complementarias y el de la masa salarial del personal laboral figuren en la ley de presupuestos de cada ejercicio.', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 21.1 TREBEP', '1. Las cuantías de las retribuciones básicas y el incremento de las cuantías globales de las retribuciones complementarias de los funcionarios, así como el incremento de la masa salarial del personal laboral, deberán reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos.', null, '12ce8a55658de53fd7466c0b939fdb0d3e7193017bd49cccdb5a655a1c4ce978', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '12ce8a55658de53fd7466c0b939fdb0d3e7193017bd49cccdb5a655a1c4ce978')
