  select 'Entre los factores que, según el artículo 24 del TREBEP, deben atenderse al fijar la cuantía y estructura de las retribuciones complementarias, ¿cuál corresponde a la compensación de las horas trabajadas fuera de la jornada?', 'El art. 24.d) TREBEP recoge como factor los servicios extraordinarios fuera de la jornada normal. La antigüedad no es factor de las complementarias, sino de las básicas (trienios).', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 24.d) TREBEP', 'd) Los servicios extraordinarios prestados fuera de la jornada normal de trabajo.', null, 'ba936148edd13e87ad4e83045ace3a29eb083513769d7a2853189c80ad6c191a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ba936148edd13e87ad4e83045ace3a29eb083513769d7a2853189c80ad6c191a')
  returning id
), o as (
