  select 'Un aspirante que ha superado la oposición al Cuerpo General Administrativo (Subgrupo C1) es nombrado funcionario en prácticas. Según el artículo 26 del TREBEP, sus retribuciones serán, como mínimo:', 'El art. 26 TREBEP deja a cada Administración fijar las retribuciones de los funcionarios en prácticas, con el mínimo del sueldo del Subgrupo o Grupo al que aspiran a ingresar.', 'age_adm_54_retribuciones', (select id from public.topics where slug = 'age-adm-54-retribuciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 26 TREBEP', 'Las Administraciones Públicas determinarán las retribuciones de los funcionarios en prácticas que, como mínimo, se corresponderán a las del sueldo del Subgrupo o Grupo, en el supuesto de que éste no tenga Subgrupo, en que aspiren a ingresar.', null, 'e759f076aed8a3a1be1e1db9b532b18572ad7a301c9af71e3cc116c1bdaab836', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e759f076aed8a3a1be1e1db9b532b18572ad7a301c9af71e3cc116c1bdaab836')
  returning id
), o as (
