  select 'Según el artículo 40 de la Ley General Presupuestaria, en la clasificación económica de los estados de gastos, dentro de los créditos para operaciones corrientes se distinguirán:', 'El art. 40.1.c) LGP separa operaciones corrientes (personal, bienes y servicios, gastos financieros y transferencias corrientes), de capital (inversiones reales y transferencias de capital) y financieras (activos y pasivos financieros), además del Fondo de Contingencia.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 40.1.c) LGP', 'En los créditos para operaciones corrientes se distinguirán los gastos de personal, los gastos corrientes en bienes y servicios, los gastos financieros y las transferencias corrientes.', null, '0bb1e9d25c27a6f61a3df34716ff7628897c66349726989acd6fe42c5d1a7dfc', false
