with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un contrato de obra de carácter plurianual que no se realiza bajo la modalidad de abono total del precio, el artículo 47.2 de la Ley General Presupuestaria exige, en el momento de la adjudicación:', 'El art. 47.2 LGP impone en los contratos de obra plurianuales una retención adicional del 10 % del importe de adjudicación, aplicada al ejercicio en que finalice el plazo de la obra o al siguiente, y que computa dentro de los porcentajes del artículo.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 47.2 LGP', 'En los contratos de obra de carácter plurianual, con excepción de los realizados bajo la modalidad de abono total del precio, se efectuará una retención adicional de crédito del 10 por ciento del importe de adjudicación, en el momento en que ésta se realice.', null, '00e70f57e9aef81e63e0dc860d3280796dd3dec81947451479274df01030329c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '00e70f57e9aef81e63e0dc860d3280796dd3dec81947451479274df01030329c')
  returning id
