with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 48 de la Ley General Presupuestaria, cuando se difiera el pago del precio de compra de un bien inmueble adquirido directamente cuyo importe exceda de seis millones de euros, el desembolso inicial a la firma de la escritura:', 'El art. 48.1 LGP permite diferir el pago en adquisiciones directas de inmuebles de más de seis millones con un desembolso inicial mínimo del 25 %, distribuyendo el resto en los cuatro ejercicios siguientes dentro de los límites del art. 47.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 48.1 LGP', 'Podrá ser diferido el vencimiento de la obligación de pago del precio de compra de bienes inmuebles adquiridos directamente cuyo importe exceda de seis millones de euros, sin que, en ningún caso, el desembolso inicial a la firma de la escritura pueda ser inferior al 25 por ciento del precio, pudiendo distribuirse el resto en los cuatro ejercicios siguientes dentro de las limitaciones porcentuales contenidas en el artículo 47 de esta ley.', null, '8511c02f4d20985ab19db792d94d394e4e24eb813330ed3404f6041f67d530ec', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8511c02f4d20985ab19db792d94d394e4e24eb813330ed3404f6041f67d530ec')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
