with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 78.3 de la Ley General Presupuestaria, la Agencia Española de Cooperación Internacional está autorizada para que la cuantía global de sus anticipos de caja fija alcance, como máximo:', 'El art. 78.3 LGP autoriza a la Agencia Española de Cooperación Internacional a superar el 7 % general hasta un máximo del 14 %. El 10 % se refiere a los créditos del art. 23 del programa 222A «Seguridad ciudadana».', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 78.3 LGP', 'Se autoriza a la Agencia Española de Cooperación Internacional para que la cuantía global de los anticipos de caja fija pueda exceder del siete por ciento previsto en este artículo, hasta un máximo del 14 por ciento del total de los créditos del capítulo destinado a gastos corrientes en bienes y servicios del presupuesto vigente en cada momento.', null, '4067d912c12cf74704afbac2f22c97c049415e830a653051183d50ff5892ba76', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4067d912c12cf74704afbac2f22c97c049415e830a653051183d50ff5892ba76')
