with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 79 de la Ley General Presupuestaria, podrán tramitarse propuestas de pagos presupuestarios y librarse fondos con el carácter de «a justificar»:', 'El art. 79.1 LGP configura los pagos a justificar como excepción, cuando no puede aportarse la documentación justificativa en el momento del art. 73.4; también caben para servicios en el extranjero. Los gastos periódicos o repetitivos son propios de los anticipos de caja fija.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 79.1 LGP', 'Cuando, excepcionalmente, no pueda aportarse la documentación justificativa de las obligaciones en el momento previsto en el apartado 4 del artículo 73, podrán tramitarse propuestas de pagos presupuestarios y librarse fondos con el carácter de a justificar.', null, 'bf867fc3e10b4e6f27357c8f7c3cfacb8f02ec2311f0a0ad7da0292338524740', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bf867fc3e10b4e6f27357c8f7c3cfacb8f02ec2311f0a0ad7da0292338524740')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre que se trate de gastos periódicos o repetitivos de bienes corrientes y servicios.', false), ('B', 'Cuando, excepcionalmente, no pueda aportarse la documentación justificativa de las obligaciones en el momento previsto para el reconocimiento de la obligación.', true), ('C', 'Cuando el gasto no supere el 7 por ciento de los créditos del capítulo de gastos corrientes en bienes y servicios.', false), ('D', 'Únicamente para gastos que se realicen en el extranjero.', false)) as v(label, body, ok)
)
