with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario recibe una orden de pago a justificar para atender gastos de un pago de expropiación. Según el artículo 79.4 de la Ley General Presupuestaria, ¿en qué plazo podrá rendir la cuenta justificativa, sin necesidad de ampliación?', 'El art. 79.4 LGP fija un plazo general de tres meses, que es de seis meses para pagos de expropiaciones y pagos en el extranjero; excepcionalmente puede ampliarse a seis y doce meses, respectivamente.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 79.4 LGP', 'El plazo de rendición de las cuentas será de tres meses, excepto las correspondientes a pagos de expropiaciones y pagos en el extranjero que podrán ser rendidas en el plazo de seis meses.', null, 'bcab7930691405c48d113822f89c74f1d6e9cc29913fc9583ed6af2fa9764c7c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bcab7930691405c48d113822f89c74f1d6e9cc29913fc9583ed6af2fa9764c7c')
  returning id
), o as (
