  select 'Según el artículo 79.3 de la Ley General Presupuestaria, la cantidad no invertida de los libramientos a justificar en el ejercicio en que se aprobaron será justificada:', 'El art. 79.3 LGP solo permite imputar a los libramientos a justificar obligaciones del ejercicio y exige justificar lo no invertido con carta de pago de su reintegro al Tesoro; solo para gastos en el extranjero puede el Consejo de Ministros acordar su aplicación a gastos del ejercicio siguiente.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 79.3 LGP', 'En todo caso, la cantidad no invertida de los libramientos en el ejercicio en que se aprobaran los mismos, será justificada mediante carta de pago demostrativa de su reintegro al tesoro público por el cajero pagador correspondiente.', null, '09e9733a1da1ef1ecfd3c32b9af89a7ec179bc7805431bf678707b3fe926ca18', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '09e9733a1da1ef1ecfd3c32b9af89a7ec179bc7805431bf678707b3fe926ca18')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Mediante su aplicación a gastos del ejercicio siguiente, sin necesidad de acuerdo alguno.', false), ('B', 'Mediante su incorporación automática al anticipo de caja fija de la unidad.', false), ('C', 'Mediante certificación del Interventor delegado de que los fondos permanecen en la cuenta de la Caja.', false), ('D', 'Mediante carta de pago demostrativa de su reintegro al Tesoro Público por el cajero pagador correspondiente.', true)) as v(label, body, ok)
)
