with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 151 de la Ley General Presupuestaria, ¿cuál de los siguientes gastos NO está sometido a fiscalización previa?', 'El art. 151 LGP excluye de fiscalización previa, entre otros, los gastos menores de 5.000 euros pagados por anticipo de caja fija y los gastos menores de 5.000 euros con fondos a justificar en territorio extranjero; los gastos de tracto sucesivo solo quedan excluidos una vez fiscalizado el período inicial.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 151 LGP', 'c) los gastos menores de 5.000 euros cuyo pago se realice mediante el procedimiento especial de anticipo de caja fija, regulado en el artículo 78 de esta Ley;', null, '8d4dc2c5c7ebb4da9792336c9f7494429cbe00e925d2e5260e39225c1f79fa78', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8d4dc2c5c7ebb4da9792336c9f7494429cbe00e925d2e5260e39225c1f79fa78')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los gastos menores de 12.000 euros cuyo pago se realice mediante el procedimiento especial de anticipo de caja fija.', false), ('B', 'Cualquier gasto que se pague mediante libramiento a justificar en territorio nacional.', false), ('C', 'Los gastos menores de 5.000 euros cuyo pago se realice mediante el procedimiento especial de anticipo de caja fija.', true), ('D', 'Los gastos de primer período de los contratos de tracto sucesivo.', false)) as v(label, body, ok)
)
