  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 177 de la Ley General Presupuestaria, no justificar la inversión de los fondos librados como anticipos de caja fija o como pagos a justificar:', 'El art. 177.1.e) LGP tipifica como infracción no justificar la inversión de los fondos de los arts. 78 y 79 LGP y de la Ley General de Subvenciones, lo que puede generar la obligación de indemnizar del art. 176.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 177.1.e) LGP', 'e) No justificar la inversión de los fondos a los que se refieren los artículos 78 y 79 de esta ley y la Ley General de Subvenciones.', null, '57cdd922738d03e675a9a4bed616d039b4f3d1adad11ab72bfd44e669369b9b0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '57cdd922738d03e675a9a4bed616d039b4f3d1adad11ab72bfd44e669369b9b0')
  returning id
), o as (
