with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 77 de la Ley General Presupuestaria, el pago realizado por error material, aritmético o de hecho en favor de persona en quien no concurra derecho alguno de cobro frente a la Administración se denomina:', 'El art. 77.1 LGP define el pago indebido; su perceptor está obligado a restituirlo y el órgano que cometió el error debe disponer de oficio su restitución.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 77.1 LGP', 'A los efectos de esta Ley se entiende por pago indebido el que se realiza por error material, aritmético o de hecho, en favor de persona en quien no concurra derecho alguno de cobro frente a la Administración con respecto a dicho pago o en cuantía que excede de la consignada en el acto o documento que reconoció el derecho del acreedor.', null, 'a057e05e9bc4e0012a52c614e34c323947dd3953fd02117915fda2377fdf3185', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a057e05e9bc4e0012a52c614e34c323947dd3953fd02117915fda2377fdf3185')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Pago a justificar.', false), ('B', 'Pago indebido.', true), ('C', 'Pago aplazado.', false), ('D', 'Pago a cuenta.', false)) as v(label, body, ok)
)
