insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 725/1989, de 16 de junio, sobre anticipos de Caja fija (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-55-pagos', 'V.5 Gastos y pagos: anticipos de caja fija y pagos a justificar') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-55-pagos' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una Caja pagadora con anticipo de caja fija recibe varias facturas. Según el artículo 1 del Real Decreto 725/1989, ¿cuál de los siguientes gastos es de los que, por su carácter periódico o repetitivo, pueden atenderse con anticipos de caja fija?', 'El art. 1 del RD 725/1989 limita los anticipos de caja fija a gastos periódicos o repetitivos que se aplican al capítulo de gastos corrientes en bienes y servicios, como dietas, locomoción, material no inventariable o conservación; no cubren inversiones, subvenciones ni gastos de personal.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441'), 'Art. 1 RD 725/1989', 'Se entienden por anticipos de Caja fija las provisiones de fondos de carácter extrapresupuestario y permanente que se realicen a Pagadurías, Cajas y Habilitaciones para la atención inmediata y posterior aplicación al capítulo de gastos corrientes en bienes y servicios del presupuesto del año en que se realicen, de gastos periódicos o repetitivos, como los referentes a dietas, gastos de locomoción, material no inventariable, conservación, tracto sucesivo y otros de similares características.', null, '858badc3fffdba4ba854e1aa2646551b9c6e140ed097034cef581d70e334b316', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '858badc3fffdba4ba854e1aa2646551b9c6e140ed097034cef581d70e334b316')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La adquisición de un edificio para una oficina periférica.', false), ('B', 'La concesión de una subvención nominativa a una fundación.', false), ('C', 'Las retribuciones básicas de la nómina mensual del personal funcionario.', false), ('D', 'Las dietas y gastos de locomoción de un funcionario en comisión de servicio.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El cajero pagador de una unidad con anticipo de caja fija recibe una factura de 6.200 euros por la reparación de una fotocopiadora. Según el artículo 2.3 del Real Decreto 725/1989, ¿puede abonarla con cargo al anticipo?', 'El art. 2.3 del RD 725/1989 prohíbe pagos individualizados con cargo al anticipo superiores a 5.000 euros (salvo teléfono, energía eléctrica, combustibles e indemnizaciones por razón del servicio) y prohíbe fraccionar un único gasto en varios pagos.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441'), 'Art. 2.3 RD 725/1989', 'no podrán realizarse con cargo al anticipo de caja fija pagos individualizados superiores a 5.000 euros (831.930 pesetas), excepto los destinados a gastos de teléfono, energía eléctrica, combustibles o indemnizaciones por razón del servicio. A efectos de aplicación de estos límites, no podrán acumularse en un solo justificante pagos que se deriven de diversos gastos, ni fraccionarse un único gasto en varios pagos.', null, '920595f33e2fcb86b90460eaaf1cbfcd1041013916247e56c3f3d30d8591b82d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '920595f33e2fcb86b90460eaaf1cbfcd1041013916247e56c3f3d30d8591b82d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sí, porque el límite de los pagos individualizados con cargo al anticipo es de 12.000 euros.', false), ('B', 'Sí, siempre que fraccione el gasto en dos pagos inferiores a 5.000 euros.', false), ('C', 'No, porque no pueden realizarse con cargo al anticipo pagos individualizados superiores a 600 euros.', false), ('D', 'No, porque no pueden realizarse con cargo al anticipo pagos individualizados superiores a 5.000 euros, salvo los gastos de teléfono, energía eléctrica, combustibles o indemnizaciones por razón del servicio.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2.3 del Real Decreto 725/1989, cuando se haya establecido el sistema de anticipos de caja fija en un ministerio, no podrán tramitarse libramientos aplicados al presupuesto a favor de perceptores directos, salvo los de reposición del anticipo, por importe inferior a:', 'El art. 2.3 del RD 725/1989 impide los libramientos a perceptores directos inferiores a 600 euros con imputación a los conceptos atendibles por caja fija; esos pagos deben hacerse a través del anticipo.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441'), 'Art. 2.3 RD 725/1989', 'Cuando el sistema de anticipos de caja fija se haya establecido en un Ministerio u Organismo autónomo, no podrán tramitarse libramientos aplicados al presupuesto a favor de perceptores directos, excepto los destinados a reposición del anticipo, por importe inferior a 600 euros (99.832 pesetas), con imputación a los conceptos a que se refiere el artículo anterior.', null, '4f67c85aff19b6f8abc5e7856d9ea76999452dd78f7bab6c0bd3a5d60cd047a9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4f67c85aff19b6f8abc5e7856d9ea76999452dd78f7bab6c0bd3a5d60cd047a9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '600 euros.', true), ('B', '5.000 euros.', false), ('C', '3.000 euros.', false), ('D', '1.000 euros.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 del Real Decreto 725/1989, los acuerdos de distribución de los anticipos de caja fija por Cajas pagadoras y sus modificaciones habrán de ser objeto de:', 'El art. 3.2 del RD 725/1989 exige informe favorable del Interventor delegado, limitado a comprobar que se respeta el tope del 7 %.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441'), 'Art. 3.2 RD 725/1989', 'Los citados acuerdos habrán de ser objeto de informe favorable del Interventor delegado respectivo, circunscrito a que se respete el citado límite del 7 por 100.', null, 'dcac92150b1b551a1c2fd833da02ebcbe8f0cf1a036d29ed4714eb4b7c7b4dd8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'dcac92150b1b551a1c2fd833da02ebcbe8f0cf1a036d29ed4714eb4b7c7b4dd8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Informe favorable del Interventor delegado respectivo, circunscrito a que se respete el límite del 7 por 100.', true), ('B', 'Autorización previa del Ministro de Hacienda.', false), ('C', 'Fiscalización previa plena del Tribunal de Cuentas.', false), ('D', 'Aprobación por el Consejo de Ministros.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 6 del Real Decreto 725/1989, las disposiciones de fondos de las cuentas de los anticipos de caja fija se efectuarán, con carácter ordinario:', 'El art. 6.1 del RD 725/1989 exige cheques nominativos o transferencias con firmas mancomunadas; la tarjeta bancaria solo cabe de manera excepcional y justificada (art. 6.3).', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441'), 'Art. 6.1 RD 725/1989', 'Las disposiciones de fondos de las cuentas a que se refiere el artículo 4.° se efectuarán mediante cheques nominativos o transferencias bancarias, autorizados con las firmas mancomunadas del Cajero pagador y del funcionario que designe el Jefe de la Unidad Administrativa a la que esté adscrita la Caja pagadora o de los sustitutos de los mismos.', 'La mención de la tarjeta bancaria en la explicación procede del art. 6.3, añadido por el RD 813/2026, de 7 de octubre (BOE-A-2026-20915); conviene confirmar que la orden ministerial de desarrollo no altera el régimen ordinario del art. 6.1.', '89ca5b9dbea9f4f12c21690206a26c02b12110ae97615becdb4e8649b08c900a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '89ca5b9dbea9f4f12c21690206a26c02b12110ae97615becdb4e8649b08c900a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Mediante cheques al portador firmados únicamente por el Cajero pagador.', false), ('B', 'Mediante cheques nominativos o transferencias bancarias, autorizados con las firmas mancomunadas del Cajero pagador y del funcionario que designe el Jefe de la Unidad Administrativa.', true), ('C', 'Mediante tarjeta bancaria, con la sola firma del Jefe de la Unidad Administrativa.', false), ('D', 'Mediante transferencias bancarias autorizadas por el Interventor delegado.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 7 del Real Decreto 725/1989, los Cajeros pagadores rendirán cuentas por los gastos atendidos con anticipos de caja fija:', 'El art. 7.1 del RD 725/1989 obliga a rendir cuentas cuando lo aconsejen las necesidades de reposición y, en todo caso, en diciembre. Las primeras quincenas de enero, abril, julio y octubre son las fechas mínimas de los estados de situación de Tesorería (art. 9.1).', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441'), 'Art. 7.1 RD 725/1989', 'Los Cajeros pagadores rendirán cuentas por los gastos atendidos con anticipos de Caja fija a medida que sus necesidades de tesorería aconsejen la reposición de los fondos utilizados y, necesariamente, en el mes de diciembre de cada año.', null, '7a91e541603050fb6c107429b629281acfeae2f49e6a6444a16134414f6ec755', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7a91e541603050fb6c107429b629281acfeae2f49e6a6444a16134414f6ec755')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Únicamente al cierre del ejercicio, en el mes de diciembre.', false), ('B', 'Trimestralmente, en las primeras quincenas de enero, abril, julio y octubre.', false), ('C', 'A medida que sus necesidades de tesorería aconsejen la reposición de los fondos utilizados y, necesariamente, en el mes de diciembre de cada año.', true), ('D', 'En el plazo de tres meses desde la percepción de los fondos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Intervención delegada examina una cuenta justificativa de anticipo de caja fija y emite un informe en el que hace constar anomalías. Según el artículo 7.4 del Real Decreto 725/1989, el órgano gestor realizará las alegaciones que estime oportunas y, en su caso, las subsanará:', 'El art. 7.4 del RD 725/1989 concede al órgano gestor quince días para alegar y subsanar, dejando constancia en la cuenta antes de enviarla al Tribunal de Cuentas, y otros quince días para dar cuenta al Interventor.', 'age_adm_55_pagos', (select id from public.topics where slug = 'age-adm-55-pagos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441'), 'Art. 7.4 RD 725/1989', 'Caso de que en el informe se hagan constar defectos o anomalías, el Órgano gestor, en un plazo de quince días, realizará las alegaciones que estime oportunas, y, en su caso, las subsanará, dejando constancia de ello en la cuenta, antes de su remisión al Tribunal de Cuentas.', null, 'f1afdfde1e9f94baf84bff192390f8dfd413112b3b6d26536239c822d26dcf7d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f1afdfde1e9f94baf84bff192390f8dfd413112b3b6d26536239c822d26dcf7d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
