with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 100 de la Ley 9/2017, de Contratos del Sector Público, el límite máximo de gasto que en virtud del contrato puede comprometer el órgano de contratación, incluido el IVA salvo disposición en contrario, se denomina:', 'El art. 100.1 LCSP define el presupuesto base de licitación como el límite máximo de gasto, IVA incluido; el valor estimado (art. 101) se calcula sin IVA.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 100.1 LCSP', 'A los efectos de esta Ley, por presupuesto base de licitación se entenderá el límite máximo de gasto que en virtud del contrato puede comprometer el órgano de contratación, incluido el Impuesto sobre el Valor Añadido, salvo disposición en contrario.', null, '3a7d573bb82ca4a47d4dd23cbf208cc775e4c317a03b83349d97e705bcb34f20', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3a7d573bb82ca4a47d4dd23cbf208cc775e4c317a03b83349d97e705bcb34f20')
