with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un órgano de contratación calcula el valor estimado de un contrato de servicios de dos años prorrogable por otro año. Según el artículo 101 de la Ley 9/2017, debe tomar:', 'El art. 101 LCSP ordena tomar, en obras, suministros y servicios, el importe total pagadero sin IVA y computar, entre otros conceptos, cualquier forma de opción eventual y las eventuales prórrogas.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 101.1.a) y 101.2.a) LCSP', 'a) En el caso de los contratos de obras, suministros y servicios, el órgano de contratación tomará el importe total, sin incluir el Impuesto sobre el Valor Añadido, pagadero según sus estimaciones. […] a) Cualquier forma de opción eventual y las eventuales prórrogas del contrato.', null, 'efdd8a871668d52f68e6439f2e3d7f9079cfdf262ef8c73384d97ac85de4bea3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'efdd8a871668d52f68e6439f2e3d7f9079cfdf262ef8c73384d97ac85de4bea3')
  returning id
), o as (
