with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 102.8 de la Ley 9/2017, en los contratos de las Administraciones Públicas el pago aplazado del precio:', 'El art. 102.8 LCSP prohíbe el pago aplazado del precio en los contratos de las Administraciones Públicas, con las excepciones del arrendamiento financiero, el arrendamiento con opción de compra y los casos autorizados expresamente por ley.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 102.8 LCSP', 'Se prohíbe el pago aplazado del precio en los contratos de las Administraciones Públicas, excepto en los supuestos en que el sistema de pago se establezca mediante la modalidad de arrendamiento financiero o de arrendamiento con opción de compra, así como en los casos en que esta u otra Ley lo autorice expresamente.', null, '6ac25d9ff04a47adcfc187870ef0424f3bae55e60bc18ba85b4fb8273b8cde4a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6ac25d9ff04a47adcfc187870ef0424f3bae55e60bc18ba85b4fb8273b8cde4a')
