with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 103.5 de la Ley 9/2017, salvo en los contratos de suministro de energía, la revisión periódica y predeterminada de precios, cuando proceda, tendrá lugar cuando el contrato:', 'El art. 103.5 LCSP exige haber ejecutado al menos el 20 % del importe y que haya pasado un año desde la formalización; el primer 20 % ejecutado y lo ejecutado en el primer año quedan excluidos de la revisión.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 103.5 LCSP', 'Salvo en los contratos de suministro de energía, cuando proceda, la revisión periódica y predeterminada de precios en los contratos del sector público tendrá lugar en los términos establecidos en este capítulo, cuando el contrato se hubiese ejecutado, al menos, en el 20 por ciento de su importe y hubiese transcurrido un año desde su formalización.', null, 'b04cda8b4a6c1735c0814186e5048179daabbcf95a1437038cbe3d82d6251f73', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b04cda8b4a6c1735c0814186e5048179daabbcf95a1437038cbe3d82d6251f73')
