  select 'De acuerdo con el artículo 103.2 de la Ley 9/2017, ¿cuál de los siguientes costes NO se considerará revisable en ningún caso?', 'El art. 103.2 LCSP excluye en todo caso de la revisión los costes asociados a las amortizaciones, los costes financieros, los gastos generales o de estructura y el beneficio industrial.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 103.2 LCSP', 'No se considerarán revisables en ningún caso los costes asociados a las amortizaciones, los costes financieros, los gastos generales o de estructura ni el beneficio industrial.', null, 'dfba27e0c5e75452c1c00c192114679f2f734e310d875198080e606598eca9f2', false
