with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 106 de la Ley 9/2017, cuando excepcionalmente se exija garantía provisional, su importe no podrá ser superior a:', 'El art. 106.2 LCSP limita la garantía provisional al 3 % del presupuesto base de licitación, sin IVA; el 5 % del precio final ofertado es la garantía definitiva (art. 107.1).', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 106.2 LCSP', 'En los casos en que el órgano de contratación haya acordado la exigencia de garantía provisional, en los pliegos de cláusulas administrativas particulares se determinará el importe de la misma, que no podrá ser superior a un 3 por 100 del presupuesto base de licitación del contrato, excluido el Impuesto sobre el Valor Añadido y el régimen de su devolución.', null, '0f10747928563866a2ca5dabfe3792971a1056e1a29d020fafe0da1b912c5cee', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0f10747928563866a2ca5dabfe3792971a1056e1a29d020fafe0da1b912c5cee')
