with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una empresa presenta la mejor oferta en una licitación de servicios con un precio final de 200.000 euros, IVA excluido. Según el artículo 107.1 de la Ley 9/2017, salvo exención justificada en el pliego, ¿qué garantía definitiva deberá constituir?', 'El art. 107.1 LCSP fija la garantía definitiva en el 5 % del precio final ofertado, excluido el IVA (5 % de 200.000 = 10.000 euros). Solo en casos especiales puede exigirse una complementaria hasta alcanzar el 10 % (art. 107.2).', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 107.1 LCSP', 'deberán constituir a disposición del órgano de contratación una garantía de un 5 por 100 del precio final ofertado por aquellos, excluido el Impuesto sobre el Valor Añadido.', null, 'c37533ffd864e6930edbf75b47b09f280e198b4399f829f28b35f368ce75b04a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c37533ffd864e6930edbf75b47b09f280e198b4399f829f28b35f368ce75b04a')
  returning id
), o as (
