with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 111.2 de la Ley 9/2017, aprobada la liquidación del contrato y transcurrido el plazo de garantía sin responsabilidades, el acuerdo de devolución de la garantía definitiva deberá adoptarse y notificarse al interesado en el plazo de:', 'El art. 111.2 LCSP fija dos meses; si la devolución se retrasa por causa imputable a la Administración, esta abonará el interés legal del dinero desde el vencimiento del plazo.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 111.2 LCSP', 'El acuerdo de devolución deberá adoptarse y notificarse al interesado en el plazo de dos meses desde la finalización del plazo de garantía.', null, 'bd8a85cd476bfd448bb02e7ecf4478c1c1f2aa362fcabed95504f56617bb11e6', false
