with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 116.3 de la Ley 9/2017, además de los pliegos, al expediente de contratación de una Administración Pública deberá incorporarse:', 'El art. 116.3 LCSP exige incorporar al expediente el certificado de existencia de crédito (o documento equivalente en entidades con presupuesto estimativo) y la fiscalización previa de la intervención, en los términos de la Ley General Presupuestaria.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 116.3 LCSP', 'Asimismo, deberá incorporarse el certificado de existencia de crédito o, en el caso de entidades del sector público estatal con presupuesto estimativo, documento equivalente que acredite la existencia de financiación, y la fiscalización previa de la intervención, en su caso, en los términos previstos en la Ley 47/2003, de 26 de noviembre, General Presupuestaria.', null, '2737d91bbc81c3a97491081e9d20ba38b5b94d7ef592c1014c83203988230f47', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2737d91bbc81c3a97491081e9d20ba38b5b94d7ef592c1014c83203988230f47')
