with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un contratista presenta en plazo su factura electrónica y la Administración aprueba la conformidad del servicio prestado. Según el artículo 198.4 de la Ley 9/2017, ¿en qué plazo debe la Administración abonar el precio para no incurrir en intereses de demora?', 'El art. 198.4 LCSP obliga a pagar en treinta días desde la aprobación de las certificaciones o documentos de conformidad; a partir de ahí se devengan intereses de demora e indemnización por costes de cobro (Ley 3/2004).', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 198.4 LCSP', 'La Administración tendrá la obligación de abonar el precio dentro de los treinta días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados', null, '47ab7234360090b988b08d4ad4ca12c51703264087109d0d1f756af0bbbf057d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '47ab7234360090b988b08d4ad4ca12c51703264087109d0d1f756af0bbbf057d')
  returning id
), o as (
