with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 198 de la Ley 9/2017, si la demora de la Administración en el pago fuese superior a seis meses, el contratista:', 'El art. 198 LCSP permite suspender el cumplimiento si la demora supera cuatro meses (con preaviso de un mes) y resolver el contrato con resarcimiento de perjuicios si supera seis meses.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 198.5-6 LCSP', '6. Si la demora de la Administración fuese superior a seis meses, el contratista tendrá derecho, asimismo, a resolver el contrato y al resarcimiento de los perjuicios que como consecuencia de ello se le originen.', null, 'e38139207c25bef4d7c439feb35566785d2f9405f4a151d50540e2eec2bd147b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e38139207c25bef4d7c439feb35566785d2f9405f4a151d50540e2eec2bd147b')
  returning id
), o as (
