with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 9.4 de la Ley 38/2003, General de Subvenciones, ¿cuál de los siguientes es un requisito para el otorgamiento de una subvención?', 'El art. 9.4 LGS exige la competencia del órgano concedente, la existencia de crédito adecuado y suficiente, la tramitación del procedimiento conforme a las normas, la fiscalización previa y la aprobación del gasto por el órgano competente.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 9.4 LGS', 'b) La existencia de crédito adecuado y suficiente para atender las obligaciones de contenido económico que se derivan de la concesión de la subvención.', null, 'f83ba584dbeff9a71332413de28c7aa1fefa0a7c5d44841e8f23f4af6e86c534', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f83ba584dbeff9a71332413de28c7aa1fefa0a7c5d44841e8f23f4af6e86c534')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La previa autorización del Tribunal de Cuentas.', false), ('B', 'La existencia de crédito adecuado y suficiente para atender las obligaciones de contenido económico que se derivan de la concesión.', true), ('C', 'La constitución de garantía por el beneficiario en todo caso.', false), ('D', 'La inscripción previa del beneficiario en el Registro Central de Personal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un ministerio va a convocar subvenciones en concurrencia competitiva por una cuantía total de 15 millones de euros. Según el artículo 10.2 de la Ley General de Subvenciones, la autorización previa del Consejo de Ministros:', 'El art. 10.2 LGS exige autorización previa del Consejo de Ministros (o de la Comisión Delegada para Asuntos Económicos si así se establece) para subvenciones de más de 12 millones; en concurrencia competitiva debe obtenerse antes de aprobar la convocatoria. La autorización no implica la aprobación del gasto.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 10.2 LGS', 'No obstante lo dispuesto en el apartado anterior, la concesión de subvenciones de cuantía superior a 12 millones de euros requerirá la previa autorización del Consejo de Ministros o, en el caso de que así lo establezca la normativa reguladora de la subvención, de la Comisión Delegada del Gobierno para Asuntos Económicos. En el caso de subvenciones concedidas en régimen de concurrencia competitiva, la autorización a que se refiere el párrafo anterior deberá obtenerse antes de la aprobación de la convocatoria cuya cuantía supere el citado límite.', null, 'f2ea76be205f0f6421de9bdd9369f346ea70937bba6937a3de813ac8d9deba92', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f2ea76be205f0f6421de9bdd9369f346ea70937bba6937a3de813ac8d9deba92')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es necesaria, pero puede obtenerse después de resolver la concesión.', false), ('B', 'No es necesaria, porque el límite que la exige es de 30 millones de euros.', false), ('C', 'Es necesaria y debe obtenerse antes de la aprobación de la convocatoria.', true), ('D', 'No es necesaria en el procedimiento de concurrencia competitiva.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 19 de la Ley General de Subvenciones, el importe de las subvenciones, aisladamente o en concurrencia con otras subvenciones, ayudas, ingresos o recursos:', 'El art. 19.3 LGS prohíbe la sobrefinanciación; si se produce, procede el reintegro del exceso con el interés de demora (art. 37.3).', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 19.3 LGS', 'El importe de las subvenciones en ningún caso podrá ser de tal cuantía que, aisladamente o en concurrencia con otras subvenciones, ayudas, ingresos o recursos, supere el coste de la actividad subvencionada.', null, '1eb7e4e6afd5218f08cb11fa69ed47d509f7a46ceb969be9331c23cffe60fd78', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1eb7e4e6afd5218f08cb11fa69ed47d509f7a46ceb969be9331c23cffe60fd78')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En ningún caso podrá ser de tal cuantía que supere el coste de la actividad subvencionada.', true), ('B', 'Podrá superar el coste de la actividad subvencionada si lo prevén las bases reguladoras.', false), ('C', 'No podrá superar el 50 por ciento del coste de la actividad subvencionada.', false), ('D', 'Podrá superar el coste de la actividad si el exceso procede de fondos de la Unión Europea.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Las bases reguladoras de una subvención no fijan el plazo de rendición de la cuenta justificativa. Según el artículo 30.2 de la Ley General de Subvenciones, el beneficiario deberá presentarla:', 'El art. 30.2 LGS establece, a falta de previsión en las bases, un plazo máximo de tres meses desde que finaliza el plazo para realizar la actividad.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 30.2 LGS', 'A falta de previsión de las bases reguladoras, la cuenta deberá incluir declaración de las actividades realizadas que han sido financiadas con la subvención y su coste, con el desglose de cada uno de los gastos incurridos, y su presentación se realizará, como máximo, en el plazo de tres meses desde la finalización del plazo para la realización de la actividad.', null, '5833bbcce7102658862944105357d22f88df80ec6f15a2b64895df0c6cbbca73', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5833bbcce7102658862944105357d22f88df80ec6f15a2b64895df0c6cbbca73')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Como máximo, en el plazo de seis meses desde el cobro de la subvención.', false), ('B', 'Como máximo, en el plazo de un mes desde la finalización de la actividad.', false), ('C', 'Antes de que finalice el año natural en que se concedió la subvención.', false), ('D', 'Como máximo, en el plazo de tres meses desde la finalización del plazo para la realización de la actividad.', true)) as v(label, body, ok)
)
