select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 34.4 de la Ley General de Subvenciones, los pagos anticipados, que suponen entregas de fondos con carácter previo a la justificación:', 'El art. 34.4 LGS admite pagos a cuenta y pagos anticipados, que deben preverse expresamente, junto con el régimen de garantías, en la normativa reguladora; no caben pagos anticipados a beneficiarios declarados en concurso salvo que haya adquirido eficacia un convenio, entre otros supuestos.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 34.4 LGS', 'También se podrán realizar pagos anticipados que supondrán entregas de fondos con carácter previo a la justificación, como financiación necesaria para poder llevar a cabo las actuaciones inherentes a la subvención. Dicha posibilidad y el régimen de garantías deberán preverse expresamente en la normativa reguladora de la subvención.', null, 'a76a9110e09334679376ecf8df9af5bf588ee57bc8c69443568804fbe18150c0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a76a9110e09334679376ecf8df9af5bf588ee57bc8c69443568804fbe18150c0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Pueden realizarse siempre que el beneficiario lo solicite y aporte un aval bancario.', false), ('B', 'Pueden realizarse aunque el beneficiario se halle declarado en concurso sin convenio eficaz.', false), ('C', 'Solo pueden realizarse si su posibilidad y el régimen de garantías se prevén expresamente en la normativa reguladora de la subvención.', true), ('D', 'Están prohibidos con carácter general en la Ley General de Subvenciones.', false)) as v(label, body, ok)
)
