select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 34.5 de la Ley General de Subvenciones, no podrá realizarse el pago de la subvención en tanto el beneficiario:', 'El art. 34.5 LGS impide el pago mientras el beneficiario no esté al corriente de sus obligaciones tributarias y con la Seguridad Social o sea deudor por reintegro.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 34.5 LGS', 'No podrá realizarse el pago de la subvención en tanto el beneficiario no se halle al corriente en el cumplimiento de sus obligaciones tributarias y frente a la Seguridad Social o sea deudor por resolución de procedencia de reintegro.', null, 'ff7adf882cd6dc19a3c81f3f700dc84b6070aa5a1abc7ad76160084932c541e6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ff7adf882cd6dc19a3c81f3f700dc84b6070aa5a1abc7ad76160084932c541e6')
  returning id
), o as (
