)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 38.2 de la Ley General de Subvenciones, el interés de demora aplicable en materia de subvenciones será, salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente:', 'El art. 38.2 LGS fija como interés de demora el interés legal del dinero incrementado en un 25 %, salvo que la Ley de Presupuestos establezca otro.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 38.2 LGS', 'El interés de demora aplicable en materia de subvenciones será el interés legal del dinero incrementado en un 25 por ciento, salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente.', 'La Ley de Presupuestos Generales del Estado de cada ejercicio suele fijar el tipo concreto del interés de demora; la pregunta solo recoge la regla supletoria del art. 38.2 LGS.', 'c7515a4374b14556f7d6f65bfb7ed9f1c7c93425e552fa8de29acfcfc965043f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c7515a4374b14556f7d6f65bfb7ed9f1c7c93425e552fa8de29acfcfc965043f')
  returning id
