)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un beneficiario debía presentar la justificación de una subvención antes del 31 de marzo de 2022 y no lo hizo; la Administración no ha realizado desde entonces ninguna actuación con su conocimiento formal. Según el artículo 39 de la Ley General de Subvenciones, el derecho de la Administración a reconocer o liquidar el reintegro prescribe:', 'El art. 39 LGS fija un plazo de prescripción de cuatro años, que con carácter general se computa desde el vencimiento del plazo de justificación, y que se interrumpe por actuaciones de la Administración con conocimiento formal del beneficiario.', 'age_adm_56_contratos_subvenciones', (select id from public.topics where slug = 'age-adm-56-contratos-subvenciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 39.1-2 LGS', '1. Prescribirá a los cuatro años el derecho de la Administración a reconocer o liquidar el reintegro. 2. Este plazo se computará, en cada caso: a) Desde el momento en que venció el plazo para presentar la justificación por parte del beneficiario o entidad colaboradora.', null, 'ea95dde93ae554d2cb472ce71eb3bffa2448d78a89f70a60168098e328c29d81', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ea95dde93ae554d2cb472ce71eb3bffa2448d78a89f70a60168098e328c29d81')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A los cinco años, contados desde la concesión de la subvención.', false), ('B', 'A los cuatro años, contados desde el pago de la subvención.', false), ('C', 'A los tres años, contados desde el momento en que venció el plazo para presentar la justificación.', false), ('D', 'A los cuatro años, contados desde el momento en que venció el plazo para presentar la justificación.', true)) as v(label, body, ok)
)
