insert into public.topics (slug, title) values ('age-adm-34-contratos', 'III.4 Los contratos del sector público') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-34-contratos' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Concepto y clases de contratos: calificación y contratos típicos (arts. 12-18 LCSP)"},{"n":"1.1","title":"Contratos administrativos y privados (arts. 25-26 LCSP)"},{"n":"1.2","title":"Necesidad, duración y prórroga (arts. 28-29 LCSP)"},{"n":"2","title":"Preparación: expediente de contratación y contratos menores (arts. 116-118 LCSP)"},{"n":"3","title":"Adjudicación: procedimientos, criterios, clasificación de ofertas y formalización (arts. 131, 145, 150, 153, 156 y 159 LCSP)"},{"n":"4","title":"Efectos y cumplimiento: prerrogativas, penalidades y demora (arts. 190-196 LCSP)"},{"n":"5","title":"La revisión de precios y otras alteraciones contractuales: modificación (arts. 103 y 203-205 LCSP)"},{"n":"6","title":"Extinción: cumplimiento, recepción y resolución (arts. 209-213 LCSP)"},{"n":"7","title":"Régimen de invalidez (arts. 38-40 LCSP)"},{"n":"8","title":"Recurso especial en materia de contratación (arts. 44 y 50 LCSP)"}]'::jsonb, '["Art. 12.1 Ley 9/2017: «Los contratos de obras, concesión de obras, concesión de servicios, suministro y servicios que celebren las entidades pertenecientes al sector público se calificarán de acuerdo con las normas contenidas en la presente sección.»","Art. 15.1 Ley 9/2017: «El contrato de concesión de servicios es aquel en cuya virtud uno o varios poderes adjudicadores encomiendan a título oneroso a una o varias personas, naturales o jurídicas, la gestión de un servicio cuya prestación sea de su titularidad o competencia, y cuya contrapartida venga constituida bien por el derecho a explotar los servicios objeto del contrato o bien por dicho derecho acompañado del de percibir un precio.»","Art. 25.2 Ley 9/2017: «Los contratos administrativos se regirán, en cuanto a su preparación, adjudicación, efectos, modificación y extinción, por esta Ley y sus disposiciones de desarrollo; supletoriamente se aplicarán las restantes normas de derecho administrativo y, en su defecto, las normas de derecho privado.»","Art. 29.4 Ley 9/2017: «Los contratos de suministros y de servicios de prestación sucesiva tendrán un plazo máximo de duración de cinco años, incluyendo las posibles prórrogas que en aplicación del apartado segundo de este artículo acuerde el órgano de contratación»","Art. 116.1 Ley 9/2017: «La celebración de contratos por parte de las Administraciones Públicas requerirá la previa tramitación del correspondiente expediente, que se iniciará por el órgano de contratación motivando la necesidad del contrato en los términos previstos en el artículo 28 de esta Ley y que deberá ser publicado en el perfil de contratante.»","Art. 118.1 Ley 9/2017: «Se consideran contratos menores los contratos de valor estimado inferior a 40.000 euros, cuando se trate de contratos de obras, o a 15.000 euros, cuando se trate de contratos de suministro o de servicios»","Art. 131.2 Ley 9/2017: «La adjudicación se realizará, ordinariamente utilizando una pluralidad de criterios de adjudicación basados en el principio de mejor relación calidad-precio, y utilizando el procedimiento abierto o el procedimiento restringido»","Art. 156.1 Ley 9/2017: «En el procedimiento abierto todo empresario interesado podrá presentar una proposición, quedando excluida toda negociación de los términos del contrato con los licitadores.»","Art. 153.3 Ley 9/2017: «Si el contrato es susceptible de recurso especial en materia de contratación conforme al artículo 44, la formalización no podrá efectuarse antes de que transcurran quince días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos.»","Art. 190 Ley 9/2017: «Dentro de los límites y con sujeción a los requisitos y efectos señalados en la presente Ley, el órgano de contratación ostenta la prerrogativa de interpretar los contratos administrativos, resolver las dudas que ofrezca su cumplimiento, modificarlos por razones de interés público, declarar la responsabilidad imputable al contratista a raíz de la ejecución del contrato, suspender la ejecución del mismo, acordar su resolución y determinar los efectos de esta.»","Art. 193.3 Ley 9/2017: «Cuando el contratista, por causas imputables al mismo, hubiere incurrido en demora respecto al cumplimiento del plazo total, la Administración podrá optar, atendidas las circunstancias del caso, por la resolución del contrato o por la imposición de las penalidades diarias en la proporción de 0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido.»","Art. 197 Ley 9/2017: «La ejecución del contrato se realizará a riesgo y ventura del contratista, sin perjuicio de lo establecido para el contrato de obras en el artículo 239.»","Art. 103.1 Ley 9/2017: «Los precios de los contratos del sector público solo podrán ser objeto de revisión periódica y predeterminada en los términos establecidos en este Capítulo.»","Art. 209 Ley 9/2017: «Los contratos se extinguirán por su cumplimiento o por resolución, acordada de acuerdo con lo regulado en esta Subsección 5.ª»","Art. 38 Ley 9/2017: «Los contratos celebrados por los poderes adjudicadores, incluidos los contratos subvencionados a que se refiere el artículo 23, serán inválidos: a) Cuando concurra en ellos alguna de las causas que los invalidan de conformidad con las disposiciones del derecho civil. b) Cuando lo sea alguno de sus actos preparatorios o del procedimiento de adjudicación, por concurrir en los mismos alguna de las causas de derecho administrativo a que se refieren los artículos siguientes. c) En aquellos casos en que la invalidez derive de la ilegalidad de su clausulado.»","Art. 50.1 Ley 9/2017: «El procedimiento de recurso se iniciará mediante escrito que deberá presentarse en el plazo de quince días hábiles.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902', null, null, null, null
