insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Derechos de los empleados públicos: individuales y ejercidos colectivamente (arts. 14-15 TREBEP)"},{"n":"2","title":"Deberes de los empleados públicos y Código de Conducta: principios éticos y de conducta (arts. 52-54 TREBEP)"},{"n":"3","title":"Provisión de puestos de trabajo: principios y procedimientos (arts. 78-81 TREBEP; arts. 36-38 RD 364/1995)"},{"n":"3.1","title":"El concurso: requisitos, méritos, comisiones de valoración, resolución y toma de posesión (arts. 39-50 RD 364/1995)"},{"n":"3.2","title":"La libre designación (arts. 51-58 RD 364/1995)"},{"n":"3.3","title":"Otras formas de provisión: redistribución y reasignación de efectivos, adscripción provisional y comisión de servicios (arts. 59-66 ter RD 364/1995)"},{"n":"4","title":"La carrera administrativa: concepto y modalidades; evaluación del desempeño (arts. 16-20 TREBEP)"},{"n":"4.1","title":"El grado personal y los intervalos de niveles (arts. 70-72 RD 364/1995)"},{"n":"5","title":"La promoción interna (art. 18 TREBEP; arts. 73-80 y disp. adic. 9.ª RD 364/1995)"}]'::jsonb, '["Art. 14.c) TREBEP: «c) A la progresión en la carrera profesional y promoción interna según principios constitucionales de igualdad, mérito y capacidad mediante la implantación de sistemas objetivos y transparentes de evaluación.»","Art. 52 TREBEP: «Los empleados públicos deberán desempeñar con diligencia las tareas que tengan asignadas y velar por los intereses generales con sujeción y observancia de la Constitución y del resto del ordenamiento jurídico»","Art. 53.5 TREBEP: «Se abstendrán en aquellos asuntos en los que tengan un interés personal, así como de toda actividad privada o interés que pueda suponer un riesgo de plantear conflictos de intereses con su puesto público.»","Art. 54.3 TREBEP: «Obedecerán las instrucciones y órdenes profesionales de los superiores, salvo que constituyan una infracción manifiesta del ordenamiento jurídico, en cuyo caso las pondrán inmediatamente en conocimiento de los órganos de inspección procedentes.»","Art. 78.1-2 TREBEP: «1. Las Administraciones Públicas proveerán los puestos de trabajo mediante procedimientos basados en los principios de igualdad, mérito, capacidad y publicidad. 2. La provisión de puestos de trabajo en cada Administración Pública se llevará a cabo por los procedimientos de concurso y de libre designación con convocatoria pública.»","Art. 36 RD 364/1995: «1. Los puestos de trabajo adscritos a funcionarios se proveerán de acuerdo con los procedimientos de concurso, que es el sistema normal de provisión, o de libre designación, de conformidad con lo que determinen las relaciones de puestos de trabajo en atención a la naturaleza de sus funciones. 2. Cuando las necesidades del servicio lo exijan, los puestos de trabajo podrán cubrirse mediante redistribución de efectivos o por reasignación de efectivos como consecuencia de un Plan de Empleo. 3. Temporalmente podrán ser cubiertos mediante comisión de servicios y adscripción provisional, en los supuestos previstos en este Reglamento.»","Art. 42.2 RD 364/1995: «El plazo de presentación de instancias será de quince días hábiles, contados a partir del siguiente al de la publicación de la convocatoria en el «Boletín Oficial del Estado».»","Art. 47.1 RD 364/1995: «El plazo para la resolución del concurso será de dos meses contados desde el día siguiente al de la finalización del de la presentación de solicitudes, salvo que la propia convocatoria establezca otro distinto.»","Art. 48.1 RD 364/1995: «El plazo para tomar posesión será de tres días hábiles si no implica cambio de residencia del funcionario, o de un mes si comporta cambio de residencia o el reingreso al servicio activo.»","Art. 58.1 RD 364/1995: «Los funcionarios nombrados para puestos de trabajo de libre designación podrán ser cesados con carácter discrecional. La motivación de esta resolución se referirá a la competencia para adoptarla.»","Art. 64.1 RD 364/1995: «Cuando un puesto de trabajo quede vacante podrá ser cubierto, en caso de urgente e inaplazable necesidad, en comisión de servicios de carácter voluntario, con un funcionario que reúna los requisitos establecidos para su desempeño en la relación de puestos de trabajo.»","Art. 16.2 TREBEP: «La carrera profesional es el conjunto ordenado de oportunidades de ascenso y expectativas de progreso profesional conforme a los principios de igualdad, mérito y capacidad.»","Art. 16.3.a)-b) TREBEP: «a) Carrera horizontal, que consiste en la progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo […] b) Carrera vertical, que consiste en el ascenso en la estructura de puestos de trabajo por los procedimientos de provisión establecidos en el capítulo III del título V de este Estatuto.»","Art. 70.1-2 RD 364/1995: «1. Los puestos de trabajo se clasifican en 30 niveles. 2. Todos los funcionarios de carrera adquirirán un grado personal por el desempeño de uno o más puestos del nivel correspondiente durante dos años continuados o tres con interrupción»","Art. 73 RD 364/1995: «La promoción interna consiste en el ascenso desde Cuerpos o Escalas de un Grupo de titulación a otro del inmediato superior o en el acceso a Cuerpos o Escalas del mismo Grupo de titulación.»","Art. 76 RD 364/1995: «Para participar en pruebas de promoción interna los funcionarios deberán tener una antigüedad de, al menos, dos años en el Cuerpo o Escala a que pertenezcan el día de la finalización del plazo de presentación de solicitudes de participación y poseer la titulación y el resto de los requisitos establecidos con carácter general para el acceso al Cuerpo o Escala en el que aspiran a ingresar.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729', null, null, null, 'Otras normas citadas: TREBEP (https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719)'
