insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Las incompatibilidades: principios generales y ámbito de aplicación (arts. 1-2 Ley 53/1984)"},{"n":"2","title":"Actividades públicas: segundo puesto, cargos electivos, límites retributivos y autorización (arts. 3-10 Ley 53/1984)"},{"n":"3","title":"Actividades privadas: prohibiciones y reconocimiento de compatibilidad (arts. 11-15 Ley 53/1984)"},{"n":"4","title":"Disposiciones comunes: complemento específico, registro, actividades exceptuadas e incumplimiento (arts. 16-20 Ley 53/1984)"},{"n":"5","title":"Régimen disciplinario: responsabilidad y principios de la potestad disciplinaria (arts. 93-94 TREBEP)"},{"n":"6","title":"Faltas disciplinarias: muy graves, graves y leves (art. 95 TREBEP)"},{"n":"7","title":"Sanciones y prescripción (arts. 96-97 TREBEP)"},{"n":"8","title":"Procedimiento disciplinario y medidas provisionales (art. 98 TREBEP)"}]'::jsonb, '["Art. 1.1 Ley 53/1984: «El personal comprendido en el ámbito de aplicación de esta Ley no podrá compatibilizar sus actividades con el desempeño, por sí o mediante sustitución, de un segundo puesto de trabajo, cargo o actividad en el sector público, salvo en los supuestos previstos en la misma.»","Art. 1.3 Ley 53/1984: «En cualquier caso, el desempeño de un puesto de trabajo por el personal incluido en el ámbito de aplicación de esta Ley será incompatible con el ejercicio de cualquier cargo, profesión o actividad, público o privado, que pueda impedir o menoscabar el estricto cumplimiento de sus deberes o comprometer su imparcialidad o independencia.»","Art. 3.1 Ley 53/1984: «Para el ejercicio de la segunda actividad será indispensable la previa y expresa autorización de compatibilidad, que no supondrá modificación de la jornada de trabajo y horario de los dos puestos y que se condiciona a su estricto cumplimiento en ambos. En todo caso la autorización de compatibilidad se efectuará en razón del interés público.»","Art. 10 Ley 53/1984: «Quienes accedan por cualquier título a un nuevo puesto del sector público que con arreglo a esta Ley resulte incompatible con el que vinieran desempeñando habrán de optar por uno de ellos dentro del plazo de toma de posesión. A falta de opción en el plazo señalado se entenderá que optan por el nuevo puesto, pasando a la situación de excedencia voluntaria en los que vinieran desempeñando.»","Art. 12.1.a) Ley 53/1984: «a) El desempeño de actividades privadas, incluidas las de carácter profesional, sea por cuenta propia o bajo la dependencia o al servicio de Entidades o particulares, en los asuntos en que esté interviniendo, haya intervenido en los dos últimos años o tenga que intervenir por razón del puesto público.»","Art. 14 Ley 53/1984: «El ejercicio de actividades profesionales, laborales, mercantiles o industriales fuera de las Administraciones Públicas requerirá el previo reconocimiento de compatibilidad.»","Art. 18 Ley 53/1984: «Todas las resoluciones de compatibilidad para desempeñar un segundo puesto o actividad en el sector público o el ejercicio de actividades privadas se inscribirán en los Registros de Personal correspondientes.»","Art. 19.b)-c) Ley 53/1984: «b) La dirección de seminarios o el dictado de cursos o conferencias en Centros oficiales destinados a la formación de funcionarios o profesorado, cuando no tenga carácter permanente o habitual ni supongan más de setenta y cinco horas al año, así como la preparación para el acceso a la función pública en los casos y forma que reglamentariamente se determine. c) La participación en Tribunales calificadores de pruebas selectivas para ingreso en las Administraciones Públicas.»","Art. 94.2 TREBEP: «La potestad disciplinaria se ejercerá de acuerdo con los siguientes principios: a) Principio de legalidad y tipicidad de las faltas y sanciones, a través de la predeterminación normativa o, en el caso del personal laboral, de los convenios colectivos. b) Principio de irretroactividad de las disposiciones sancionadoras no favorables y de retroactividad de las favorables al presunto infractor. c) Principio de proporcionalidad, aplicable tanto a la clasificación de las infracciones y sanciones como a su aplicación. d) Principio de culpabilidad. e) Principio de presunción de inocencia.»","Art. 95.1 TREBEP: «Las faltas disciplinarias pueden ser muy graves, graves y leves.»","Art. 95.2.c) y n) TREBEP: «c) El abandono del servicio, así como no hacerse cargo voluntariamente de las tareas o funciones que tienen encomendadas. […] n) El incumplimiento de las normas sobre incompatibilidades cuando ello dé lugar a una situación de incompatibilidad.»","Art. 96.1 TREBEP: «Por razón de las faltas cometidas podrán imponerse las siguientes sanciones: a) Separación del servicio de los funcionarios, que en el caso de los funcionarios interinos comportará la revocación de su nombramiento, y que sólo podrá sancionar la comisión de faltas muy graves.»","Art. 97.1 TREBEP: «Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses; las sanciones impuestas por faltas muy graves prescribirán a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves al año.»","Art. 98.1 TREBEP: «No podrá imponerse sanción por la comisión de faltas muy graves o graves sino mediante el procedimiento previamente establecido. La imposición de sanciones por faltas leves se llevará a cabo por procedimiento sumario con audiencia al interesado.»","Art. 98.3 TREBEP: «La suspensión provisional como medida cautelar en la tramitación de un expediente disciplinario no podrá exceder de 6 meses, salvo en caso de paralización del procedimiento imputable al interesado.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151', null, null, null, 'Otras normas citadas: TREBEP (https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719)'
  from public.topics t where t.slug = 'age-adm-46-incompatibilidades'
