insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Régimen especial de Seguridad Social de los Funcionarios Civiles del Estado: mecanismos de cobertura y campo de aplicación (arts. 1-3 RDLeg 4/2000)"},{"n":"2","title":"Las Clases Pasivas y la inclusión en el Régimen General de los funcionarios de nuevo ingreso desde 2011 (art. 2.2 RDLeg 4/2000; DA 3.ª LGSS)"},{"n":"3","title":"MUFACE: competencia, naturaleza y régimen de personal (arts. 4-6)"},{"n":"4","title":"Incorporación: afiliación, altas, bajas y mutualistas voluntarios (arts. 7-9)"},{"n":"5","title":"Cotización (art. 10)"},{"n":"6","title":"Contingencias y prestaciones (arts. 11-12)"},{"n":"7","title":"Asistencia sanitaria (arts. 13-17)"},{"n":"8","title":"Incapacidad temporal y riesgo durante el embarazo y la lactancia natural (arts. 18-22)"},{"n":"9","title":"Incapacidad permanente, gran invalidez y lesiones permanentes no invalidantes (arts. 23-28)"},{"n":"10","title":"Protección a la familia, servicios sociales y asistencia social (arts. 29-32)"},{"n":"11","title":"Régimen económico, patrimonial y de recursos (arts. 33-37)"}]'::jsonb, '["Art. 1 RDLeg 4/2000: «El Régimen especial de la Seguridad Social de los Funcionarios Civiles del Estado se rige por lo dispuesto en la presente Ley y en sus normas de aplicación y desarrollo, así como por la legislación de Clases Pasivas del Estado.»","Art. 2 RDLeg 4/2000: «1. Este Régimen especial queda integrado por los siguientes mecanismos de cobertura: a) El Régimen de Clases Pasivas del Estado, de acuerdo con sus normas específicas. b) El Régimen del Mutualismo Administrativo que se regula en la presente Ley. 2. No obstante lo anterior, los funcionarios de carrera de la Administración Civil del Estado que hayan ingresado a partir del 1 de enero de 2011, quedarán integrados en el Régimen General de la Seguridad Social a los exclusivos efectos de pensiones»","Art. 3.1 RDLeg 4/2000: «1. Quedan obligatoriamente incluidos en el campo de aplicación de este Régimen especial: a) Los funcionarios de carrera de la Administración Civil del Estado. b) Los funcionarios en prácticas que aspiren a incorporarse a Cuerpos de la Administración Civil del Estado, en la forma que reglamentariamente se determine.»","DA 3.ª.1 LGSS: «1. Con efectos de 1 de enero de 2011, el personal que se relaciona en el artículo 2.1 del texto refundido de la Ley de Clases Pasivas del Estado, aprobado por el Real Decreto Legislativo 670/1987, de 30 de abril, excepción hecha del comprendido en la letra i), estará obligatoriamente incluido, a los exclusivos efectos de lo dispuesto en dicha norma y en sus disposiciones de desarrollo, en el Régimen General de la Seguridad Social siempre que el acceso a la condición de que se trate se produzca a partir de aquella fecha.»","Art. 5.1 RDLeg 4/2000: «1. La Mutualidad General de Funcionarios Civiles del Estado es un organismo público con personalidad jurídica pública diferenciada, patrimonio y tesorería propios y autonomía de gestión»","Art. 7.1 RDLeg 4/2000: «1. Los funcionarios de carrera de la Administración Civil del Estado se incorporarán obligatoriamente, como mutualistas, a la Mutualidad General de Funcionarios Civiles del Estado, en el momento de la toma de posesión de su cargo, cuando adquieran la condición de funcionario, o sean rehabilitados en dicha condición, o reingresen al servicio activo»","Art. 8.2 RDLeg 4/2000: «2. Podrán mantener facultativamente la situación de alta como mutualistas voluntarios, con igualdad de derechos, los funcionarios a que se refieren los párrafos a), b) y c) del apartado 1 de este artículo, siempre que abonen exclusivamente a su cargo las cuotas correspondientes al funcionario y al Estado.»","Art. 10.4 RDLeg 4/2000: «4. La cuota mensual de cotización se obtendrá dividiendo por catorce la cantidad resultante de aplicar a la base de cotización anual, reducida en su caso, el tipo porcentual establecido y se abonará doblemente en los meses de junio y diciembre.»","Art. 11 RDLeg 4/2000: «Los mutualistas y, en su caso, los familiares o asimilados a su cargo quedan concretamente protegidos, de acuerdo con lo previsto en esta Ley, en las siguientes contingencias: a) Necesidad de asistencia sanitaria. b) Incapacidad temporal, derivada bien de enfermedad común o profesional, bien de accidente común o en acto de servicio o como consecuencia de él. c) Incapacidad permanente en los mismos supuestos del apartado anterior. d) Cargas familiares. e) Situación especial de incapacidad temporal por donación de órganos o tejidos para su trasplante, prevista en el artículo 18.»","Art. 17.1 RDLeg 4/2000: «1. La asistencia sanitaria se facilitará por la Mutualidad General de Funcionarios Civiles del Estado, bien directamente o por concierto con otras entidades o establecimientos públicos o privados. Estos conciertos se establecerán preferentemente con instituciones de la Seguridad Social.»","Art. 21.1 RDLeg 4/2000: «b) Desde el cuarto mes percibirá las retribuciones básicas, la prestación por hijo a cargo, en su caso, y un subsidio por incapacidad temporal a cargo de la Mutualidad General de Funcionarios Civiles del Estado, cuya cuantía, fija e invariable mientras dure la incapacidad, será la mayor de las dos cantidades siguientes: 1.ª El 80 por ciento de las retribuciones básicas (sueldo, trienios y grado, en su caso), incrementadas en la sexta parte de una paga extraordinaria, correspondientes al tercer mes de licencia. 2.ª El 75 por ciento de las retribuciones complementarias devengadas en el tercer mes de licencia.»","Art. 23.2 RDLeg 4/2000: «2. La incapacidad permanente se clasifica con arreglo a los siguientes grados: a) Incapacidad permanente parcial para la función habitual: es la que, sin alcanzar el grado de total, produce al funcionario una limitación para el desempeño de las funciones de su Cuerpo, Escala o plaza.»","Art. 26 RDLeg 4/2000: «La gran invalidez originará la jubilación del funcionario y dará derecho a una cantidad mensual equivalente al 50 por 100 de la pensión de jubilación que le corresponda con arreglo al Régimen de Clases Pasivas, destinada a remunerar a la persona encargada de su asistencia.»","Art. 29.1 RDLeg 4/2000: «1. Las prestaciones económicas de protección a la familia serán de pago periódico y de pago único. Las primeras corresponden a las prestaciones familiares por hijo a cargo y las segundas a ayudas económicas en los casos de parto múltiple y por nacimiento de hijo.»","Art. 33.1 RDLeg 4/2000: «1. Salvo las excepciones que puedan establecerse en las normas reguladoras de este Régimen especial de la Seguridad Social, el sistema financiero del mismo será de reparto y su cuota revisable periódicamente.»","Art. 37.1 RDLeg 4/2000: «1. Los actos y resoluciones del Director general de la Mutualidad General de Funcionarios Civiles del Estado no ponen fin a la vía administrativa, pudiéndose recurrir en alzada ante el Ministro de Administraciones Públicas.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140', null, null, null, 'Otras normas citadas: LGSS (https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724)'
  from public.topics t where t.slug = 'age-adm-47-muface'
