insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El personal laboral de las Administraciones públicas en el Régimen General (art. 136 LGSS)"},{"n":"2","title":"La acción protectora del sistema y del Régimen General (arts. 42 y 155 LGSS)"},{"n":"3","title":"Contingencias: accidente de trabajo, enfermedad profesional, accidente no laboral y enfermedad común (arts. 156-160 LGSS)"},{"n":"4","title":"Requisitos generales: afiliación, alta, situaciones asimiladas y carencia (arts. 165-166 LGSS)"},{"n":"5","title":"Incapacidad temporal (arts. 169-176 LGSS)"},{"n":"6","title":"Nacimiento y cuidado de menor, riesgo durante el embarazo y la lactancia natural (arts. 177-189 LGSS)"},{"n":"7","title":"Incapacidad permanente contributiva (arts. 193-200 LGSS)"},{"n":"8","title":"Jubilación contributiva (arts. 204-215 LGSS)"},{"n":"9","title":"Muerte y supervivencia (arts. 216-234 LGSS)"},{"n":"10","title":"Protección por desempleo: niveles contributivo y asistencial (arts. 262-280 LGSS)"}]'::jsonb, '["Art. 136.2.k) LGSS: «k) El personal civil no funcionario de las administraciones públicas y de las entidades y organismos vinculados o dependientes de ellas siempre que no estén incluidos en virtud de una ley especial en otro régimen obligatorio de previsión social.»","Art. 42.1 LGSS: «1. La acción protectora del sistema de la Seguridad Social comprenderá: a) La asistencia sanitaria en los casos de maternidad, de enfermedad común o profesional y de accidente, sea o no de trabajo. b) La recuperación profesional, cuya procedencia se aprecie en cualquiera de los casos que se mencionan en la letra anterior.»","Art. 155.1 LGSS: «1. La acción protectora del Régimen General será la establecida en el artículo 42, con excepción de la protección por cese de actividad y las prestaciones no contributivas.»","Art. 156.1 y 3 LGSS: «1. Se entiende por accidente de trabajo toda lesión corporal que el trabajador sufra con ocasión o por consecuencia del trabajo que ejecute por cuenta ajena. […] 3. Se presumirá, salvo prueba en contrario, que son constitutivas de accidente de trabajo las lesiones que sufra el trabajador durante el tiempo y en el lugar del trabajo.»","Art. 157 LGSS: «Se entenderá por enfermedad profesional la contraída a consecuencia del trabajo ejecutado por cuenta ajena en las actividades que se especifiquen en el cuadro que se apruebe por las disposiciones de aplicación y desarrollo de esta ley, y que esté provocada por la acción de los elementos o sustancias que en dicho cuadro se indiquen para cada enfermedad profesional.»","Art. 165.1 LGSS: «1. Para causar derecho a las prestaciones del Régimen General, las personas incluidas en su campo de aplicación habrán de cumplir, además de los requisitos particulares exigidos para acceder a cada una de ellas, el requisito general de estar afiliadas y en alta en dicho Régimen o en situación asimilada a la de alta al sobrevenir la contingencia o situación protegida, salvo disposición legal expresa en contrario.»","Art. 165.4 LGSS: «4. No se exigirán períodos previos de cotización para el derecho a las prestaciones derivadas de accidente, sea o no de trabajo, o de enfermedad profesional, salvo disposición legal expresa en contrario.»","Art. 169.1.a) LGSS: «a) Las debidas a enfermedad común o profesional y a accidente, sea o no de trabajo, mientras el trabajador reciba asistencia sanitaria de la Seguridad Social y esté impedido para el trabajo, con una duración máxima de trescientos sesenta y cinco días, prorrogables por otros 180 días cuando se presuma que durante ellos puede el trabajador ser dado de alta médica por curación.»","Art. 173.1 LGSS: «En caso de enfermedad común o de accidente no laboral, el subsidio se abonará a partir del cuarto día de baja en el trabajo, si bien desde el día cuarto al decimoquinto de baja, ambos inclusive, el subsidio estará a cargo del empresario.»","Art. 177 LGSS: «A efectos de la prestación por nacimiento y cuidado de menor prevista en esta sección, se consideran situaciones protegidas el nacimiento, la adopción, la guarda con fines de adopción y el acogimiento familiar»","Art. 186 LGSS: «La prestación correspondiente a la situación de riesgo durante el embarazo tendrá la naturaleza de prestación derivada de contingencias profesionales.»","DT 26.ª (art. 194.1 transitorio) LGSS: «1. La incapacidad permanente, cualquiera que sea su causa determinante, se clasificará con arreglo a los siguientes grados: a) Incapacidad permanente parcial para la profesión habitual. b) Incapacidad permanente total para la profesión habitual. c) Incapacidad permanente absoluta para todo trabajo. d) Gran incapacidad.»","Art. 205.1.b) LGSS: «b) Tener cubierto un período mínimo de cotización de quince años, de los cuales al menos dos deberán estar comprendidos dentro de los quince años inmediatamente anteriores al momento de causar el derecho.»","Art. 216.1 LGSS: «1. En caso de muerte, cualquiera que fuera su causa, cuando concurran los requisitos exigibles se reconocerán, según los supuestos, alguna o algunas de las prestaciones siguientes: a) Un auxilio por defunción. b) Una pensión vitalicia de viudedad. c) Una prestación temporal de viudedad. d) Una pensión de orfandad. e) Una pensión vitalicia o, en su caso, subsidio temporal en favor de familiares.»","Art. 263.1 LGSS: «1. La protección por desempleo se estructura en un nivel contributivo y en un nivel asistencial, ambos de carácter público y obligatorio.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724', null, null, null, null
  from public.topics t where t.slug = 'age-adm-49-seguridad-social'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
