insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El presupuesto: concepto y principios presupuestarios (art. 134 CE; arts. 26-27 y 32 LGP)"},{"n":"1.1","title":"Anualidad, universalidad, presupuesto bruto y especialidad (arts. 27, 34 y 42 LGP)"},{"n":"2","title":"Programación plurianual y ciclo presupuestario: escenarios, elaboración y prórroga (arts. 28-31 y 36-38 LGP)"},{"n":"3","title":"El presupuesto por programas: créditos y programas presupuestarios (art. 35 LGP)"},{"n":"4","title":"Estructura de los Presupuestos Generales del Estado: clasificaciones orgánica, por programas y económica (arts. 39-41 LGP)"},{"n":"5","title":"Los créditos presupuestarios: especialidad, especificación, limitación y temporalidad (arts. 42-49 LGP)"},{"n":"5.1","title":"Gastos plurianuales (art. 47 LGP)"},{"n":"5.2","title":"Fondo de Contingencia (art. 50 LGP)"},{"n":"6","title":"Modificaciones presupuestarias: transferencias, generaciones, ampliaciones, créditos extraordinarios y suplementos, e incorporaciones (arts. 51-59 LGP)"},{"n":"7","title":"Anticipos de Tesorería (art. 60 LGP)"},{"n":"8","title":"Competencias en materia de modificaciones de crédito (arts. 61-63 LGP)"}]'::jsonb, '["Art. 134.2 CE: «Los Presupuestos Generales del Estado tendrán carácter anual, incluirán la totalidad de los gastos e ingresos del sector público estatal y en ellos se consignará el importe de los beneficios fiscales que afecten a los tributos del Estado.»","Art. 27.4 Ley 47/2003: «Los derechos liquidados y las obligaciones reconocidas se aplicarán a los presupuestos por su importe íntegro, sin que puedan atenderse obligaciones mediante minoración de los derechos a liquidar o ya ingresados, salvo que la ley lo autorice de modo expreso.»","Art. 28.1 Ley 47/2003: «Los escenarios presupuestarios plurianuales determinarán los límites, referidos a los tres ejercicios siguientes, que la acción de gobierno debe respetar en los casos en que sus decisiones tengan incidencia presupuestaria.»","Art. 35.1 Ley 47/2003: «Son créditos presupuestarios cada una de las asignaciones individualizadas de gasto, que figuran en los presupuestos de los órganos y entidades a que se refiere el artículo 33.1.ª) de esta ley, puestas a disposición de los centros gestores para la cobertura de las necesidades para las que hayan sido aprobados.»","Art. 35.4 Ley 47/2003: «Constituye un programa de gasto del presupuesto anual el conjunto de créditos que, para el logro de los objetivos anuales que el mismo establezca, se ponen a disposición del gestor responsable de su ejecución.»","Art. 40.1 Ley 47/2003: «a) La clasificación orgánica que agrupará por secciones y servicios los créditos asignados a los distintos centros gestores de gasto»","Art. 42 Ley 47/2003: «Los créditos para gastos se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados por la Ley de Presupuestos o a la que resulte de las modificaciones aprobadas conforme a esta ley.»","Art. 43.1 Ley 47/2003: «En el presupuesto del Estado los créditos se especificarán a nivel de concepto, salvo los créditos destinados a gastos de personal y los gastos corrientes en bienes y servicios, que se especificarán a nivel de artículo y las inversiones reales a nivel de capítulo.»","Art. 47.2 Ley 47/2003: «El número de ejercicios a que pueden aplicarse los gastos no será superior a cuatro. El gasto que se impute a cada uno de los ejercicios posteriores no podrá exceder de la cantidad que resulte de aplicar al crédito inicial a que corresponda la operación los siguientes porcentajes: en el ejercicio inmediato siguiente, el 70 por ciento, en el segundo ejercicio, el 60 por ciento, y en los ejercicios tercero y cuarto, el 50 por ciento.»","Art. 49.2 Ley 47/2003: «Los créditos para gastos que en el último día del ejercicio presupuestario no estén afectados al cumplimiento de obligaciones ya reconocidas, quedarán anulados de pleno derecho, sin perjuicio de lo establecido en el artículo 58 de esta ley.»","Art. 51 Ley 47/2003: «La cuantía y finalidad de los créditos contenidos en los presupuestos de gastos sólo podrán ser modificadas durante el ejercicio, dentro de los límites y con arreglo al procedimiento establecido en los artículos siguientes, mediante: a) Transferencias. b) Generaciones. c) Ampliaciones. d) Créditos extraordinarios y suplementos de crédito. e) Incorporaciones.»","Art. 52.1 Ley 47/2003: «Las transferencias son traspasos de dotaciones entre créditos. Pueden realizarse entre los diferentes créditos del presupuesto incluso con la creación de créditos nuevos, con las siguientes restricciones: a) No podrán realizarse desde créditos para operaciones financieras al resto de los créditos, ni desde créditos para operaciones de capital a créditos para operaciones corrientes. b) No podrán realizarse entre créditos de distintas secciones presupuestarias.»","Art. 53.1 Ley 47/2003: «Las generaciones son modificaciones que incrementan los créditos como consecuencia de la realización de determinados ingresos no previstos o superiores a los contemplados en el presupuesto inicial.»","Art. 55.1 Ley 47/2003: «Cuando haya de realizarse con cargo al Presupuesto del Estado algún gasto que no pueda demorarse hasta el ejercicio siguiente, y no exista crédito adecuado o sea insuficiente y no ampliable el consignado y su dotación no resulte posible a través de las restantes figuras previstas en el artículo 51, deberá procederse a la tramitación de un crédito extraordinario o suplementario del inicialmente previsto.»","Art. 60.1 Ley 47/2003: «Con carácter excepcional, el Gobierno, a propuesta del Ministro de Economía, podrá conceder anticipos de Tesorería para atender gastos inaplazables, con el límite máximo en cada ejercicio del uno por ciento de los créditos autorizados al Estado por la Ley de Presupuestos Generales del Estado»","Art. 63.1 Ley 47/2003: «Los titulares de los distintos ministerios podrán autorizar, previo informe favorable de la Intervención Delegada competente en el ministerio o, en su caso, en las entidades a que se refiere el artículo 3.1 de esta ley, las siguientes modificaciones presupuestarias: a) Transferencias entre créditos de un mismo programa o entre programas de un mismo servicio»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', null, null, null, 'Otras normas citadas: CE (https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229)'
