insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El procedimiento de ejecución del presupuesto de gasto: fases (art. 73 LGP)"},{"n":"2","title":"Órganos competentes en la gestión de gastos (art. 74 LGP)"},{"n":"3","title":"Compromisos de gasto para ejercicios posteriores (arts. 47, 47 bis y disposición adicional decimonovena LGP)"},{"n":"4","title":"La ordenación del pago: concepto y competencia (arts. 75 y 107 LGP)"},{"n":"5","title":"Realización del pago: modos y perceptores (arts. 75.3 y 110 LGP)"},{"n":"6","title":"Control del gasto público: control externo e interno (art. 140 LGP)"},{"n":"6.1","title":"Clases de control interno: función interventora, control financiero permanente y auditoría pública (arts. 142-166 LGP)"},{"n":"6.2","title":"El control de legalidad: fiscalización previa, reparos, discrepancias y omisión de fiscalización (arts. 148-156 LGP)"},{"n":"7","title":"El Tribunal de Cuentas y la Cuenta General del Estado (art. 136 CE; arts. 131-132 LGP)"},{"n":"8","title":"Responsabilidades por infracción de la Ley General Presupuestaria (arts. 176-180 LGP)"}]'::jsonb, '["Art. 73.1 Ley 47/2003: «a) Aprobación del gasto. b) Compromiso de gasto. c) Reconocimiento de la obligación. d) Ordenación del pago. e) Pago material.»","Art. 74.1 Ley 47/2003: «Corresponde a los Ministros y a los titulares de los demás órganos del Estado con dotaciones diferenciadas en los Presupuestos Generales del Estado aprobar y comprometer los gastos propios de sus presupuestos, salvo los casos reservados por la Ley a la competencia del Consejo de Ministros, así como reconocer las obligaciones económicas correspondientes, e interesar del Ordenador general de pagos del Estado la realización de los correspondientes pagos.»","Art. 47.1 Ley 47/2003: «Podrán adquirirse compromisos de gastos que hayan de extenderse a ejercicios posteriores a aquel en que se autoricen, siempre que su ejecución se inicie en el propio ejercicio y que no superen los límites y anualidades fijados en el número siguiente.»","Art. 75.1 Ley 47/2003: «Bajo la superior autoridad del Ministro de Economía, competen al Director General del Tesoro y Política Financiera las funciones de Ordenador General de pagos del Estado.»","Art. 75.3 Ley 47/2003: «Las órdenes de pago se expedirán a favor del acreedor que figura en la correspondiente propuesta de pago»","Art. 107 Ley 47/2003: «El Ordenador de Pagos aplicará criterios objetivos en la expedición de las órdenes de pago, tales como la fecha de recepción, el importe de la operación, la aplicación presupuestaria y la forma de pago, entre otros.»","Art. 110 Ley 47/2003: «los ingresos y los pagos de la Administración General del Estado y sus organismos autónomos podrán realizarse mediante transferencia bancaria, cheque, efectivo o cualesquiera otros medios de pago, sean o no bancarios.»","Art. 140 Ley 47/2003: «1. En su condición de supremo órgano fiscalizador de las cuentas y de la gestión económica del Estado y del sector público, corresponde al Tribunal de Cuentas el control externo del sector público estatal, en los términos establecidos en la Constitución, en su ley orgánica y en las demás leyes que regulen su competencia. 2. La Intervención General de la Administración del Estado ejercerá en los términos previstos en esta ley el control interno de la gestión económica y financiera del sector público estatal, con plena autonomía respecto de las autoridades y demás entidades cuya gestión controle.»","Art. 142.2 Ley 47/2003: «El control se realizará mediante el ejercicio de la función interventora, el control financiero permanente y la auditoría pública, a que se refieren los capítulos II, III y IV de este título.»","Art. 148 Ley 47/2003: «La función interventora tiene por objeto controlar, antes de que sean aprobados, los actos del sector público estatal que den lugar al reconocimiento de derechos o a la realización de gastos, así como los ingresos y pagos que de ellos se deriven, y la inversión o aplicación en general de sus fondos públicos, con el fin de asegurar que su gestión se ajuste a las disposiciones aplicables en cada caso.»","Art. 154.1 Ley 47/2003: «Si la Intervención, al realizar la fiscalización o intervención, se manifiesta en desacuerdo con el contenido de los actos examinados o con el procedimiento seguido para su adopción, deberá formular sus reparos por escrito, con cita de los preceptos legales en los que sustente su criterio. La formulación del reparo suspenderá la tramitación del expediente hasta que sea solventado»","Art. 157 Ley 47/2003: «El control financiero permanente se ejercerá en los órganos y entidades establecidos en el artículo siguiente y tendrá por objeto la verificación de una forma continua realizada a través de la correspondiente intervención delegada, de la situación y el funcionamiento de las entidades del sector público estatal en el aspecto económico-financiero»","Art. 162 Ley 47/2003: «La auditoría pública consistirá en la verificación, realizada con posterioridad y efectuada de forma sistemática, de la actividad económico-financiera del sector público estatal, mediante la aplicación de los procedimientos de revisión selectivos contenidos en las normas de auditoría e instrucciones que dicte la Intervención General de la Administración del Estado.»","Art. 136.1 CE: «El Tribunal de Cuentas es el supremo órgano fiscalizador de las cuentas y de la gestión económica de Estado, así como del sector público. Dependerá directamente de las Cortes Generales y ejercerá sus funciones por delegación de ellas en el examen y comprobación de la Cuenta General del Estado.»","Art. 132 Ley 47/2003: «El Tribunal de Cuentas, por delegación de las Cortes Generales, procederá al examen y comprobación de la Cuenta General del Estado dentro del plazo de seis meses a partir de la fecha en que las haya recibido. El Pleno, oído el Fiscal, dictará la declaración definitiva que le merezca para elevarla a las Cámaras con la oportuna propuesta, dando traslado al Gobierno.»","Art. 176 Ley 47/2003: «Las autoridades y demás personal al servicio de las entidades contempladas en el artículo 2 de esta ley que por dolo o culpa graves adopten resoluciones o realicen actos con infracción de las disposiciones de esta ley, estarán obligados a indemnizar a la Hacienda Pública estatal o, en su caso, a la respectiva entidad los daños y perjuicios que sean consecuencia de aquellos, con independencia de la responsabilidad penal o disciplinaria que les pueda corresponder.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', null, null, null, 'Otras normas citadas: CE (https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229)'
