insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Determinación de las cuantías y límites de los incrementos retributivos (art. 21 TREBEP)"},{"n":"2","title":"Retribuciones de los funcionarios: clasificación y pagas extraordinarias (art. 22 TREBEP)"},{"n":"2.1","title":"Retribuciones básicas: sueldo y trienios (art. 23 TREBEP)"},{"n":"2.2","title":"Retribuciones complementarias: factores (art. 24 TREBEP)"},{"n":"3","title":"Retribuciones de funcionarios interinos, en prácticas y del personal laboral (arts. 25-27 TREBEP)"},{"n":"4","title":"Retribuciones diferidas y deducción de retribuciones (arts. 29-30 TREBEP)"},{"n":"5","title":"Indemnizaciones por razón del servicio: supuestos y ámbito (art. 28 TREBEP; arts. 1-2 RD 462/2002)"},{"n":"6","title":"Comisiones de servicio: designación, duración, residencia eventual, dietas y gastos de viaje (arts. 3-19 RD 462/2002)"},{"n":"7","title":"Desplazamientos dentro del término municipal y traslados de residencia (arts. 20-26 RD 462/2002)"},{"n":"8","title":"Asistencias (arts. 27-33 RD 462/2002)"}]'::jsonb, '["Art. 21.1 TREBEP: «1. Las cuantías de las retribuciones básicas y el incremento de las cuantías globales de las retribuciones complementarias de los funcionarios, así como el incremento de la masa salarial del personal laboral, deberán reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos.»","Art. 22.2 TREBEP: «2. Las retribuciones básicas son las que retribuyen al funcionario según la adscripción de su cuerpo o escala a un determinado Subgrupo o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo, y por su antigüedad en el mismo. Dentro de ellas están comprendidas los componentes de sueldo y trienios de las pagas extraordinarias.»","Art. 22.3 TREBEP: «3. Las retribuciones complementarias son las que retribuyen las características de los puestos de trabajo, la carrera profesional o el desempeño, rendimiento o resultados alcanzados por el funcionario.»","Art. 22.4 TREBEP: «4. Las pagas extraordinarias serán dos al año, cada una por el importe de una mensualidad de retribuciones básicas y de la totalidad de las retribuciones complementarias, salvo aquéllas a las que se refieren los apartados c) y d) del artículo 24.»","Art. 23 TREBEP: «a) El sueldo asignado a cada Subgrupo o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo. b) Los trienios, que consisten en una cantidad, que será igual para cada Subgrupo o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo, por cada tres años de servicio.»","Art. 24 TREBEP: «a) La progresión alcanzada por el funcionario dentro del sistema de carrera administrativa. b) La especial dificultad técnica, responsabilidad, dedicación, incompatibilidad exigible para el desempeño de determinados puestos de trabajo o las condiciones en que se desarrolla el trabajo. c) El grado de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos. d) Los servicios extraordinarios prestados fuera de la jornada normal de trabajo.»","Art. 26 TREBEP: «Las Administraciones Públicas determinarán las retribuciones de los funcionarios en prácticas que, como mínimo, se corresponderán a las del sueldo del Subgrupo o Grupo, en el supuesto de que éste no tenga Subgrupo, en que aspiren a ingresar.»","Art. 30.1 TREBEP: «1. Sin perjuicio de la sanción disciplinaria que pueda corresponder, la parte de jornada no realizada dará lugar a la deducción proporcional de haberes, que no tendrá carácter sancionador.»","Art. 1.1 RD 462/2002: «a) Comisiones de servicio con derecho a indemnización. b) Desplazamientos dentro del término municipal por razón de servicio. c) Traslados de residencia. d) Asistencias por concurrencia a Consejos de Administración u Órganos Colegiados, por participación en tribunales de oposiciones y concursos y por la colaboración en centros de formación y perfeccionamiento del personal de las Administraciones públicas.»","Art. 5.1 RD 462/2002: «1. Toda comisión con derecho a indemnización, salvo casos excepcionales, no durará más de un mes en territorio nacional y de tres en el extranjero.»","Art. 9 RD 462/2002: «1. «Dieta» es la cantidad que se devenga diariamente para satisfacer los gastos que origina la estancia fuera de la residencia oficial en los casos previstos en el artículo 5 del presente Real Decreto.»","Art. 12.3 RD 462/2002: «c) En los días intermedios entre los de salida y regreso se percibirán dietas al 100 por 100.»","Art. 19.1 RD 462/2002: «1. El personal a quien se encomiende una comisión de servicio de las reguladas en el artículo 3 del presente Real Decreto tendrá derecho a percibir por adelantado el importe aproximado de las dietas, pluses, residencia eventual y gastos de viaje sin perjuicio de la devolución del anticipo, en la cuantía que proceda en su caso, una vez finalizada la comisión de servicios.»","Art. 23.3 RD 462/2002: «3. Los traslados que obedezcan a sanción impuesta al funcionario no darán derecho a indemnización.»","Art. 27.3 RD 462/2002: «3. Dichas cantidades en ningún caso podrán totalizar, para el conjunto de los tres tipos de asistencias, un importe por año natural superior al 50 por 100 de las retribuciones anuales, excluidas las de carácter personal derivadas de la antigüedad, que se perciban por el puesto de trabajo desempeñado.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', null, null, null, 'Otras normas citadas: RD 462/2002 (https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337)'
