insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Clasificación económica del gasto: operaciones corrientes, de capital y financieras (art. 40.1.c) LGP)"},{"n":"1.1","title":"Gastos para la compra de bienes y servicios y gastos de transferencias corrientes"},{"n":"1.2","title":"Gastos de inversión y transferencias de capital; inversiones con pago aplazado (arts. 47.2 y 48 LGP)"},{"n":"2","title":"Pagos: concepto y tipos. Pagos por obligaciones presupuestarias (arts. 73, 75 y 77 LGP)"},{"n":"3","title":"Anticipos de caja fija: concepto, límites y gestión (art. 78 LGP; RD 725/1989)"},{"n":"3.1","title":"Situación y disposición de los fondos (arts. 4 y 6 RD 725/1989)"},{"n":"3.2","title":"Reposición de fondos, rendición de cuentas y control (arts. 7-9 RD 725/1989)"},{"n":"4","title":"Pagos «a justificar» (art. 79 LGP)"},{"n":"5","title":"Justificación de libramientos y control: fiscalización e intervención (arts. 151 y 153 LGP)"},{"n":"6","title":"Responsabilidad por falta de justificación (arts. 177 y 182 LGP)"}]'::jsonb, '["Art. 40.1.c) Ley 47/2003: «En los créditos para operaciones corrientes se distinguirán los gastos de personal, los gastos corrientes en bienes y servicios, los gastos financieros y las transferencias corrientes. En los créditos para operaciones de capital se distinguirán las inversiones reales y las transferencias de capital.»","Art. 48.1 Ley 47/2003: «Podrá ser diferido el vencimiento de la obligación de pago del precio de compra de bienes inmuebles adquiridos directamente cuyo importe exceda de seis millones de euros, sin que, en ningún caso, el desembolso inicial a la firma de la escritura pueda ser inferior al 25 por ciento del precio»","Art. 77.1 Ley 47/2003: «A los efectos de esta Ley se entiende por pago indebido el que se realiza por error material, aritmético o de hecho, en favor de persona en quien no concurra derecho alguno de cobro frente a la Administración con respecto a dicho pago o en cuantía que excede de la consignada en el acto o documento que reconoció el derecho del acreedor.»","Art. 78.1 Ley 47/2003: «Se entienden por anticipos de caja fija las provisiones de fondos de carácter extrapresupuestario y permanente que se realicen a pagadurías, cajas y habilitaciones para la atención inmediata y posterior aplicación al capítulo de gastos corrientes en bienes y servicios del presupuesto del año en que se realicen, de gastos periódicos o repetitivos.»","Art. 78.3 Ley 47/2003: «En todo caso, la cuantía global de los anticipos de caja fija no podrá superar para cada ministerio u organismo autónomo el siete por ciento del total de créditos del capítulo destinado a gastos corrientes en bienes y servicios del presupuesto vigente en cada momento.»","Art. 1 RD 725/1989: «como los referentes a dietas, gastos de locomoción, material no inventariable, conservación, tracto sucesivo y otros de similares características.»","Art. 2.3 RD 725/1989: «no podrán realizarse con cargo al anticipo de caja fija pagos individualizados superiores a 5.000 euros (831.930 pesetas), excepto los destinados a gastos de teléfono, energía eléctrica, combustibles o indemnizaciones por razón del servicio.»","Art. 4.3 RD 725/1989: «Los fondos librados conforme a lo previsto en este Real Decreto tendrán, en todo caso, el carácter de fondos públicos y formarán parte integrante del Tesoro Público.»","Art. 7.1 RD 725/1989: «Los Cajeros pagadores rendirán cuentas por los gastos atendidos con anticipos de Caja fija a medida que sus necesidades de tesorería aconsejen la reposición de los fondos utilizados y, necesariamente, en el mes de diciembre de cada año.»","Art. 79.1 Ley 47/2003: «Cuando, excepcionalmente, no pueda aportarse la documentación justificativa de las obligaciones en el momento previsto en el apartado 4 del artículo 73, podrán tramitarse propuestas de pagos presupuestarios y librarse fondos con el carácter de a justificar. Asimismo, podrá procederse a la expedición de libramientos a justificar cuando los servicios y prestaciones a que se refieran hayan tenido o vayan a tener lugar en el extranjero.»","Art. 79.3 Ley 47/2003: «En todo caso, la cantidad no invertida de los libramientos en el ejercicio en que se aprobaran los mismos, será justificada mediante carta de pago demostrativa de su reintegro al tesoro público por el cajero pagador correspondiente.»","Art. 79.4 Ley 47/2003: «Los perceptores de estas órdenes de pago a justificar quedan obligados a rendir cuenta justificativa de la aplicación de las cantidades recibidas. El plazo de rendición de las cuentas será de tres meses, excepto las correspondientes a pagos de expropiaciones y pagos en el extranjero que podrán ser rendidas en el plazo de seis meses.»","Art. 79.6 Ley 47/2003: «En el curso de los dos meses siguientes a la fecha de aportación de los documentos justificativos a que se refieren los apartados anteriores de este artículo, se llevará a cabo la aprobación o reparo de la cuenta por la autoridad competente.»","Art. 151.c) Ley 47/2003: «c) los gastos menores de 5.000 euros cuyo pago se realice mediante el procedimiento especial de anticipo de caja fija, regulado en el artículo 78 de esta Ley;»","Art. 177.1.e) Ley 47/2003: «e) No justificar la inversión de los fondos a los que se refieren los artículos 78 y 79 de esta ley y la Ley General de Subvenciones.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', null, null, null, 'Otras normas citadas: RD 725/1989 (https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441)'
