insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 38/2003, de 17 de noviembre, General de Subvenciones (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-56-contratos-subvenciones', 'V.6 Gestión económica de los contratos y de las subvenciones') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-56-contratos-subvenciones' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Gestión económica de los contratos: presupuesto base de licitación, valor estimado y precio (arts. 100-102 LCSP)"},{"n":"2","title":"Revisión de precios (arts. 103-105 LCSP)"},{"n":"3","title":"Garantías: provisional y definitiva (arts. 106-111 LCSP)"},{"n":"4","title":"El expediente de gasto en la contratación: crédito, fiscalización y tramitación anticipada (arts. 116-117 LCSP)"},{"n":"5","title":"Pago del precio, abonos a cuenta y cesión de derechos de cobro (arts. 198-200 y 240 LCSP)"},{"n":"6","title":"Gestión económica de las subvenciones: concepto, principios y requisitos (arts. 2, 8 y 9 LGS)"},{"n":"7","title":"Órganos competentes y financiación de la actividad subvencionada (arts. 10 y 19 LGS)"},{"n":"8","title":"Justificación y gastos subvencionables (arts. 30-31 LGS)"},{"n":"9","title":"Aprobación del gasto y pago de la subvención (art. 34 LGS)"},{"n":"10","title":"Reintegro: causas, interés de demora y prescripción (arts. 37-39 y 42 LGS)"}]'::jsonb, '["Art. 100.1 Ley 9/2017: «A los efectos de esta Ley, por presupuesto base de licitación se entenderá el límite máximo de gasto que en virtud del contrato puede comprometer el órgano de contratación, incluido el Impuesto sobre el Valor Añadido, salvo disposición en contrario.»","Art. 102.1 Ley 9/2017: «Los contratos del sector público tendrán siempre un precio cierto, que se abonará al contratista en función de la prestación realmente ejecutada y de acuerdo con lo pactado. En el precio se entenderá incluido el importe a abonar en concepto de Impuesto sobre el Valor Añadido, que en todo caso se indicará como partida independiente.»","Art. 103.5 Ley 9/2017: «Salvo en los contratos de suministro de energía, cuando proceda, la revisión periódica y predeterminada de precios en los contratos del sector público tendrá lugar en los términos establecidos en este capítulo, cuando el contrato se hubiese ejecutado, al menos, en el 20 por ciento de su importe y hubiese transcurrido un año desde su formalización.»","Art. 107.1 Ley 9/2017: «deberán constituir a disposición del órgano de contratación una garantía de un 5 por 100 del precio final ofertado por aquellos, excluido el Impuesto sobre el Valor Añadido.»","Art. 116.3 Ley 9/2017: «Asimismo, deberá incorporarse el certificado de existencia de crédito o, en el caso de entidades del sector público estatal con presupuesto estimativo, documento equivalente que acredite la existencia de financiación, y la fiscalización previa de la intervención, en su caso, en los términos previstos en la Ley 47/2003, de 26 de noviembre, General Presupuestaria.»","Art. 198.4 Ley 9/2017: «La Administración tendrá la obligación de abonar el precio dentro de los treinta días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados»","Art. 240.1 Ley 9/2017: «A los efectos del pago, la Administración expedirá mensualmente, en los primeros diez días siguientes al mes al que correspondan, certificaciones que comprendan la obra ejecutada conforme a proyecto durante dicho período de tiempo»","Art. 2.1 Ley 38/2003: «Se entiende por subvención, a los efectos de esta ley, toda disposición dineraria realizada por cualesquiera de los sujetos contemplados en el artículo 3 de esta ley, a favor de personas públicas o privadas, y que cumpla los siguientes requisitos: a) Que la entrega se realice sin contraprestación directa de los beneficiarios.»","Art. 8.3 Ley 38/2003: «a) Publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación. b) Eficacia en el cumplimiento de los objetivos fijados por la Administración otorgante. c) Eficiencia en la asignación y utilización de los recursos públicos.»","Art. 10.2 Ley 38/2003: «la concesión de subvenciones de cuantía superior a 12 millones de euros requerirá la previa autorización del Consejo de Ministros»","Art. 19.3 Ley 38/2003: «El importe de las subvenciones en ningún caso podrá ser de tal cuantía que, aisladamente o en concurrencia con otras subvenciones, ayudas, ingresos o recursos, supere el coste de la actividad subvencionada.»","Art. 30.1 Ley 38/2003: «La justificación del cumplimiento de las condiciones impuestas y de la consecución de los objetivos previstos en el acto de concesión de la subvención se documentará de la manera que se determine reglamentariamente, pudiendo revestir la forma de cuenta justificativa del gasto realizado o acreditarse dicho gasto por módulos o mediante la presentación de estados contables, según se disponga en la normativa reguladora.»","Art. 34.1-3 Ley 38/2003: «Con carácter previo a la convocatoria de la subvención o a la concesión directa de la misma, deberá efectuarse la aprobación del gasto en los términos previstos en la Ley General Presupuestaria o en las normas presupuestarias de las restantes Administraciones públicas. 2. La resolución de concesión de la subvención conllevará el compromiso del gasto correspondiente. 3. El pago de la subvención se realizará previa justificación, por el beneficiario, de la realización de la actividad, proyecto, objetivo o adopción del comportamiento para el que se concedió en los términos establecidos en la normativa reguladora de la subvención.»","Art. 38.2 Ley 38/2003: «El interés de demora aplicable en materia de subvenciones será el interés legal del dinero incrementado en un 25 por ciento, salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente.»","Art. 39.1 Ley 38/2003: «Prescribirá a los cuatro años el derecho de la Administración a reconocer o liquidar el reintegro.»","Art. 42.4 Ley 38/2003: «El plazo máximo para resolver y notificar la resolución del procedimiento de reintegro será de 12 meses desde la fecha del acuerdo de iniciación.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977', null, null, null, 'Otras normas citadas: Ley 9/2017 (https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902)'
  from public.topics t where t.slug = 'age-adm-56-contratos-subvenciones'
